-- Medical-Surgical Care question bank: exactly 400 hand-written NCLEX-style
-- questions (single-best-answer + select-all-that-apply), 50 per note. Every answer is grounded in
-- (and its rationale limited to) the source note listed for its topic:
--   Notes/MedSurg/MedSurg-Pharmacology.html
--   Notes/MedSurg/Orthopedic-PostOp-Care.html
--   Notes/MedSurg/Emergency-Shock-Surgical-Meds.html
--   Notes/MedSurg/MedSurg-Priorities.html
--   Notes/MedSurg/Postoperative-Surgical-Emergencies.html
--   Notes/MedSurg/MedSurg-Master-Overview.html
--   Notes/MedSurg/Shock-Management-Emergency-Care.html
--   Notes/MedSurg/Preoperative-Postoperative-Care.html
--
-- Maps each source path through note_catalog.note_id to the published test_topics
-- row(s) for that note (matching test.html's note-level topic grouping). All
-- missing/ambiguous mappings are reported before any deletion or insertion.
-- Safe to rerun: only rows carrying this script's category labels are replaced,
-- and the transaction aborts unless exactly 50 rows per topic (400) exist after insert.
BEGIN;

CREATE TEMP TABLE _medsurg_sources (
  source_key text PRIMARY KEY,
  source_path text NOT NULL UNIQUE,
  category text NOT NULL UNIQUE
) ON COMMIT DROP;

INSERT INTO _medsurg_sources (source_key, source_path, category) VALUES
  ('pharm', 'Notes/MedSurg/MedSurg-Pharmacology.html', 'Medical-Surgical Care NCLEX seed v1 - medsurg pharmacology'),
  ('ortho', 'Notes/MedSurg/Orthopedic-PostOp-Care.html', 'Medical-Surgical Care NCLEX seed v1 - orthopedic postop care'),
  ('emerg_meds', 'Notes/MedSurg/Emergency-Shock-Surgical-Meds.html', 'Medical-Surgical Care NCLEX seed v1 - emergency shock surgical meds'),
  ('priorities', 'Notes/MedSurg/MedSurg-Priorities.html', 'Medical-Surgical Care NCLEX seed v1 - medsurg priorities'),
  ('postop_emerg', 'Notes/MedSurg/Postoperative-Surgical-Emergencies.html', 'Medical-Surgical Care NCLEX seed v1 - postoperative surgical emergencies'),
  ('overview', 'Notes/MedSurg/MedSurg-Master-Overview.html', 'Medical-Surgical Care NCLEX seed v1 - medsurg master overview'),
  ('shock', 'Notes/MedSurg/Shock-Management-Emergency-Care.html', 'Medical-Surgical Care NCLEX seed v1 - shock management emergency care'),
  ('periop', 'Notes/MedSurg/Preoperative-Postoperative-Care.html', 'Medical-Surgical Care NCLEX seed v1 - preoperative postoperative care');

CREATE TEMP TABLE _medsurg_seed_map (
  source_key text PRIMARY KEY,
  source_path text NOT NULL,
  category text NOT NULL,
  note_id uuid NOT NULL,
  note_title text NOT NULL,
  topic_id uuid NOT NULL,
  topic_aliases text[] NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE _medsurg_seed_config (test_id bigint NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  v_subject_id uuid;
  v_subject_count integer;
  v_note_count integer;
  v_topic_count integer;
  v_note_id uuid;
  v_note_title text;
  v_topic_id uuid;
  v_aliases text[];
  v_test_id bigint;
  v_errors text[] := ARRAY[]::text[];
  r record;
BEGIN
  SELECT count(*)
    INTO v_subject_count
    FROM test_subjects
   WHERE lower(btrim(name)) = 'medical-surgical care'
     AND is_active = true;
  IF v_subject_count <> 1 THEN
    v_errors := array_append(v_errors,
      format('Expected exactly one active test_subjects row named "Medical-Surgical Care"; found %s.', v_subject_count));
  ELSE
    SELECT id INTO v_subject_id
      FROM test_subjects
     WHERE lower(btrim(name)) = 'medical-surgical care'
       AND is_active = true;
  END IF;

  SELECT id INTO v_test_id
    FROM tests
   WHERE is_active = true
   ORDER BY id
   LIMIT 1;
  IF v_test_id IS NULL THEN
    v_errors := array_append(v_errors, 'No active tests row is available for test_questions.test_id.');
  END IF;

  FOR r IN SELECT source_key, source_path, category FROM _medsurg_sources ORDER BY source_key LOOP
    SELECT count(*)
      INTO v_note_count
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_note_count = 0 THEN
      v_errors := array_append(v_errors,
        format('Missing active note_catalog mapping for %s.', r.source_path));
      CONTINUE;
    ELSIF v_note_count > 1 THEN
      v_errors := array_append(v_errors,
        format('Ambiguous active note_catalog mapping for %s (%s rows).', r.source_path, v_note_count));
      CONTINUE;
    END IF;

    SELECT note_id, title
      INTO v_note_id, v_note_title
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_subject_count <> 1 THEN
      v_errors := array_append(v_errors,
        format('Cannot resolve test_topics aliases for %s because the active Medical-Surgical Care subject mapping is not unique.',
               r.source_path));
      CONTINUE;
    END IF;

    SELECT count(*)
      INTO v_topic_count
      FROM test_topics
     WHERE subject_id = v_subject_id
       AND note_id = v_note_id
       AND (status = 'published' OR status IS NULL);

    IF v_topic_count = 0 THEN
      v_errors := array_append(v_errors,
        format('No published test_topics row in Medical-Surgical Care points to note %s (%s).',
               v_note_title, r.source_path));
      CONTINUE;
    END IF;

    -- Sibling topics are expected aliases in test.html's note-level merged row.
    -- Insert all 50 for this source under one deterministic sibling topic_id.
    SELECT t.id
      INTO v_topic_id
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL)
     ORDER BY t.display_order NULLS LAST, t.created_at, t.name, t.id
     LIMIT 1;

    -- Collect the actual underlying aliases for the mapping check/report context.
    SELECT array_agg(t.name ORDER BY t.display_order NULLS LAST, t.name, t.id)
      INTO v_aliases
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL);

    INSERT INTO _medsurg_seed_map
      (source_key, source_path, category, note_id, note_title, topic_id, topic_aliases)
    VALUES
      (r.source_key, r.source_path, r.category, v_note_id, v_note_title, v_topic_id, v_aliases);
  END LOOP;

  IF cardinality(v_errors) > 0 THEN
    RAISE EXCEPTION E'Med-Surg seed mapping validation failed before any deletion/insertion:\n - %',
      array_to_string(v_errors, E'\n - ');
  END IF;

  IF (SELECT count(*) FROM _medsurg_seed_map) <> 8 THEN
    RAISE EXCEPTION 'Internal mapping check failed: expected 8 note mappings, found %.',
      (SELECT count(*) FROM _medsurg_seed_map);
  END IF;

  INSERT INTO _medsurg_seed_config (test_id) VALUES (v_test_id);
END $$;

-- Only rows from this script's unique category names are replaced.
DELETE FROM test_questions q
 USING _medsurg_seed_map m
 WHERE q.category = m.category;

INSERT INTO test_questions
  (test_id, topic_id, question, question_stem, options, correct_answer, rationale,
   category, is_multiple_choice, display_order, points, is_active)
SELECT c.test_id, m.topic_id, v.stem, v.stem, v.options, v.correct_answer, v.rationale,
       m.category, v.is_multi, v.display_order, 1, true
  FROM (VALUES
  ('pharm', 1, 'A client 3 hours after abdominal surgery requests IV morphine for incisional pain rated 8/10. The nurse counts a respiratory rate of 10/min, and the client falls asleep in the middle of answering a question. What is the nurse''s BEST action?', '[{"id": "a", "text": "Give the full morphine dose because the pain rating is severe"}, {"id": "b", "text": "Hold the morphine dose; the respiratory rate is below 12"}, {"id": "c", "text": "Give the dose with ondansetron to prevent nausea and vomiting"}, {"id": "d", "text": "Give the dose now and reassess the pain level in 30 minutes"}]'::jsonb, '["b"]', 'Before giving an opioid the nurse assesses respiratory rate, pain level, and LOC; a respiratory rate under 12 means hold the dose, and this client is also sedated. A severe pain rating does not override the respiratory-rate hold rule.', false),
  ('pharm', 2, 'A client on postoperative day 2 has been receiving IV hydromorphone (Dilaudid) every 3 hours for pain. Which assessment findings should the nurse recognize as side effects of this medication? Select all that apply.', '[{"id": "a", "text": "Constipation since the medication was started"}, {"id": "b", "text": "Urinary retention with an inability to void"}, {"id": "c", "text": "New ringing in the ears and reduced hearing"}, {"id": "d", "text": "Nausea after each dose of the medication"}, {"id": "e", "text": "Sedation that increases after each dose"}]'::jsonb, '["a", "b", "d", "e"]', 'Hydromorphone is an opioid. Constipation (a), urinary retention (b), nausea (d), and sedation (e) are all listed opioid side effects. Ringing in the ears and hearing loss (c) reflect ototoxicity, which is linked to vancomycin, aminoglycosides such as gentamicin, and rapid IV furosemide, not to opioids.', true),
  ('pharm', 3, 'A client receiving a continuous IV heparin infusion for a blood clot has an aPTT of 82 seconds. The laboratory''s normal (control) value is 30 seconds, and the client has no visible bleeding. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The aPTT is within the goal range, so the infusion is working as intended"}, {"id": "b", "text": "The aPTT is below the goal range, so the client remains at risk for clotting"}, {"id": "c", "text": "The aPTT is above the goal range, which increases the risk of bleeding"}, {"id": "d", "text": "The aPTT does not apply; the INR is the test used to monitor heparin"}]'::jsonb, '["c"]', 'The heparin goal is an aPTT of 1.5–2.5 times normal, or 45–75 seconds with a 30-second control. A value of 82 seconds is about 2.7 times normal, so it is above goal, and bleeding is the major risk. The INR monitors warfarin, not heparin.', false),
  ('pharm', 4, 'A client in the PACU received several doses of IV fentanyl and no other sedating medications. Twenty minutes later the client is difficult to arouse and has a respiratory rate of 6/min. Which medication should the nurse prepare to administer FIRST?', '[{"id": "a", "text": "Naloxone (Narcan)"}, {"id": "b", "text": "Flumazenil"}, {"id": "c", "text": "Protamine sulfate IV"}, {"id": "d", "text": "N-acetylcysteine"}]'::jsonb, '["a"]', 'Fentanyl is an opioid, and respiratory depression with sedation points to opioid overdose, which naloxone (Narcan) reverses. Flumazenil reverses benzodiazepines such as diazepam, and this client received none.', false),
  ('pharm', 5, 'A client on a continuous heparin infusion started oral warfarin yesterday. Today the client has pink-tinged urine and bleeding gums. The aPTT is 3 times the normal value, and the INR is 1.3. Which antidote should the nurse anticipate the provider will order?', '[{"id": "a", "text": "Vitamin K"}, {"id": "b", "text": "N-acetylcysteine IV"}, {"id": "c", "text": "Flumazenil"}, {"id": "d", "text": "Protamine sulfate"}]'::jsonb, '["d"]', 'The aPTT is well above the heparin goal of 1.5–2.5 times normal, and the INR is below the warfarin goal of 2–3, so heparin is causing the bleeding. Its antidote is protamine sulfate. Vitamin K reverses warfarin, which is not yet at a therapeutic level.', false),
  ('pharm', 6, 'A client is being discharged on warfarin (Coumadin) after treatment for a deep vein clot. Which statements by the client indicate understanding of the discharge teaching? Select all that apply.', '[{"id": "a", "text": "\"I will report bleeding gums, blood in my urine or stool, or bruising.\""}, {"id": "b", "text": "\"I can keep taking ibuprofen or naproxen for my arthritis pain.\""}, {"id": "c", "text": "\"My INR goal is 2 to 3 while I take warfarin.\""}, {"id": "d", "text": "\"If I bleed, the antidote I would receive is protamine sulfate.\""}, {"id": "e", "text": "\"Aspirin is fine for headaches because it is not an NSAID.\""}]'::jsonb, '["a", "c"]', 'Bleeding is the major risk of anticoagulants, so the client should watch the gums, urine, stool, and skin for bruising (a). The warfarin INR goal is 2–3 (c). Ibuprofen and naproxen (b) are NSAIDs, and aspirin (e) is also excluded; neither is taken with anticoagulants unless ordered. Protamine sulfate (d) reverses heparin, while vitamin K reverses warfarin.', true),
  ('pharm', 7, 'A client receiving enoxaparin (Lovenox) SQ after surgery asks why the roommate, who is on an IV heparin infusion, has an aPTT drawn every few hours while the client has no such blood tests. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Enoxaparin is monitored with the INR instead, which is drawn weekly.\""}, {"id": "b", "text": "\"Enoxaparin is a low-molecular-weight heparin, so less monitoring is needed.\""}, {"id": "c", "text": "\"Enoxaparin has no bleeding risk, so blood tests are not necessary for you at all.\""}, {"id": "d", "text": "\"Your enoxaparin dose is too small to need any monitoring during your stay.\""}]'::jsonb, '["b"]', 'Enoxaparin (Lovenox) is a low-molecular-weight heparin, so it needs less monitoring than an IV heparin infusion, which is monitored by aPTT. Bleeding remains the major risk of every anticoagulant, so option c is false.', false),
  ('pharm', 8, 'A client with diabetes receives short-acting (Regular) insulin subcutaneously at 0730. The nurse plans to watch closely for hypoglycemia while the insulin is at its peak. During which time frame is the client at HIGHEST risk?', '[{"id": "a", "text": "0800 to 0830"}, {"id": "b", "text": "0830 to 0930"}, {"id": "c", "text": "0930 to 1130"}, {"id": "d", "text": "1130 to 1930"}]'::jsonb, '["c"]', 'Regular insulin peaks 2–4 hours after it is given, so a 0730 dose peaks from 0930 to 1130. The 0800–0830 window is its 30–60 minute onset, about 1 hour matches the lispro peak, and 4–12 hours matches the NPH peak.', false),
  ('pharm', 9, 'A nurse will give insulin lispro at 0745 to a client with diabetes, and the breakfast trays arrive on the unit at 0800. Which actions or expectations by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Have another nurse double-check the insulin dose"}, {"id": "b", "text": "Give the rapid-acting insulin with meals"}, {"id": "c", "text": "Monitor for the peak about 1 hr after the dose"}, {"id": "d", "text": "Monitor for the peak 4 to 12 hr after the dose"}, {"id": "e", "text": "Hold the lispro until bedtime since it is rapid-acting"}]'::jsonb, '["a", "b", "c"]', 'Insulin is always double-checked with another nurse (a). Rapid-acting insulin is given with meals (b), and lispro peaks about 1 hour after injection (c). A 4–12 hour peak (d) describes NPH. Rapid-acting insulin is given with meals, not held until bedtime (e).', true),
  ('pharm', 10, 'Four clients with diabetes each received one type of insulin at 0700 with breakfast and have not eaten since lunch. At 1600, which client is at HIGHEST risk for hypoglycemia related to the insulin''s peak action?', '[{"id": "a", "text": "Intermediate (NPH) insulin given at 0700"}, {"id": "b", "text": "Rapid-acting (Lispro) insulin given with breakfast"}, {"id": "c", "text": "Short-acting (Regular) insulin given at 0700"}, {"id": "d", "text": "Long-acting (Glargine) insulin given at 0700"}]'::jsonb, '["a"]', 'NPH peaks 4–12 hours after injection, so a 0700 dose peaks from 1100 to 1900, which includes 1600. Lispro peaks at about 0800, Regular peaks from 0900 to 1100, and glargine has no peak.', false),
  ('pharm', 11, 'A client received Regular insulin 3 hours ago and IV morphine 4 hours ago. The client is now unresponsive with a respiratory rate of 16/min, and the bedside glucose result is critically low, consistent with severe hypoglycemia. Which medication should the nurse prepare to give IMMEDIATELY?', '[{"id": "a", "text": "Naloxone (Narcan) IV"}, {"id": "b", "text": "Flumazenil"}, {"id": "c", "text": "Vitamin K"}, {"id": "d", "text": "IV dextrose (D50)"}]'::jsonb, '["d"]', 'The critically low glucose 3 hours after Regular insulin, within its 2–4 hour peak, explains the unresponsiveness, and severe hypoglycemia is treated with glucagon or IV dextrose (D50). A respiratory rate of 16 is not below 12, so opioid overdose requiring naloxone is not the likely cause.', false),
  ('pharm', 12, 'A client receiving chemotherapy has a markedly decreased WBC count and has been placed on neutropenic precautions. Which actions by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Monitor WBCs, platelets, and RBCs"}, {"id": "b", "text": "Use PPE during handling of chemotherapy"}, {"id": "c", "text": "Encourage fresh fruits from the family"}, {"id": "d", "text": "No fresh flowers for neutropenic precautions"}, {"id": "e", "text": "Avoid crowds while immunosuppressed"}]'::jsonb, '["a", "b", "d", "e"]', 'Chemotherapy requires monitoring of WBCs, platelets, and RBCs (a) and the use of PPE during handling (b). Neutropenic precautions mean no fresh flowers (d) and avoiding crowds (e). Fresh fruit (c) is also excluded under neutropenic precautions.', true),
  ('pharm', 13, 'A client 10 days after a cycle of chemotherapy has new mouth sores, thinning hair, and mild nausea. Today''s laboratory results show a sharply lower WBC count than at the previous cycle. Which finding requires the nurse''s IMMEDIATE follow-up?', '[{"id": "a", "text": "Stomatitis"}, {"id": "b", "text": "Immunosuppression"}, {"id": "c", "text": "Alopecia"}, {"id": "d", "text": "Nausea"}]'::jsonb, '["b"]', 'Stomatitis, alopecia, nausea, and immunosuppression are all chemotherapy effects to watch for, but a sharply falling WBC count signals immunosuppression and the need for neutropenic precautions to protect the client from infection. The other findings are uncomfortable but do not pose the same immediate safety threat.', false),
  ('pharm', 14, 'A client has scheduled acetaminophen 650 mg orally every 4 hours around the clock. The client now asks for a PRN combination pain tablet that contains 325 mg of acetaminophen. What is the nurse''s BEST action?', '[{"id": "a", "text": "Give the combination tablet because 325 mg is a small added amount"}, {"id": "b", "text": "Give the tablet and monitor the client for GI bleeding and renal damage"}, {"id": "c", "text": "Hold the tablet; the dose would exceed the 4 g/day max dose"}, {"id": "d", "text": "Give the tablet, since liver toxicity occurs only with doses above 6 g/day"}]'::jsonb, '["c"]', '650 mg × 6 doses = 3,900 mg per day, and adding 325 mg brings the total to 4,225 mg, which is over the 4 g/day maximum and risks liver toxicity. GI bleeding and renal damage are NSAID risks, not acetaminophen risks.', false),
  ('pharm', 15, 'A nurse teaches a client who will take acetaminophen (Tylenol) at home for pain. Which statements by the client indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "\"I can take two 500 mg tablets every 4 hours around the clock.\""}, {"id": "b", "text": "\"Taking too much acetaminophen can cause liver toxicity.\""}, {"id": "c", "text": "\"I can use acetaminophen for mild pain or for a fever.\""}, {"id": "d", "text": "\"I will keep my total dose under 4 grams in one day.\""}, {"id": "e", "text": "\"The main risk I need to watch for is GI bleeding.\""}]'::jsonb, '["a", "e"]', 'Two 500 mg tablets every 4 hours equals 1,000 mg × 6 = 6 g/day, which exceeds the 4 g/day maximum (a needs teaching). GI bleeding is an NSAID risk, while the acetaminophen risk is liver toxicity (e needs teaching). Statements b, c, and d are correct: liver toxicity is the risk, the drug is used for mild pain or fever, and the maximum is 4 g/day.', true),
  ('pharm', 16, 'A client is brought to the emergency department 2 hours after swallowing a large amount of acetaminophen (Tylenol) along with two of a family member''s diazepam tablets. The client is alert and oriented with a respiratory rate of 18/min. Which antidote is MOST important for the nurse to anticipate?', '[{"id": "a", "text": "N-acetylcysteine"}, {"id": "b", "text": "Naloxone (Narcan)"}, {"id": "c", "text": "Flumazenil"}, {"id": "d", "text": "Vitamin K"}]'::jsonb, '["a"]', 'N-acetylcysteine is the antidote for acetaminophen, whose risk is liver toxicity after a large overdose. Flumazenil reverses benzodiazepines such as diazepam, but this alert client with a normal respiratory rate shows no oversedation, and naloxone is for opioid overdose.', false),
  ('pharm', 17, 'A client with chronic kidney disease and an elevated creatinine reports mild pain rated 3/10 and has a fever. PRN orders include ketorolac IV, ibuprofen PO, naproxen PO, and acetaminophen PO. Which medication is MOST appropriate for the nurse to give?', '[{"id": "a", "text": "Ketorolac (Toradol) IV"}, {"id": "b", "text": "Ibuprofen PO"}, {"id": "c", "text": "Naproxen PO"}, {"id": "d", "text": "Acetaminophen PO"}]'::jsonb, '["d"]', 'Acetaminophen treats mild pain and fever. Ibuprofen and naproxen are NSAIDs, which are avoided in kidney disease, and ketorolac is avoided when the creatinine is elevated.', false),
  ('pharm', 18, 'A nurse reviews postoperative pain medication orders for several clients before administration. Which orders require follow-up with the provider? Select all that apply.', '[{"id": "a", "text": "Ketorolac IV for a client whose creatinine is elevated"}, {"id": "b", "text": "Ketorolac IV for a client also on scheduled ibuprofen"}, {"id": "c", "text": "Ketorolac IV continued on day 6 for ongoing pain"}, {"id": "d", "text": "Naproxen PO for a client with a history of peptic ulcers"}, {"id": "e", "text": "Acetaminophen 650 mg PO every 6 hours for a fever"}]'::jsonb, '["a", "b", "c", "d"]', 'Ketorolac is avoided when the creatinine is elevated (a), is not used with other NSAIDs such as ibuprofen (b), and is limited to a maximum of 5 days (c). Naproxen is an NSAID, and NSAIDs are avoided with peptic ulcers (d). Acetaminophen 650 mg every 6 hours is 2,600 mg/day, which is under the 4 g/day maximum and appropriate for fever (e).', true),
  ('pharm', 19, 'A client on postoperative day 1 with a known platelet disorder reports moderate-to-severe incisional pain, and a new order for ketorolac (Toradol) IV has been received. The creatinine is within normal limits. What is the nurse''s BEST action?', '[{"id": "a", "text": "Give the ketorolac because creatinine is normal"}, {"id": "b", "text": "Hold the ketorolac due to the platelet disorder"}, {"id": "c", "text": "Give the ketorolac with ibuprofen for better relief"}, {"id": "d", "text": "Give the ketorolac but for no more than 5 days"}]'::jsonb, '["b"]', 'Ketorolac is avoided with an elevated creatinine or a platelet disorder, so the platelet disorder alone is reason to clarify the order. A normal creatinine and a 5-day limit do not remove the platelet contraindication, and combining it with another NSAID is not allowed.', false),
  ('pharm', 20, 'A client on day 5 of IV vancomycin says the television sounds muffled. This morning''s creatinine has risen from the client''s baseline, and the next dose is due in 1 hour. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Give the dose on time because muffled hearing is an expected effect"}, {"id": "b", "text": "Give the dose and recheck the creatinine level again at the end of therapy"}, {"id": "c", "text": "Check the trough level and report the hearing and creatinine changes"}, {"id": "d", "text": "Give the dose with a rapid IV push of furosemide to protect the kidneys"}]'::jsonb, '["c"]', 'Vancomycin requires monitoring of trough levels and creatinine because of the risks of ototoxicity and nephrotoxicity, and both appear to be developing. Rapid IV furosemide would add to the risk of ototoxicity rather than protect the client.', false),
  ('pharm', 21, 'A client receiving IV gentamicin for a serious infection develops fluid overload and is prescribed IV furosemide (Lasix). Which adverse effects should the nurse monitor for MOST closely while the client receives both drugs? Select all that apply.', '[{"id": "a", "text": "Ototoxicity"}, {"id": "b", "text": "Hypokalemia"}, {"id": "c", "text": "Tendon rupture"}, {"id": "d", "text": "Nephrotoxicity"}, {"id": "e", "text": "Teeth staining"}]'::jsonb, '["a", "b", "d"]', 'Gentamicin is ototoxic and nephrotoxic (a, d), and IV furosemide can also cause ototoxicity when it is not given slowly. Furosemide causes potassium loss, so hypokalemia is a risk (b). Tendon rupture (c) is a fluoroquinolone (ciprofloxacin) risk, and teeth staining (e) is a tetracycline risk.', true),
  ('pharm', 22, 'A client receiving IV gentamicin has a new order for furosemide (Lasix) 40 mg IV for edema. The client''s urine output has been adequate. Which action by the nurse is MOST important when giving the furosemide?', '[{"id": "a", "text": "Give the furosemide slowly IV to prevent ototoxicity"}, {"id": "b", "text": "Push the furosemide rapidly to achieve faster diuresis"}, {"id": "c", "text": "Monitor the client closely for signs of hyperkalemia"}, {"id": "d", "text": "Check the aPTT before each dose of furosemide is given"}]'::jsonb, '["a"]', 'IV furosemide is given slowly to prevent ototoxicity, which matters even more because gentamicin is also ototoxic. Furosemide causes hypokalemia, not hyperkalemia, and its monitoring includes I&O, potassium, and BP rather than aPTT.', false),
  ('pharm', 23, 'A nurse reviews new antibiotic orders before the first doses are given. Which client situations require follow-up with the provider before administration? Select all that apply.', '[{"id": "a", "text": "Tetracyclines during pregnancy at 20 weeks"}, {"id": "b", "text": "Tetracyclines for children, such as an 8-year-old"}, {"id": "c", "text": "Cephalosporins despite allergies to penicillins"}, {"id": "d", "text": "Ciprofloxacin for an adult with no tendon problems"}, {"id": "e", "text": "Vancomycin with a creatinine that is rising"}]'::jsonb, '["a", "b", "c", "e"]', 'Tetracyclines are avoided in pregnancy and in children because they stain teeth (a, b). Penicillins and cephalosporins require an allergy check because of cross-reactivity (c). Vancomycin is nephrotoxic, so a rising creatinine needs follow-up (e). Ciprofloxacin carries a risk of tendon rupture, but an adult with no tendon problems has no stated reason to question the order (d).', true),
  ('pharm', 24, 'A client is discharged on a 10-day course of ciprofloxacin for a urinary tract infection. On day 4 the nurse calls to follow up. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will report any sudden pain in my heel or ankle tendon.\""}, {"id": "b", "text": "\"I know this antibiotic carries a risk of tendon rupture.\""}, {"id": "c", "text": "\"I''m taking every dose even though my burning has eased.\""}, {"id": "d", "text": "\"I''m feeling better, so I can stop the antibiotic course.\""}]'::jsonb, '["d"]', 'The full antibiotic course must be finished even when the client feels better, so stopping on day 4 needs correction. Watching for tendon problems reflects the ciprofloxacin risk of tendon rupture and is correct.', false),
  ('pharm', 25, 'A client in the preoperative area has an order for an IV cephalosporin antibiotic before incision. During the final check, the client says, "I broke out in hives the last time I took penicillin." What should the nurse do FIRST?', '[{"id": "a", "text": "Give the cephalosporin because it is not a penicillin"}, {"id": "b", "text": "Hold the dose and clarify it due to cross-reactivity"}, {"id": "c", "text": "Give half of the dose and watch the client for hives"}, {"id": "d", "text": "Give the dose and document the allergy afterward"}]'::jsonb, '["b"]', 'Penicillins and cephalosporins require an allergy check because of cross-reactivity, so the dose is held and the order clarified before it is given. Treating the cephalosporin as safe because it is a different class ignores that cross-reactivity.', false),
  ('pharm', 26, 'A client received IV diazepam for anxiety before a procedure and has not received any opioids. One hour later, the client is very difficult to arouse and has a respiratory rate of 8/min. Which antidote should the nurse anticipate giving?', '[{"id": "a", "text": "Naloxone (Narcan)"}, {"id": "b", "text": "Protamine sulfate"}, {"id": "c", "text": "Flumazenil"}, {"id": "d", "text": "Digibind"}]'::jsonb, '["c"]', 'Diazepam is a benzodiazepine, and the benzodiazepine antidote is flumazenil. Naloxone reverses opioid overdose, and this client received no opioids.', false),
  ('pharm', 27, 'A nurse prepares for medication emergencies on a surgical unit and reviews each client situation with its antidote. Which client situation–antidote pairings are correct? Select all that apply.', '[{"id": "a", "text": "Heparin infusion with bleeding — vitamin K"}, {"id": "b", "text": "Acetaminophen overdose — N-acetylcysteine"}, {"id": "c", "text": "Digoxin toxicity — Digibind"}, {"id": "d", "text": "Warfarin with bleeding — protamine sulfate"}, {"id": "e", "text": "Diazepam oversedation — flumazenil"}]'::jsonb, '["b", "c", "e"]', 'Acetaminophen is reversed by N-acetylcysteine (b), digoxin by Digibind (c), and benzodiazepines such as diazepam by flumazenil (e). Heparin is reversed by protamine sulfate, not vitamin K (a), and warfarin is reversed by vitamin K, not protamine sulfate (d).', true),
  ('pharm', 28, 'A client with a known history of a prolonged QT interval is nauseated after general anesthesia, and ondansetron (Zofran) IV is ordered. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Give the ondansetron and monitor the ECG"}, {"id": "b", "text": "Give the ondansetron and watch for tardive dyskinesia"}, {"id": "c", "text": "Hold the ondansetron because of bowel obstruction risk"}, {"id": "d", "text": "Give famotidine instead to stop the nausea"}]'::jsonb, '["a"]', 'Ondansetron is the first-line antiemetic before and after surgery, but it can prolong the QT interval, so the ECG is monitored in high-risk patients such as this client. Tardive dyskinesia and the bowel obstruction concern belong to metoclopramide, and famotidine reduces acid rather than treating nausea.', false),
  ('pharm', 29, 'A client received ondansetron (Zofran) before surgery and again in the PACU. On postoperative day 1, the client asks which symptoms might be caused by this medication. Which findings are common side effects of ondansetron? Select all that apply.', '[{"id": "a", "text": "Tardive dyskinesia"}, {"id": "b", "text": "Tendon rupture"}, {"id": "c", "text": "Headache"}, {"id": "d", "text": "Constipation"}, {"id": "e", "text": "Stomatitis"}]'::jsonb, '["c", "d"]', 'Headache (c) and constipation (d) are the common side effects of ondansetron. Tardive dyskinesia (a) is a risk of long-term metoclopramide use, tendon rupture (b) is a ciprofloxacin risk, and stomatitis (e) is a chemotherapy effect.', true),
  ('pharm', 30, 'A client admitted with abdominal distension, vomiting, and a suspected bowel obstruction has several new medication orders. Which order should the nurse question before giving it?', '[{"id": "a", "text": "Ondansetron IV for nausea and vomiting"}, {"id": "b", "text": "Metoclopramide IV for nausea and vomiting"}, {"id": "c", "text": "Famotidine IV to reduce gastric acid"}, {"id": "d", "text": "Hydromorphone IV with respiratory rate checks"}]'::jsonb, '["b"]', 'Metoclopramide is a prokinetic that promotes gastric emptying and is avoided in bowel obstruction. Ondansetron, famotidine, and hydromorphone with respiratory monitoring are not contraindicated by a bowel obstruction.', false),
  ('pharm', 31, 'A client has taken metoclopramide (Reglan) for several months for slow gastric emptying, and the provider wants to continue it. Which adverse effect should the nurse monitor for MOST closely because of this long-term use?', '[{"id": "a", "text": "QT interval prolongation"}, {"id": "b", "text": "Tendon rupture"}, {"id": "c", "text": "Hypokalemia"}, {"id": "d", "text": "Tardive dyskinesia"}]'::jsonb, '["d"]', 'Tardive dyskinesia is the risk tied to long-term metoclopramide use. QT prolongation is the ondansetron concern, tendon rupture belongs to ciprofloxacin, and hypokalemia belongs to furosemide.', false),
  ('pharm', 32, 'A critically ill client on a ventilator after major surgery has famotidine (Pepcid) IV ordered. The family asks why it is needed, since the client has never had an ulcer. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"It prevents nausea and vomiting after anesthesia and surgery.\""}, {"id": "b", "text": "\"It promotes gastric emptying after surgery.\""}, {"id": "c", "text": "\"It is stress ulcer prophylaxis for critically ill patients.\""}, {"id": "d", "text": "\"It reverses the effects of the sedating medications you received.\""}]'::jsonb, '["c"]', 'After surgery, famotidine is used for stress ulcer prophylaxis in critically ill patients, so a history of ulcers is not required. Preventing nausea describes ondansetron, and promoting gastric emptying describes metoclopramide.', false),
  ('pharm', 33, 'A nurse reviews the perioperative medications ordered for a client having abdominal surgery. Which medication–purpose statements are accurate? Select all that apply.', '[{"id": "a", "text": "Famotidine given pre-op reduces aspiration risk"}, {"id": "b", "text": "Ketorolac is given for mild pain and fever"}, {"id": "c", "text": "Metoclopramide promotes gastric emptying"}, {"id": "d", "text": "Furosemide is given to treat hypokalemia"}, {"id": "e", "text": "Ondansetron prevents post-op nausea and vomiting"}]'::jsonb, '["a", "c", "e"]', 'Famotidine given before surgery reduces aspiration risk (a), metoclopramide promotes gastric emptying (c), and ondansetron prevents post-op nausea and vomiting (e). Ketorolac is an NSAID for moderate–severe post-op pain, while mild pain and fever describe acetaminophen (b). Furosemide causes hypokalemia rather than treating it (d).', true),
  ('pharm', 34, 'A client with acute kidney failure has crackles and edema and has had no urine output (anuria) for the past 12 hours. An order reads furosemide (Lasix) 40 mg IV now. What is the nurse''s BEST action?', '[{"id": "a", "text": "Hold the dose and clarify it; furosemide is contraindicated in anuria"}, {"id": "b", "text": "Give the furosemide IV rapidly so that the urine output can begin again"}, {"id": "c", "text": "Give the furosemide and monitor the potassium level for hyperkalemia"}, {"id": "d", "text": "Give the furosemide and recheck the urine output again in 8 hours"}]'::jsonb, '["a"]', 'Furosemide is contraindicated in anuria (no urine output), so the dose is held and the order clarified even though the client is fluid overloaded. Giving it rapidly IV risks ototoxicity, and the potassium risk is hypokalemia, not hyperkalemia.', false),
  ('pharm', 35, 'A client with fluid overload and edema is receiving furosemide (Lasix) 40 mg IV twice daily and has good urine output. Which actions should the nurse include in the plan of care? Select all that apply.', '[{"id": "a", "text": "Monitor intake and output (I&O)"}, {"id": "b", "text": "Monitor potassium for hypokalemia"}, {"id": "c", "text": "Push each IV dose rapidly for diuresis"}, {"id": "d", "text": "Monitor BP with each dose"}, {"id": "e", "text": "Monitor potassium for hyperkalemia"}]'::jsonb, '["a", "b", "d"]', 'Furosemide monitoring includes I&O (a), potassium because of the risk of hypokalemia (b), and BP (d). IV furosemide is given slowly to prevent ototoxicity, not pushed rapidly (c). Furosemide causes potassium loss, so hyperkalemia (e) is the wrong concern.', true),
  ('pharm', 36, 'The nurse receives handoff report on four clients on a medical-surgical unit. Which client should the nurse see FIRST?', '[{"id": "a", "text": "A client on warfarin with an INR of 2.6 who is asking when discharge will happen today"}, {"id": "b", "text": "A client on IV morphine with a respiratory rate of 9/min and increasing sedation"}, {"id": "c", "text": "A client receiving chemotherapy who is tearful and upset about new alopecia this morning"}, {"id": "d", "text": "A client given ondansetron 1 hour ago who now reports a mild headache"}]'::jsonb, '["b"]', 'Respiratory depression with sedation in a client on an opioid is an airway and breathing threat, and a respiratory rate under 12 means the opioid is held. An INR of 2.6 is within the 2–3 goal, alopecia is an expected chemotherapy effect, and headache is a common ondansetron side effect.', false),
  ('pharm', 37, 'A nurse is assigned four clients who are receiving anticoagulant or insulin therapy. Based on the data in report, which client''s situation should the nurse address FIRST?', '[{"id": "a", "text": "Warfarin with an INR of 2.4 and ready for discharge teaching"}, {"id": "b", "text": "Insulin lispro due with a breakfast tray arriving in 20 minutes"}, {"id": "c", "text": "Heparin infusion with bleeding noted in the stool"}, {"id": "d", "text": "Enoxaparin with a question about why no blood tests are ordered"}]'::jsonb, '["c"]', 'Bleeding is the major risk of anticoagulants, and blood in the stool of a client on heparin is an actual bleeding problem that needs assessment first. Rapid-acting insulin is given with meals, so the lispro can wait for the tray, and an INR of 2.4 is within the 2–3 goal.', false),
  ('pharm', 38, 'Before giving morning medications, a nurse reviews laboratory results for several clients on a medical-surgical unit. Which medication–laboratory monitoring pairs are appropriate? Select all that apply.', '[{"id": "a", "text": "Heparin infusion — aPTT"}, {"id": "b", "text": "Warfarin (Coumadin) — INR"}, {"id": "c", "text": "Furosemide (Lasix) — aPTT"}, {"id": "d", "text": "Insulin — glucose"}, {"id": "e", "text": "Vancomycin — trough and creatinine"}]'::jsonb, '["a", "b", "d", "e"]', 'Heparin is monitored with the aPTT (a), warfarin with the INR (b), insulin with glucose (d), and vancomycin with trough levels and creatinine (e). Furosemide monitoring is I&O, potassium, and BP, not the aPTT (c).', true),
  ('pharm', 39, 'A client 6 hours after abdominal surgery rates incisional pain 7/10 and requests the prescribed IV morphine. The client is awake, answers questions appropriately, and has a respiratory rate of 12/min. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Hold the dose because the respiratory rate is at the hold limit"}, {"id": "b", "text": "Hold the dose and give naloxone to prevent respiratory depression"}, {"id": "c", "text": "Give half of the dose now and recheck the respiratory rate in 1 hour"}, {"id": "d", "text": "Give the dose, then reassess pain level, respiratory rate, and LOC"}]'::jsonb, '["d"]', 'The opioid is held only when the respiratory rate is below 12, and a rate of 12 in an alert client with severe pain does not meet that rule, so the dose is given and the client is reassessed. Naloxone is for opioid overdose, which this client does not have.', false),
  ('pharm', 40, 'Fifteen minutes ago, the nurse gave IV hydromorphone (Dilaudid) to a client whose pre-dose respiratory rate was 16/min and whose pain was rated 8/10. What is the nurse''s NEXT action?', '[{"id": "a", "text": "Reassess the pain level, respiratory rate, and LOC"}, {"id": "b", "text": "Document the dose and recheck the client at shift end"}, {"id": "c", "text": "Give ondansetron to prevent opioid-related nausea"}, {"id": "d", "text": "Prepare a dose of naloxone to give at the bedside now"}]'::jsonb, '["a"]', 'Pain medications require assessment both before and after administration, which includes pain level, respiratory rate, and LOC after an opioid. Naloxone is given only for opioid overdose, which is not present here.', false),
  ('pharm', 41, 'A charge nurse reviews the actions of a newly hired nurse who is caring for several clients, including one with diabetes whose breakfast was delayed until 0900 for a procedure. Which action by the new nurse requires follow-up?', '[{"id": "a", "text": "Asked another nurse to double-check an insulin dose"}, {"id": "b", "text": "Reviewed the client''s glucose result before insulin"}, {"id": "c", "text": "Gave insulin lispro at 0700 for the 0900 breakfast"}, {"id": "d", "text": "Held morphine for a client breathing 10 times/min"}]'::jsonb, '["c"]', 'Rapid-acting insulin is given with meals; lispro given at 0700 peaks at about 0800, an hour before the delayed meal arrives, which places the client at risk for hypoglycemia. Double-checking insulin, checking glucose, and holding an opioid for a respiratory rate under 12 are all correct actions.', false),
  ('pharm', 42, 'At 1200, the nurse reviews the insulin given to five clients today to decide who is within the expected peak window of the insulin. Which clients are currently at the peak action of their insulin? Select all that apply.', '[{"id": "a", "text": "Regular insulin given at 0700"}, {"id": "b", "text": "NPH insulin given at 0700"}, {"id": "c", "text": "Lispro insulin given at 1100"}, {"id": "d", "text": "Glargine insulin given at 0700"}, {"id": "e", "text": "Regular insulin given at 0900"}]'::jsonb, '["b", "c", "e"]', 'NPH peaks 4–12 hours after injection, so a 0700 dose peaks from 1100 to 1900 (b). Lispro peaks about 1 hour after injection, so an 1100 dose peaks near 1200 (c). Regular insulin peaks 2–4 hours after injection, so a 0900 dose peaks from 1100 to 1300 (e). Regular given at 0700 peaked from 0900 to 1100 (a), and glargine has no peak (d).', true),
  ('pharm', 43, 'A client newly started on insulin glargine at 2100 asks, "What time will this insulin peak, so I know when my blood sugar might drop overnight?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Glargine has a peak about 1 hr after injection.\""}, {"id": "b", "text": "\"Glargine has a peak 2 to 4 hr after injection.\""}, {"id": "c", "text": "\"Glargine has a peak 4 to 12 hr after injection.\""}, {"id": "d", "text": "\"Glargine has no peak; its duration is 24 hr.\""}]'::jsonb, '["d"]', 'Long-acting glargine has no peak and lasts about 24 hours. A peak at about 1 hour describes lispro, 2–4 hours describes Regular, and 4–12 hours describes NPH.', false),
  ('pharm', 44, 'A nurse is preparing to hang an IV chemotherapy agent for a client with cancer whose WBC, platelet, and RBC counts were reviewed this morning. Which action is MOST important for safe handling of the agent?', '[{"id": "a", "text": "Hang the bag quickly so the infusion finishes before visitors arrive"}, {"id": "b", "text": "Put on PPE before handling the chemotherapy bag and tubing"}, {"id": "c", "text": "Prime the tubing bare-handed to avoid contaminating the line"}, {"id": "d", "text": "Have the client''s family help hold the bag during connection"}]'::jsonb, '["b"]', 'Chemotherapy agents target cancer cells and are highly toxic, so PPE is used during handling. Priming the tubing bare-handed or letting family handle the bag exposes people to a highly toxic drug.', false),
  ('pharm', 45, 'A client receiving enoxaparin (Lovenox) after surgery asks to take ibuprofen brought from home for a headache. No ibuprofen or aspirin is ordered for this client. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"NSAIDs aren''t used with anticoagulants unless ordered; I''ll check.\""}, {"id": "b", "text": "\"Ibuprofen is safe because enoxaparin needs less monitoring.\""}, {"id": "c", "text": "\"You may take it as long as you report bruising or gum bleeding.\""}, {"id": "d", "text": "\"Aspirin would be a safer choice to take along with your enoxaparin.\""}]'::jsonb, '["a"]', 'Aspirin and NSAIDs such as ibuprofen are not given with anticoagulants unless ordered, so the nurse checks with the provider rather than allowing the home dose. Enoxaparin needing less monitoring does not remove its bleeding risk, and aspirin is excluded as well.', false),
  ('pharm', 46, 'A client scheduled for surgery under general anesthesia receives famotidine (Pepcid) IV in the preoperative area. The client says, "I never have heartburn, so why do I need this?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"It prevents nausea and vomiting after anesthesia.\""}, {"id": "b", "text": "\"It speeds up gastric emptying before your surgery.\""}, {"id": "c", "text": "\"It lowers stomach acid to reduce aspiration risk.\""}, {"id": "d", "text": "\"It treats the stress ulcer you have developed.\""}]'::jsonb, '["c"]', 'Before surgery, famotidine reduces aspiration risk by reducing stomach acid volume and acidity, whether or not the client has heartburn. Preventing nausea describes ondansetron, and speeding gastric emptying describes metoclopramide.', false),
  ('pharm', 47, 'A nurse is reviewing new orders for metoclopramide (Reglan) for several clients on a surgical unit. For which clients should the nurse question the order? Select all that apply.', '[{"id": "a", "text": "A client with delayed gastric emptying after surgery"}, {"id": "b", "text": "A client with a suspected bowel obstruction"}, {"id": "c", "text": "A client with nausea and vomiting after anesthesia"}, {"id": "d", "text": "A client with tardive dyskinesia from prior long-term use"}, {"id": "e", "text": "A client with a penicillin allergy listed in the chart"}]'::jsonb, '["b", "d"]', 'Metoclopramide is avoided in bowel obstruction (b) and carries a risk of tardive dyskinesia with long-term use, so a client who already has it needs follow-up (d). It is an antiemetic and prokinetic that promotes gastric emptying, which fits clients a and c, and a penicillin allergy (e) does not affect its use.', true),
  ('pharm', 48, 'A parent asks why the provider prescribed a different antibiotic instead of tetracycline for the parent''s 7-year-old child, who has a skin infection. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Tetracycline commonly causes tendon rupture in children.\""}, {"id": "b", "text": "\"Tetracycline must be given IV with trough level checks.\""}, {"id": "c", "text": "\"Tetracycline cross-reacts with penicillin in children.\""}, {"id": "d", "text": "\"Tetracycline is avoided in children; it stains teeth.\""}]'::jsonb, '["d"]', 'Tetracyclines are avoided in pregnancy and in children because they stain teeth. Tendon rupture is a ciprofloxacin risk, trough levels are drawn for vancomycin, and cross-reactivity applies to penicillins and cephalosporins.', false),
  ('pharm', 49, 'A client who takes warfarin (Coumadin) at home is admitted with an INR of 5.2 after a recent dose change. The provider plans to reverse the anticoagulant effect. Which medication should the nurse anticipate?', '[{"id": "a", "text": "Protamine sulfate"}, {"id": "b", "text": "Vitamin K"}, {"id": "c", "text": "Naloxone (Narcan)"}, {"id": "d", "text": "N-acetylcysteine"}]'::jsonb, '["b"]', 'An INR of 5.2 is well above the warfarin goal of 2–3, and vitamin K is the warfarin antidote. Protamine sulfate reverses heparin, not warfarin.', false),
  ('pharm', 50, 'A client with osteoarthritis has taken naproxen daily for several months. Which new finding is MOST important for the nurse to report to the health care provider?', '[{"id": "a", "text": "Stool that tests positive for blood, indicating GI bleeding"}, {"id": "b", "text": "Knee pain that improves about an hour after each daily dose"}, {"id": "c", "text": "Joint swelling and inflammation that have decreased"}, {"id": "d", "text": "A creatinine level that is unchanged from baseline"}]'::jsonb, '["a"]', 'NSAIDs such as naproxen carry risks of GI bleeding and renal damage, so blood in the stool must be reported. Improved pain and inflammation show the drug is working, and an unchanged creatinine does not suggest renal damage.', false),
  ('ortho', 1, 'On the first postoperative day after a right total hip replacement (THR), the nurse enters the room just after the UAP has repositioned the client. Which observation requires IMMEDIATE intervention?', '[{"id": "a", "text": "An abduction pillow is secured between the client''s legs"}, {"id": "b", "text": "The head of the bed is elevated to 40 degrees"}, {"id": "c", "text": "The right ankle is crossed over the left at the midline"}, {"id": "d", "text": "The client is turned toward the unaffected left side"}]'::jsonb, '["c"]', 'After a THR there must be no adduction, so the operative leg must not cross the midline, and a crossed leg risks hip dislocation. The abduction pillow, a head of bed under 45°, and turning toward the unaffected side are all correct positioning.', false),
  ('ortho', 2, 'Four hours after surgical repair of a fractured tibia and application of a long-leg cast, the nurse performs a neurovascular check distal to the cast. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "The toes are pale"}, {"id": "b", "text": "The foot is cool to touch"}, {"id": "c", "text": "Capillary refill is 1 second"}, {"id": "d", "text": "The pedal pulse is weak"}, {"id": "e", "text": "Loss of sensation in the toes"}]'::jsonb, '["a", "b", "d", "e"]', 'Pale color signals poor perfusion (a), coolness signals poor circulation (b), and an absent or weak pulse is a red flag (d). Loss of sensation suggests nerve damage or compartment syndrome (e). A capillary refill under 2 seconds is normal (c).', true),
  ('ortho', 3, 'On postoperative day 3 after a total knee replacement, a client suddenly reports sharp chest pain and shortness of breath. Oxygen saturation has dropped from 97% to 89% within the last few minutes. What is the nurse''s FIRST action?', '[{"id": "a", "text": "Coach the client to use the incentive spirometer for deep breaths"}, {"id": "b", "text": "Call the provider immediately about these findings"}, {"id": "c", "text": "Assist the client to walk in the hall to improve circulation"}, {"id": "d", "text": "Apply sequential compression devices (SCDs) to both legs"}]'::jsonb, '["b"]', 'Sudden chest pain with shortness of breath and a falling O₂ saturation signals a pulmonary embolism, and the provider is called immediately. Incentive spirometry, ambulation, and SCDs are routine prevention measures, not the response to an acute PE.', false),
  ('ortho', 4, 'A client 1 day after a total hip replacement asks the nurse to raise the head of the bed to 60 degrees because eating lunch lying back is difficult. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"I can elevate the bed, but not past 45 degrees, to protect your hip.\""}, {"id": "b", "text": "\"I''ll raise it to 60 degrees while you eat, then lower it afterward.\""}, {"id": "c", "text": "\"You need to stay lying flat in bed until the abduction pillow is removed.\""}, {"id": "d", "text": "\"I''ll raise it to 90 degrees so you can sit fully upright for lunch.\""}]'::jsonb, '["a"]', 'After a THR the head of the bed is not elevated above 45°, which helps prevent hip flexion past 90°. Raising it to 60° even briefly breaks this precaution, and lying completely flat is not required.', false),
  ('ortho', 5, 'A client who sustained a femur fracture 36 hours ago is awaiting surgery. The nurse finds the client newly confused, with an oxygen saturation that has fallen from 98% to 88%, and a petechial rash across the chest and axillae. Which complication is MOST likely?', '[{"id": "a", "text": "Pulmonary embolism"}, {"id": "b", "text": "Compartment syndrome"}, {"id": "c", "text": "Fat embolism syndrome"}, {"id": "d", "text": "Deep vein thrombosis (DVT)"}]'::jsonb, '["c"]', 'Hypoxia, confusion, and a petechial rash on the chest and axillae form the classic triad of fat embolism syndrome, which begins 24–72 hours after a long bone fracture. A pulmonary embolism presents with chest pain and dyspnea and does not cause a petechial rash.', false),
  ('ortho', 6, 'A client is admitted to the orthopedic unit after a total knee replacement. Which interventions should the nurse include in the plan of care to prevent venous thromboembolism (VTE)? Select all that apply.', '[{"id": "a", "text": "Apply sequential compression devices (SCDs)"}, {"id": "b", "text": "Give low molecular weight heparin (enoxaparin)"}, {"id": "c", "text": "Teach leg exercises: ankle pumps and foot circles"}, {"id": "d", "text": "Keep the client on bed rest for the first 48 hours"}, {"id": "e", "text": "Encourage early ambulation to walk ASAP"}]'::jsonb, '["a", "b", "c", "e"]', 'VTE prophylaxis includes SCDs or compression stockings (a), low molecular weight heparin such as enoxaparin (b), leg exercises such as ankle pumps and foot circles (c), and early ambulation (e). Bed rest (d) adds immobility, which is a cause of VTE, and delays in movement increase DVT risk.', true),
  ('ortho', 7, 'A client with a forearm fracture had a cast applied 8 hours ago. The client rates pain 9/10 despite two doses of IV morphine, reports tingling in the fingers, and says the cast feels tight. The radial pulse is weaker than earlier. Which complication is MOST likely?', '[{"id": "a", "text": "Deep vein thrombosis"}, {"id": "b", "text": "Fat embolism syndrome"}, {"id": "c", "text": "Expected fracture pain"}, {"id": "d", "text": "Compartment syndrome"}]'::jsonb, '["d"]', 'Severe pain unrelieved by medication, a tight cast, paresthesia, and a weakening pulse point to compartment syndrome, which is an emergency. This is not expected pain, because the pain is not relieved by medication and neurovascular signs are worsening.', false),
  ('ortho', 8, 'The nurse is preparing to reposition a client who had a right total hip replacement this morning and has an abduction pillow in place. Which approach is MOST appropriate?', '[{"id": "a", "text": "Turn toward the unaffected left side with an abduction pillow between the legs"}, {"id": "b", "text": "Turn onto the operative right side so the incision is supported by the mattress"}, {"id": "c", "text": "Turn toward the left side and allow the right leg to cross over for comfort"}, {"id": "d", "text": "Raise the head of the bed to 60 degrees first so the client can help with the turn"}]'::jsonb, '["a"]', 'After a THR the client is turned toward the unaffected side, here the left, with the abduction pillow keeping the leg abducted. Letting the right leg cross over violates the no-adduction precaution, and raising the head of the bed to 60° exceeds the 45° limit.', false),
  ('ortho', 9, 'A client is preparing for discharge after a total hip replacement. Which statements by the client indicate correct understanding of hip precautions? Select all that apply.', '[{"id": "a", "text": "\"I will avoid low chairs or toilets at home.\""}, {"id": "b", "text": "\"I''ll bend forward to put my shoes on each morning.\""}, {"id": "c", "text": "\"I won''t bend my hip past a right angle.\""}, {"id": "d", "text": "\"I''ll twist my torso to reach things behind me.\""}, {"id": "e", "text": "\"I''ll sit with my legs crossed to stay comfortable.\""}]'::jsonb, '["a", "c"]', 'Avoiding low chairs and toilets (a) and not bending the hip past a right angle, which means no flexion beyond 90° (c), are correct. Bending forward (b), twisting the torso (d), and crossing the legs (e) are all to be avoided, especially after a THR.', true),
  ('ortho', 10, 'On postoperative day 1 after a total knee replacement, a client asks why a machine is slowly bending and straightening the operative knee for several hours a day. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"It keeps the knee moving to prevent stiffness.\""}, {"id": "b", "text": "\"It keeps the leg abducted to prevent dislocation.\""}, {"id": "c", "text": "\"It holds the knee straight so the new joint can heal.\""}, {"id": "d", "text": "\"It replaces the need to walk until you go home.\""}]'::jsonb, '["a"]', 'The CPM (continuous passive motion) machine keeps the knee moving to prevent stiffness after a TKR. Keeping the leg abducted to prevent dislocation is the purpose of the abduction pillow after a hip replacement, and weight bearing still begins early.', false),
  ('ortho', 11, 'Two hours after a total knee replacement, the nurse checks the operative foot. The toes are pink and warm, the pedal pulse is present and strong, and the client can move and feel the toes. Capillary refill is 3 seconds. Which finding requires follow-up?', '[{"id": "a", "text": "Color"}, {"id": "b", "text": "Warmth of the skin"}, {"id": "c", "text": "Capillary refill"}, {"id": "d", "text": "Pedal pulses"}]'::jsonb, '["c"]', 'A normal capillary refill is under 2 seconds, so 3 seconds is outside the normal range and needs follow-up. Pink color, warmth, present and strong pulses, and intact movement and sensation are all normal.', false),
  ('ortho', 12, 'A client sustained a closed femur fracture 2 days ago and is being closely monitored for fat embolism syndrome. Which assessment findings would be consistent with this complication? Select all that apply.', '[{"id": "a", "text": "New confusion"}, {"id": "b", "text": "Unilateral calf swelling and redness"}, {"id": "c", "text": "Petechial rash on the chest and axillae"}, {"id": "d", "text": "Hypoxia with a falling O₂ saturation"}, {"id": "e", "text": "Severe pain unrelieved under a tight cast"}]'::jsonb, '["a", "c", "d"]', 'The classic triad of fat embolism syndrome is hypoxia (d), confusion (a), and a petechial rash on the chest and axillae (c). Calf swelling and redness (b) are DVT signs, and severe pain unrelieved under a tight cast (e) suggests compartment syndrome.', true),
  ('ortho', 13, 'A client with a femur fracture sustained 30 hours ago becomes restless and confused. Oxygen saturation has fallen from 97% to 87%, and a petechial rash is noted in the axillae. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Coach the client to use the incentive spirometer"}, {"id": "b", "text": "Start O₂ therapy and notify the provider"}, {"id": "c", "text": "Apply sequential compression devices to both legs"}, {"id": "d", "text": "Assist the client to ambulate to improve circulation"}]'::jsonb, '["b"]', 'Hypoxia, confusion, and a petechial rash 24–72 hours after a long bone fracture indicate fat embolism syndrome, which is managed with O₂ therapy and notifying the provider. The incentive spirometer is a prevention measure for pulmonary complications and will not correct this hypoxia.', false),
  ('ortho', 14, 'The evening after a total knee replacement, a client says, "My neighbor told me I would have to stay in bed for a week after this surgery." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Your neighbor is right; staying in bed protects the new knee joint.\""}, {"id": "b", "text": "\"You will stay in bed until the stiffness in your knee goes away.\""}, {"id": "c", "text": "\"Weight bearing may begin today or tomorrow with assistive devices.\""}, {"id": "d", "text": "\"You can walk without a walker once the CPM machine is stopped.\""}]'::jsonb, '["c"]', 'After a TKR, weight bearing may begin the same day or the next day with assistive devices, because delaying movement increases the risk of DVT and joint stiffness. Waiting for stiffness to resolve before walking would make the stiffness worse.', false),
  ('ortho', 15, 'A home health nurse visits a client who had a total hip replacement 1 week ago and walks with a walker. Which recommendations for fall prevention and hip safety are appropriate? Select all that apply.', '[{"id": "a", "text": "Place throw rugs over slippery spots on the floor"}, {"id": "b", "text": "Install grab bars in the bathroom"}, {"id": "c", "text": "Rest on the low, soft couch in the living room"}, {"id": "d", "text": "Keep clear pathways through each room"}, {"id": "e", "text": "Bend forward from the walker to pick up items"}]'::jsonb, '["b", "d"]', 'Fall prevention includes installing grab bars (b) and keeping pathways clear (d). Rugs should be avoided, not added (a). Low chairs and seats are avoided after a THR (c), and bending forward is not allowed (e).', true),
  ('ortho', 16, 'The nurse receives handoff report on four clients on an orthopedic unit. Which client should the nurse see FIRST?', '[{"id": "a", "text": "A client 1 day after a total knee replacement on the CPM machine who rates knee pain 4/10"}, {"id": "b", "text": "A client after a total hip replacement who asks to have the abduction pillow adjusted"}, {"id": "c", "text": "A client using the incentive spirometer who is reaching the target volume each hour"}, {"id": "d", "text": "A client 3 days after hip replacement with sudden chest pain and shortness of breath"}]'::jsonb, '["d"]', 'Sudden chest pain with shortness of breath suggests a pulmonary embolism, which is an airway and breathing emergency, and the provider is called immediately. The other clients are stable and have routine needs.', false),
  ('ortho', 17, 'On postoperative day 4 after a total hip replacement, a client reports aching in the operative calf. The calf is swollen, warm, and red. Oxygen saturation is 97%, and the client denies chest pain or shortness of breath. Which complication is MOST likely?', '[{"id": "a", "text": "Pulmonary embolism"}, {"id": "b", "text": "DVT of the leg"}, {"id": "c", "text": "Compartment syndrome"}, {"id": "d", "text": "Fat embolism syndrome"}]'::jsonb, '["b"]', 'Leg pain, swelling, warmth, and redness are DVT signs. A pulmonary embolism would cause chest pain, dyspnea, and a low O₂ saturation, and none of these are present.', false),
  ('ortho', 18, 'A client with a lower-leg cast applied yesterday calls the nurse to the room. Which findings would indicate compartment syndrome, an emergency that requires IMMEDIATE action? Select all that apply.', '[{"id": "a", "text": "Severe pain unrelieved by opioid doses"}, {"id": "b", "text": "Paresthesia of the toes"}, {"id": "c", "text": "Loss of the pedal pulse"}, {"id": "d", "text": "Petechial rash on the chest and axillae"}, {"id": "e", "text": "The cast feels tight around the leg"}]'::jsonb, '["a", "b", "c", "e"]', 'Compartment syndrome presents with severe pain unrelieved by medication (a), paresthesia (b), pulselessness or loss of pulse (c), and a tight cast or dressing (e). A petechial rash on the chest and axillae (d) belongs to fat embolism syndrome.', true),
  ('ortho', 19, 'A client 1 day after a total hip replacement is drowsy after opioid doses and is taking shallow breaths. Which intervention is MOST important to prevent a pulmonary complication?', '[{"id": "a", "text": "Encourage use of the incentive spirometer for deep breaths"}, {"id": "b", "text": "Apply sequential compression devices to both of the legs"}, {"id": "c", "text": "Place an abduction pillow between the client''s legs"}, {"id": "d", "text": "Raise the head of the bed to 90 degrees so breathing is easier"}]'::jsonb, '["a"]', 'The incentive spirometer encourages deep breaths and is the pulmonary hygiene measure for shallow breathing. SCDs prevent DVT, and raising the head of the bed to 90° would break the THR limit of 45°.', false),
  ('ortho', 20, 'A client 1 day after a total knee replacement, who is already walking with a walker, asks why daily enoxaparin injections are still needed. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Enoxaparin keeps your knee moving so it will not become stiff.\""}, {"id": "b", "text": "\"Once you walk, enoxaparin is given only to help control pain.\""}, {"id": "c", "text": "\"Enoxaparin prevents fat embolism until your fracture is stabilized.\""}, {"id": "d", "text": "\"Ortho surgery raises VTE risk from immobility and vessel injury.\""}]'::jsonb, '["d"]', 'Orthopedic surgery patients are at high risk for VTE because of immobility and vessel injury, so enoxaparin is continued along with early ambulation. Keeping the knee moving is the role of the CPM machine, and fat embolism is prevented by early fracture stabilization.', false),
  ('ortho', 21, 'On postoperative day 2 after a total knee replacement, the nurse is monitoring for pulmonary complications. Which findings should the nurse recognize as concerning for a pulmonary complication? Select all that apply.', '[{"id": "a", "text": "Decreased O₂ saturation"}, {"id": "b", "text": "Capillary refill <2 seconds"}, {"id": "c", "text": "New fever"}, {"id": "d", "text": "Mild knee stiffness"}, {"id": "e", "text": "Crackles"}]'::jsonb, '["a", "c", "e"]', 'With pulmonary hygiene the nurse monitors for decreased O₂ saturation (a), fever (c), and crackles (e). A capillary refill under 2 seconds is a normal neurovascular finding (b), and knee stiffness is what the CPM machine addresses, not a pulmonary sign (d).', true),
  ('ortho', 22, 'After the UAP repositions a client who had a left total hip replacement 6 hours ago, the nurse notes that the client''s left knee and foot are turned inward. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Reposition the leg out of internal rotation and keep it abducted"}, {"id": "b", "text": "Leave the leg as is because the abduction pillow is in place"}, {"id": "c", "text": "Raise the head of the bed to 60 degrees to relieve the strain"}, {"id": "d", "text": "Turn the client onto the left operative side to straighten the leg"}]'::jsonb, '["a"]', 'Internal rotation, meaning the leg twisted inward, is one of the three THR precautions, and the leg must be kept abducted to prevent dislocation. A pillow being in place does not make an inward-turned leg safe.', false),
  ('ortho', 23, 'A nurse is caring for four clients with long bone (femur) fractures. Based on the time since the fracture occurred, which client is MOST likely to show the onset of fat embolism syndrome at this time?', '[{"id": "a", "text": "Long bone fracture 10 hrs ago"}, {"id": "b", "text": "Long bone fracture 96 hrs ago"}, {"id": "c", "text": "Long bone fracture 2 weeks ago"}, {"id": "d", "text": "Long bone fracture 48 hrs ago"}]'::jsonb, '["d"]', 'Fat embolism syndrome begins 24–72 hours after a long bone fracture, and 48 hours falls within that window. Ten hours is earlier than the window, and 96 hours is later than it.', false),
  ('ortho', 24, 'A nurse is planning care for a client on the first day after a total knee replacement. Which interventions are appropriate to include in the plan? Select all that apply.', '[{"id": "a", "text": "Keep the knee immobilized for one week"}, {"id": "b", "text": "Use the CPM machine to keep the knee moving"}, {"id": "c", "text": "Begin weight bearing with assistive devices"}, {"id": "d", "text": "Follow provider orders for progression"}, {"id": "e", "text": "Use an abduction pillow to prevent knee dislocation"}]'::jsonb, '["b", "c", "d"]', 'TKR care includes the CPM machine to keep the knee moving (b), weight bearing with assistive devices starting the same day or the next day (c), and following provider orders for progression (d). Immobilizing the knee (a) increases the risk of DVT and stiffness, and the abduction pillow (e) is a hip replacement measure.', true),
  ('ortho', 25, 'A client with a femur fracture asks why the surgery to stabilize the fracture is scheduled for today rather than after waiting several days. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"Early surgery means the SCDs and enoxaparin won''t be needed.\""}, {"id": "b", "text": "\"Early fracture stabilization helps prevent fat embolism.\""}, {"id": "c", "text": "\"Early surgery lets us stop neurovascular checks sooner.\""}, {"id": "d", "text": "\"Waiting would mean wearing an abduction pillow for weeks.\""}]'::jsonb, '["b"]', 'Fat embolism syndrome is prevented with early fracture stabilization. VTE prophylaxis with SCDs and enoxaparin and neurovascular checks are still needed for all orthopedic clients after surgery.', false),
  ('ortho', 26, 'A nurse on an orthopedic unit is planning rounds after receiving report on four clients. Which client should the nurse assess FIRST?', '[{"id": "a", "text": "A client after hip replacement whose pain is 6/10 and due for an analgesic"}, {"id": "b", "text": "A client after knee replacement resting on the CPM machine with mild stiffness"}, {"id": "c", "text": "A client with a new forearm cast, pain unrelieved by meds, and paresthesia"}, {"id": "d", "text": "A client on enoxaparin who asks how to give the injections at home"}]'::jsonb, '["c"]', 'Severe pain unrelieved by medication with paresthesia under a new cast suggests compartment syndrome, which is an emergency. The client due for an analgesic has pain that is expected and controllable.', false),
  ('ortho', 27, 'A client 1 day after hip replacement is walking with a walker, wears SCDs in bed, and receives enoxaparin, but refuses the incentive spirometer because deep breaths hurt and has skipped coughing exercises. Which complication is this client MOST likely to develop?', '[{"id": "a", "text": "Atelectasis"}, {"id": "b", "text": "Deep vein thrombosis"}, {"id": "c", "text": "Compartment syndrome"}, {"id": "d", "text": "Fat embolism syndrome"}]'::jsonb, '["a"]', 'Atelectasis is a complication that postoperative orthopedic care aims to prevent, and the incentive spirometer with coughing and deep breathing is the prevention measure this client is refusing. DVT is less likely because the client is ambulating and receiving SCDs and enoxaparin.', false),
  ('ortho', 28, 'A client 2 days after a total hip replacement is sitting in a chair at the bedside and drops the call light on the floor. Which action by the client requires IMMEDIATE intervention?', '[{"id": "a", "text": "Ask the UAP to pick up the call light"}, {"id": "b", "text": "Keep the knees apart while seated"}, {"id": "c", "text": "Do ankle pumps while waiting for the UAP"}, {"id": "d", "text": "Bend forward to pick up the call light"}]'::jsonb, '["d"]', 'After a THR the client must not bend forward, because reaching to the floor flexes the hip past 90° and risks dislocation. Asking for help, keeping the knees apart, and doing ankle pumps are all safe.', false),
  ('ortho', 29, 'A client with a confirmed DVT in the operative leg 4 days after hip surgery suddenly develops chest pain and dyspnea, and the O₂ saturation is falling. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Compartment syndrome is developing in the operative leg"}, {"id": "b", "text": "Signs of a pulmonary embolism; call the provider now"}, {"id": "c", "text": "Fat embolism syndrome from the original surgery"}, {"id": "d", "text": "Atelectasis from shallow breathing after surgery"}]'::jsonb, '["b"]', 'Chest pain, dyspnea, and a low O₂ saturation are PE signs, and the provider is called now. Fat embolism syndrome would show confusion and a petechial rash and follows a long bone fracture, not a DVT.', false),
  ('ortho', 30, 'The nurse is planning care for a client on the first day after a total hip replacement. Which actions should the nurse include to prevent dislocation? Select all that apply.', '[{"id": "a", "text": "Keep the leg abducted with an abduction pillow"}, {"id": "b", "text": "Elevate HOB to 90° for each meal"}, {"id": "c", "text": "Do not elevate HOB more than 45°"}, {"id": "d", "text": "Turn toward the unaffected side"}, {"id": "e", "text": "Rotate the operative leg inward for comfort"}]'::jsonb, '["a", "c", "d"]', 'Keeping the leg abducted with an abduction pillow (a), keeping the head of the bed at 45° or less (c), and turning toward the unaffected side (d) are THR positioning measures. Raising the head of the bed to 90° (b) exceeds 45° and flexes the hip, and rotating the leg inward (e) is internal rotation, which is not allowed.', true),
  ('ortho', 31, 'The evening after a total knee replacement, a client receives teaching about activity during recovery. Which statement by the client indicates understanding?', '[{"id": "a", "text": "\"I should wait to walk until the stiffness in my knee goes away.\""}, {"id": "b", "text": "\"The CPM machine means I won''t need to walk this week.\""}, {"id": "c", "text": "\"Early movement lowers my risk of DVT and joint stiffness.\""}, {"id": "d", "text": "\"Keeping my knee still will help prevent contractures.\""}]'::jsonb, '["c"]', 'Early movement is encouraged after a TKR because delays increase the risk of DVT and joint stiffness. Keeping the knee still would promote, not prevent, the contractures that TKR care aims to avoid.', false),
  ('ortho', 32, 'A client who had a total hip replacement receives teaching about preventing blood clots after discharge. Which statements by the client indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"I''ll do ankle pumps and foot circles in bed.\""}, {"id": "b", "text": "\"Compression stockings help prevent clots.\""}, {"id": "c", "text": "\"I should stay in bed as much as I can to protect my hip.\""}, {"id": "d", "text": "\"Immobility and vessel injury raise my VTE risk.\""}, {"id": "e", "text": "\"I can leave the SCDs off in bed since I walked today.\""}]'::jsonb, '["a", "b", "d"]', 'Ankle pumps and foot circles (a) and compression stockings (b) are VTE prophylaxis measures, and immobility and vessel injury are the reasons orthopedic patients are at high risk (d). Staying in bed (c) contradicts walking as soon as possible to prevent clots. SCDs (e) remain part of prophylaxis while the client is in bed.', true),
  ('ortho', 33, 'A client returns from surgery after a left total knee replacement with a bulky dressing over the knee. Where should the nurse perform neurovascular checks to BEST detect impaired circulation?', '[{"id": "a", "text": "Left thigh, just above the bulky dressing"}, {"id": "b", "text": "Left foot and toes, distal to the surgical site"}, {"id": "c", "text": "Right foot only, used as the unaffected comparison"}, {"id": "d", "text": "Under the dressing, directly at the incision"}]'::jsonb, '["b"]', 'Neurovascular checks are performed distal to the surgical site, which for a left knee means the left foot and toes. The thigh is proximal to the surgery and would not reveal impaired circulation below the knee.', false),
  ('ortho', 34, 'Six hours after a long-leg cast is applied, a client can no longer move the toes or feel the nurse touching them, although pain is controlled with oral analgesics. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Expected numbness from swelling under a new cast"}, {"id": "b", "text": "Early signs of a deep vein thrombosis in the leg"}, {"id": "c", "text": "Early signs of fat embolism syndrome developing"}, {"id": "d", "text": "Possible nerve damage or compartment syndrome"}]'::jsonb, '["d"]', 'Loss of movement and sensation is a red flag for nerve damage or compartment syndrome, even when pain is controlled. Intact movement and sensation are the normal findings, so this is not an expected finding under a new cast.', false),
  ('ortho', 35, 'A client 1 day after a total knee replacement has been taking shallow breaths and has a new elevated temperature. Which nursing actions BEST promote pulmonary hygiene for this client? Select all that apply.', '[{"id": "a", "text": "Continue the CPM machine sessions"}, {"id": "b", "text": "Use the incentive spirometer"}, {"id": "c", "text": "Apply sequential compression devices"}, {"id": "d", "text": "Keep the abduction pillow in place"}, {"id": "e", "text": "Encourage coughing and deep breathing"}]'::jsonb, '["b", "e"]', 'Pulmonary hygiene includes the incentive spirometer (b) and encouraging coughing and deep breathing exercises (e). The CPM machine (a) prevents knee stiffness, SCDs (c) prevent VTE, and the abduction pillow (d) prevents hip dislocation, so none of them addresses the lungs.', true),
  ('ortho', 36, 'On the first day after a total hip replacement, a client rates incisional pain 7/10 and refuses to get out of bed for the scheduled walk with physical therapy. Which action by the nurse is BEST?', '[{"id": "a", "text": "Manage pain with analgesics, then encourage early ambulation"}, {"id": "b", "text": "Allow the client to stay in bed until the pain has fully resolved"}, {"id": "c", "text": "Postpone walking until the third postoperative day"}, {"id": "d", "text": "Raise the head of the bed to 90 degrees for comfort"}]'::jsonb, '["a"]', 'Pain management with analgesics and early ambulation are both postoperative orthopedic priorities, and walking as soon as possible prevents clots and restores function. Staying in bed until the pain resolves delays ambulation.', false),
  ('ortho', 37, 'After applying a new short-arm cast, the nurse documents: "Fingers pink and warm, radial pulse present and strong, capillary refill 1 second." Which assessment is MOST important to add to complete the neurovascular check?', '[{"id": "a", "text": "Blood pressure in the unaffected arm"}, {"id": "b", "text": "Oxygen saturation by pulse oximetry"}, {"id": "c", "text": "Movement and sensation of the fingers"}, {"id": "d", "text": "Fit of the cast compared with the other arm"}]'::jsonb, '["c"]', 'A neurovascular check covers circulation, movement, sensation, capillary refill, color, temperature, and pulses, so movement and sensation are still missing. Blood pressure and oxygen saturation are not part of the neurovascular check distal to the cast.', false),
  ('ortho', 38, 'A client who had a total hip replacement asks why the staff are so careful about how he is positioned in bed every time he is turned. Which reasons for careful positioning should the nurse include? Select all that apply.', '[{"id": "a", "text": "To prevent fat embolism syndrome"}, {"id": "b", "text": "To prevent joint dislocation"}, {"id": "c", "text": "To keep the knee moving to prevent stiffness"}, {"id": "d", "text": "To replace the need for neurovascular checks"}, {"id": "e", "text": "To prevent pressure injuries"}]'::jsonb, '["b", "e"]', 'Patient positioning is done to prevent joint dislocation (b) and pressure injuries (e). Fat embolism syndrome (a) is prevented by early fracture stabilization, keeping the knee moving (c) is the role of the CPM machine, and neurovascular checks (d) remain a priority for all orthopedic clients.', true),
  ('ortho', 39, 'The nurse is assigned four clients on an orthopedic unit and reviews the morning assessment data. Which client should the nurse see FIRST?', '[{"id": "a", "text": "A client 1 day after knee replacement who is due for the next CPM session"}, {"id": "b", "text": "A client 40 hrs after a long bone fracture with new confusion and hypoxia"}, {"id": "c", "text": "A client after a hip replacement who asks for help walking to the bathroom"}, {"id": "d", "text": "A client with a forearm cast whose fingers are pink, warm, and moving"}]'::jsonb, '["b"]', 'New confusion with hypoxia 24–72 hours after a long bone fracture suggests fat embolism syndrome, which needs O₂ therapy and notification of the provider. The client with pink, warm, moving fingers has a normal neurovascular check.', false),
  ('ortho', 40, 'On the first day after a total knee replacement, a client whose order reads weight bearing as tolerated with a walker wants to walk to the bathroom alone without the walker. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Walking is not allowed until the CPM machine is finished.\""}, {"id": "b", "text": "\"You may walk without the walker if your pain is controlled.\""}, {"id": "c", "text": "\"You must stay in bed until physical therapy has evaluated you.\""}, {"id": "d", "text": "\"Use the walker; we follow provider orders for progression.\""}]'::jsonb, '["d"]', 'After a TKR, weight bearing begins with assistive devices, and progression follows the provider''s orders. Pain control does not replace the ordered walker, and keeping the client in bed would delay early movement.', false),
  ('ortho', 41, 'A client 3 days after a total hip replacement is walking on the unit with a walker and preparing for discharge. Which actions by the client demonstrate safe practice? Select all that apply.', '[{"id": "a", "text": "Keep clear pathways while walking"}, {"id": "b", "text": "Avoid low chairs when sitting down"}, {"id": "c", "text": "Bend forward to pick up a slipper"}, {"id": "d", "text": "Cross the legs after sitting down"}, {"id": "e", "text": "Use grab bars installed at home"}]'::jsonb, '["a", "b", "e"]', 'Clear pathways (a) and grab bars (e) are fall-prevention measures, and avoiding low chairs (b) prevents hip flexion past 90°. Bending forward (c) and crossing the legs (d) are not allowed after a THR.', true),
  ('ortho', 42, 'A nurse provides fall-prevention teaching to a client going home after a total hip replacement. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"My son is installing grab bars next to the toilet.\""}, {"id": "b", "text": "\"I''ll keep the pathways in my house clear of clutter.\""}, {"id": "c", "text": "\"I''ll keep my throw rugs; they will cushion a fall.\""}, {"id": "d", "text": "\"I''ll use my walker each time I get up to walk.\""}]'::jsonb, '["c"]', 'Fall prevention includes avoiding rugs, so keeping throw rugs needs correction. Installing grab bars, keeping pathways clear, and using the walker are all correct.', false),
  ('ortho', 43, 'A client returns to the unit 2 hours after a total hip replacement and is still too drowsy to stand safely. Which action should the nurse teach FIRST to reduce the risk of VTE while the client is in bed?', '[{"id": "a", "text": "Leg exercises: ankle pumps and foot circles"}, {"id": "b", "text": "Crossing the legs at the ankles to aid circulation"}, {"id": "c", "text": "Raising the head of the bed past 45°"}, {"id": "d", "text": "Holding the leg still to protect the hip"}]'::jsonb, '["a"]', 'Leg exercises such as ankle pumps and foot circles are VTE prophylaxis that can be done in bed. Crossing the legs violates the no-adduction precaution, and holding the leg still adds immobility, which raises VTE risk.', false),
  ('ortho', 44, 'On postoperative day 5 after a total knee replacement, the nurse assesses the operative leg during morning rounds. Which findings would suggest a deep vein thrombosis (DVT)? Select all that apply.', '[{"id": "a", "text": "Leg pain"}, {"id": "b", "text": "Pale toes with absent pulses"}, {"id": "c", "text": "Swelling"}, {"id": "d", "text": "Warmth"}, {"id": "e", "text": "Redness"}]'::jsonb, '["a", "c", "d", "e"]', 'DVT signs are leg pain (a), swelling (c), warmth (d), and redness (e). Pale toes with absent pulses (b) point to poor perfusion, a neurovascular red flag, rather than the warm, red leg of a DVT.', true),
  ('ortho', 45, 'A client is in bed 1 day after a total knee replacement with sequential compression devices (SCDs) ordered. The nurse finds the UAP removing the SCDs because "the client walked this morning." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"That''s fine, since walking replaces the need for SCDs today.\""}, {"id": "b", "text": "\"Put the SCDs back on; they prevent VTE with immobility.\""}, {"id": "c", "text": "\"Remove them, but have the client do ankle pumps every hour.\""}, {"id": "d", "text": "\"Leave them off until the client reports leg pain or swelling.\""}]'::jsonb, '["b"]', 'Orthopedic clients are at high risk for VTE because of immobility, and SCDs are part of prophylaxis while the client is in bed, alongside early ambulation. Waiting for leg pain or swelling means waiting for DVT signs instead of preventing a DVT.', false),
  ('ortho', 46, 'The nurse reviews assessment findings for a client on postoperative day 3 after a total knee replacement. Which finding requires IMMEDIATE follow-up?', '[{"id": "a", "text": "Knee stiffness during the CPM session"}, {"id": "b", "text": "Incisional pain of 3/10 after an analgesic"}, {"id": "c", "text": "Capillary refill under 2 seconds in the toes"}, {"id": "d", "text": "New calf swelling, warmth, and redness"}]'::jsonb, '["d"]', 'Swelling, warmth, and redness in the leg are DVT signs. Stiffness is what the CPM machine is treating, controlled pain is expected, and a capillary refill under 2 seconds is normal.', false),
  ('ortho', 47, 'Four hours after a total hip replacement, a client needs to be turned but has severe pain with movement and cannot help. Which method of turning is BEST?', '[{"id": "a", "text": "Have the client pull up and roll onto the operative side"}, {"id": "b", "text": "Turn onto the operative side with the knees together"}, {"id": "c", "text": "Logroll toward the unaffected side with the pillow in place"}, {"id": "d", "text": "Raise the head of the bed to 70 degrees, then turn the client"}]'::jsonb, '["c"]', 'The THR client is turned toward the unaffected side, or logrolled if needed, with the abduction pillow keeping the leg abducted. Knees held together and a head of bed above 45° both break hip precautions.', false),
  ('ortho', 48, 'The nurse reviews assessment data for several orthopedic clients during the shift. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Mild stiffness in the first CPM session"}, {"id": "b", "text": "Incentive spirometer used 10 times an hour"}, {"id": "c", "text": "Absent pulse distal to a tight dressing"}, {"id": "d", "text": "Pale, cool toes distal to a new cast"}, {"id": "e", "text": "Abduction pillow in place, HOB at 30°"}]'::jsonb, '["c", "d"]', 'An absent or weak pulse is a red flag, and with a tight dressing it raises concern for compartment syndrome (c). Pale, cool toes indicate poor perfusion and poor circulation (d). Mild stiffness on the CPM machine (a), regular incentive spirometer use (b), and a pillow in place with the head of the bed under 45° (e) are expected or correct.', true),
  ('ortho', 49, 'A client 2 days after a total hip replacement is sitting in bed and wants the phone, which is on the bedside table behind the client. Which client action requires IMMEDIATE intervention by the nurse?', '[{"id": "a", "text": "Twist torso and bend forward to get the phone"}, {"id": "b", "text": "Ask the nurse to move the phone closer within reach"}, {"id": "c", "text": "Keep the abduction pillow between the legs"}, {"id": "d", "text": "Do ankle pumps while waiting for the phone"}]'::jsonb, '["a"]', 'After a THR the client must not twist the torso or bend forward, because these movements risk dislocation. Asking for help, keeping the pillow in place, and doing ankle pumps are all safe.', false),
  ('ortho', 50, 'A charge nurse observes a UAP caring for a client 1 day after a total hip replacement as lunch trays arrive. Which action by the UAP is MOST important for the charge nurse to correct?', '[{"id": "a", "text": "Elevate HOB to 45° for the lunch tray"}, {"id": "b", "text": "Keep the abduction pillow between the legs"}, {"id": "c", "text": "Turn toward the unaffected side for care"}, {"id": "d", "text": "Elevate HOB past 45° (to 70°) for lunch"}]'::jsonb, '["d"]', 'The head of the bed is not elevated above 45° after a THR, so raising it to 70° must be corrected, while 45° itself is within the limit. The abduction pillow and turning toward the unaffected side are correct care.', false),
  ('emerg_meds', 1, 'A 70-kg client with pneumonia is diagnosed with septic shock, with a BP of 82/46 mmHg and a heart rate of 120 bpm. IV antibiotics are infusing, and the provider prescribes an IV fluid bolus per the septic shock protocol. Which volume should the nurse prepare for the INITIAL bolus?', '[{"id": "a", "text": "700 mL"}, {"id": "b", "text": "1,400 mL"}, {"id": "c", "text": "2,100 mL"}, {"id": "d", "text": "3,000 mL"}]'::jsonb, '["c"]', 'Septic shock fluid resuscitation is a 30 mL/kg bolus: 30 mL × 70 kg = 2,100 mL. 1,400 mL would be only 20 mL/kg and 700 mL only 10 mL/kg.', false),
  ('emerg_meds', 2, 'A client admitted with cellulitis of the leg has a BP of 80/44 mmHg and a heart rate of 126 bpm, and septic shock is suspected. The airway is patent and oxygen is applied. Which prescription should the nurse give FIRST?', '[{"id": "a", "text": "Norepinephrine infusion"}, {"id": "b", "text": "Dopamine infusion"}, {"id": "c", "text": "Albumin infusion"}, {"id": "d", "text": "IV antibiotics"}]'::jsonb, '["d"]', 'In septic shock, IV antibiotics are the first priority. Norepinephrine and dopamine are vasopressors that support BP but do not come first, and albumin is reserved for when crystalloids are insufficient.', false),
  ('emerg_meds', 3, 'In the preoperative holding area, a client receives the prescribed IV antibiotic before incision. Within minutes the client develops hives, wheezing, and a BP of 76/42 mmHg. Which medication should the nurse prepare FIRST?', '[{"id": "a", "text": "Diphenhydramine IV"}, {"id": "b", "text": "Epinephrine IM"}, {"id": "c", "text": "Corticosteroids IV"}, {"id": "d", "text": "Atropine IV"}]'::jsonb, '["b"]', 'A severe allergy with low BP is anaphylactic shock, and epinephrine IM is first line. Diphenhydramine and corticosteroids are added after epinephrine, and atropine is for bradycardia or reducing secretions.', false),
  ('emerg_meds', 4, 'A client in anaphylactic shock after eating shellfish has just received epinephrine IM. Which additional interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Diphenhydramine"}, {"id": "b", "text": "Corticosteroids"}, {"id": "c", "text": "Atropine"}, {"id": "d", "text": "IV fluids and oxygen"}, {"id": "e", "text": "Monitor the airway and allergic response"}]'::jsonb, '["a", "b", "d", "e"]', 'After epinephrine IM, anaphylactic shock is treated with diphenhydramine (antihistamine), corticosteroids, IV fluids, and oxygen, and the nurse monitors the airway and allergic response. Atropine is used for bradycardia in neurogenic shock and to reduce secretions before surgery, not for anaphylaxis.', true),
  ('emerg_meds', 5, 'A client with a T4 spinal cord injury in neurogenic shock is receiving dopamine and was given atropine. The heart rate is now 62 bpm and the BP is 96/60 mmHg. Which additional assessment is MOST important for the nurse to include in ongoing monitoring?', '[{"id": "a", "text": "Signs of thrombotic events"}, {"id": "b", "text": "Bleeding and kidney injury"}, {"id": "c", "text": "Temperature regulation"}, {"id": "d", "text": "Headache and constipation"}]'::jsonb, '["c"]', 'In neurogenic shock the nurse monitors HR and temperature regulation. Thrombotic events are monitored with tranexamic acid, bleeding and kidney injury with ketorolac, and headache and constipation are ondansetron side effects.', false),
  ('emerg_meds', 6, 'A client who fell from a ladder has an acute cervical spinal cord injury, a BP of 84/48 mmHg, and a heart rate of 42 bpm. Which medication is the nurse MOST likely to administer for the heart rate?', '[{"id": "a", "text": "Dobutamine"}, {"id": "b", "text": "Atropine"}, {"id": "c", "text": "Diphenhydramine"}, {"id": "d", "text": "Protamine sulfate"}]'::jsonb, '["b"]', 'Neurogenic shock (spinal cord injury) is treated with atropine for bradycardia and vasopressors such as dopamine. Dobutamine increases contractility in cardiogenic shock, and protamine is the heparin antidote.', false),
  ('emerg_meds', 7, 'A client 1 day after an MI has a BP of 82/56 mmHg, cool skin, and decreasing urine output, and the provider states the heart is failing to pump. The provider wants a drug whose main action is to increase heart contractility. Which medication BEST matches this goal?', '[{"id": "a", "text": "Dopamine"}, {"id": "b", "text": "Dobutamine"}, {"id": "c", "text": "Norepinephrine"}, {"id": "d", "text": "Atropine"}]'::jsonb, '["b"]', 'Cardiogenic shock is often post-MI, and dobutamine increases heart contractility. Dopamine increases BP and cardiac output, norepinephrine is a vasopressor for septic shock, and atropine treats bradycardia.', false),
  ('emerg_meds', 8, 'A client in cardiogenic shock after an MI has a BP of 78/50 mmHg, and the provider documents fluid overload. Which medications should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "IV fluids as a 30 mL/kg bolus"}, {"id": "b", "text": "Dobutamine"}, {"id": "c", "text": "Diuretics"}, {"id": "d", "text": "Epinephrine IM"}, {"id": "e", "text": "Dopamine"}]'::jsonb, '["b", "c", "e"]', 'Cardiogenic shock is treated with dobutamine (↑ heart contractility), dopamine (↑ BP and cardiac output), and diuretics when fluid overload is present. The 30 mL/kg bolus is for septic shock and would worsen fluid overload, and epinephrine IM is first line for anaphylactic shock.', true),
  ('emerg_meds', 9, 'A client with penetrating chest trauma has a BP of 74/40 mmHg, a heart rate of 136 bpm, and falling oxygen saturation, and a tension pneumothorax is identified. Which intervention should the nurse prepare to assist with IMMEDIATELY?', '[{"id": "a", "text": "Pericardiocentesis"}, {"id": "b", "text": "Needle decompression"}, {"id": "c", "text": "Thrombolytic therapy"}, {"id": "d", "text": "Dobutamine infusion"}]'::jsonb, '["b"]', 'Tension pneumothorax causes obstructive shock and is treated with needle decompression. Pericardiocentesis treats cardiac tamponade, and thrombolytics treat a PE.', false),
  ('emerg_meds', 10, 'A client 4 hours after cardiac surgery has a BP of 72/50 mmHg and a heart rate of 130 bpm, and an echocardiogram shows cardiac tamponade. Which procedure is the nurse MOST likely to prepare the client for?', '[{"id": "a", "text": "Pericardiocentesis"}, {"id": "b", "text": "Needle decompression"}, {"id": "c", "text": "Anticoagulant therapy"}, {"id": "d", "text": "Albumin infusion"}]'::jsonb, '["a"]', 'Cardiac tamponade blocks blood flow (obstructive shock) and is treated with pericardiocentesis. Needle decompression is for tension pneumothorax and anticoagulants are for a PE.', false),
  ('emerg_meds', 11, 'An ED nurse is reviewing treatments with a nursing student who is caring for a client in obstructive shock. Which pairings of cause and treatment are correct? Select all that apply.', '[{"id": "a", "text": "Tension pneumothorax — needle decompression"}, {"id": "b", "text": "PE — pericardiocentesis"}, {"id": "c", "text": "Cardiac tamponade — pericardiocentesis"}, {"id": "d", "text": "Tension pneumothorax — thrombolytics"}, {"id": "e", "text": "PE — anticoagulants or thrombolytics"}]'::jsonb, '["a", "c", "e"]', 'Tension pneumothorax is treated with needle decompression, cardiac tamponade with pericardiocentesis, and a PE with anticoagulants or thrombolytics. Pericardiocentesis does not treat a PE, and thrombolytics do not relieve a tension pneumothorax.', true),
  ('emerg_meds', 12, 'A client in septic shock remains hypotensive after receiving 30 mL/kg of crystalloid fluids, and the provider adds albumin. Which statement by a nursing student about albumin indicates understanding?', '[{"id": "a", "text": "\"It prevents clot breakdown so bleeding is controlled more quickly.\""}, {"id": "b", "text": "\"It draws fluid into the vessels through oncotic pressure.\""}, {"id": "c", "text": "\"It reverses heparin so the bleeding will stop.\""}, {"id": "d", "text": "\"It increases heart contractility to raise the BP.\""}]'::jsonb, '["b"]', 'Albumin is a colloid that draws fluid into vessels via oncotic pressure, unlike crystalloids. Preventing clot breakdown describes tranexamic acid, and reversing heparin describes protamine sulfate.', false),
  ('emerg_meds', 13, 'A client with severe burns and hypoalbuminemia is receiving an albumin infusion after several liters of crystalloids. Which complication should the nurse monitor for MOST closely during this infusion?', '[{"id": "a", "text": "Thrombotic events"}, {"id": "b", "text": "Bradycardia and anaphylaxis"}, {"id": "c", "text": "Fluid overload"}, {"id": "d", "text": "Dry mouth and blurred vision"}]'::jsonb, '["c"]', 'Albumin expands volume by drawing fluid into vessels, so the nurse monitors for fluid overload. Thrombotic events are monitored with tranexamic acid, and bradycardia and anaphylaxis with protamine sulfate.', false),
  ('emerg_meds', 14, 'The nurse reviews new prescriptions for four clients in the ICU. For which client is an albumin infusion MOST appropriate?', '[{"id": "a", "text": "Trauma with active bleeding 1 hour after the injury occurred"}, {"id": "b", "text": "Septic shock that is still hypotensive after crystalloids"}, {"id": "c", "text": "Heparin overdose with oozing from the IV sites"}, {"id": "d", "text": "Spinal cord injury with a heart rate of 44 bpm"}]'::jsonb, '["b"]', 'Albumin is used for volume expansion in hypovolemic or septic shock when crystalloids are insufficient. Trauma bleeding within 3 hours calls for tranexamic acid, a heparin overdose for protamine sulfate, and bradycardia in spinal cord injury for atropine.', false),
  ('emerg_meds', 15, 'A client injured in a motor vehicle crash at 1310 arrives in the ED in hemorrhagic shock. At 1555, the provider prescribes tranexamic acid (TXA). Which action by the nurse is BEST?', '[{"id": "a", "text": "Give the TXA now; it is still within 3 hours of injury"}, {"id": "b", "text": "Hold the TXA, because more than 2 hours have passed since injury"}, {"id": "c", "text": "Give protamine sulfate instead to stop the bleeding"}, {"id": "d", "text": "Delay the TXA until the blood transfusion is complete"}]'::jsonb, '["a"]', 'TXA should be given within 3 hours of injury for best results; 1310 to 1555 is 2 hours 45 minutes, so it should be given now. Protamine reverses heparin and is not a trauma hemorrhage drug.', false),
  ('emerg_meds', 16, 'Four clients each have a BP below 85/50 mmHg. Which client''s findings are MOST consistent with a type of distributive shock?', '[{"id": "a", "text": "Spinal cord injury with a heart rate of 46 bpm"}, {"id": "b", "text": "Two days post-MI with cool skin and arrhythmias"}, {"id": "c", "text": "Chest trauma with a tension pneumothorax"}, {"id": "d", "text": "Burns over both legs with dehydration"}]'::jsonb, '["a"]', 'Distributive shock has three types, including neurogenic shock from a spinal cord injury, which often comes with bradycardia. Post-MI pump failure is cardiogenic, tension pneumothorax is obstructive, and burns with dehydration are hypovolemic.', false),
  ('emerg_meds', 17, 'A client with a pelvic fracture from a crash 90 minutes ago is in hemorrhagic shock, and tranexamic acid (TXA) is prescribed. Which statements by the nurse to the client''s spouse are accurate? Select all that apply.', '[{"id": "a", "text": "\"It reverses the effect of heparin.\""}, {"id": "b", "text": "\"It prevents clot breakdown.\""}, {"id": "c", "text": "\"It works best given within 3 hours of injury.\""}, {"id": "d", "text": "\"It draws fluid into the blood vessels.\""}, {"id": "e", "text": "\"We will watch for thrombotic events.\""}]'::jsonb, '["b", "c", "e"]', 'TXA is an antifibrinolytic that prevents clot breakdown in hemorrhagic shock and trauma, works best when given within 3 hours of injury, and requires monitoring for thrombotic events. Reversing heparin describes protamine sulfate, and drawing fluid into vessels describes albumin.', true),
  ('emerg_meds', 18, 'A client on a continuous heparin infusion accidentally received a large overdose and now has oozing from IV sites and blood in the urine. Which medication is the nurse MOST likely to prepare to reverse the anticoagulation?', '[{"id": "a", "text": "Tranexamic acid"}, {"id": "b", "text": "Albumin"}, {"id": "c", "text": "Protamine sulfate"}, {"id": "d", "text": "Packed RBCs"}]'::jsonb, '["c"]', 'Protamine sulfate is the heparin antidote used for heparin overdose. Tranexamic acid prevents clot breakdown in trauma and surgical bleeding but does not reverse heparin.', false),
  ('emerg_meds', 19, 'A client who received heparin during cardiac surgery is prescribed protamine sulfate in the ICU. Which finding in the client''s history should the nurse report to the provider before the drug is given?', '[{"id": "a", "text": "Ondansetron given for nausea"}, {"id": "b", "text": "Lorazepam given before surgery"}, {"id": "c", "text": "Allergy to penicillin"}, {"id": "d", "text": "Allergy to fish"}]'::jsonb, '["d"]', 'Protamine carries an anaphylaxis risk, especially in patients with fish allergy, so this must be reported first. The other history items are not the allergy the protamine warning names.', false),
  ('emerg_meds', 20, 'A nurse is preparing to give protamine sulfate to a client with a heparin overdose. Which action by the nurse requires IMMEDIATE correction?', '[{"id": "a", "text": "Pushing it rapidly IV to stop the bleeding sooner"}, {"id": "b", "text": "Asking the client about any history of fish allergy"}, {"id": "c", "text": "Having resuscitation equipment ready at the bedside"}, {"id": "d", "text": "Monitoring the BP and heart rate during the dose"}]'::jsonb, '["a"]', 'Protamine must be given slowly IV with resuscitation equipment ready because of hypotension, bradycardia, and anaphylaxis risk. Checking for fish allergy and monitoring BP and HR are correct.', false),
  ('emerg_meds', 21, 'A client is receiving protamine sulfate after cardiac surgery. Which findings would the nurse recognize as adverse effects of this drug that require follow-up? Select all that apply.', '[{"id": "a", "text": "BP of 82/48 (hypotension)"}, {"id": "b", "text": "New thrombotic events"}, {"id": "c", "text": "Heart rate of 48 bpm (bradycardia)"}, {"id": "d", "text": "Signs of anaphylaxis"}, {"id": "e", "text": "Signs of fluid overload"}]'::jsonb, '["a", "c", "d"]', 'Protamine requires monitoring for hypotension, bradycardia, and anaphylaxis. Thrombotic events are monitored with tranexamic acid, and fluid overload with albumin or IV fluids.', true),
  ('emerg_meds', 22, 'A client scheduled for a colectomy is to receive a prophylactic IV antibiotic in the preoperative area before incision. Which action is the nurse''s PRIORITY before giving it?', '[{"id": "a", "text": "Check for allergies"}, {"id": "b", "text": "Plan to give it after the incision"}, {"id": "c", "text": "Teach incentive spirometer use"}, {"id": "d", "text": "Give ondansetron for nausea"}]'::jsonb, '["a"]', 'Preoperative antibiotics are given before incision to prevent infection, and the nurse must watch for allergies. Antibiotics are given before incision, not after, and the other actions are unrelated to safe antibiotic administration.', false),
  ('emerg_meds', 23, 'A client received midazolam IV for preoperative anxiety 20 minutes ago. Which finding requires IMMEDIATE follow-up?', '[{"id": "a", "text": "Drowsy but responds to voice"}, {"id": "b", "text": "Reports a dry mouth"}, {"id": "c", "text": "Reports a mild headache"}, {"id": "d", "text": "Respiratory rate of 8/min"}]'::jsonb, '["d"]', 'Sedatives such as midazolam can cause respiratory depression, so a respiratory rate of 8/min needs immediate follow-up. Drowsiness is an expected side effect, dry mouth is an atropine effect, and headache is an ondansetron effect.', false),
  ('emerg_meds', 24, 'A client who received ondansetron before surgery to prevent nausea reports a dull headache on postoperative day 1. Vital signs are stable. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Headache is from the preoperative atropine"}, {"id": "b", "text": "Headache signals a reaction needing epinephrine"}, {"id": "c", "text": "Headache signals a thrombotic event from the drug"}, {"id": "d", "text": "Headache is a side effect of ondansetron"}]'::jsonb, '["d"]', 'Ondansetron is given to prevent anesthesia-related nausea, and its side effects include headache and constipation. Atropine causes dry mouth and blurred vision, not headache.', false),
  ('emerg_meds', 25, 'Before surgery, a client received atropine and now reports a very dry mouth and blurred vision. The client asks why the medication was needed. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"It reduces secretions during surgery.\""}, {"id": "b", "text": "\"It prevents nausea from the anesthesia.\""}, {"id": "c", "text": "\"It calms your anxiety before surgery.\""}, {"id": "d", "text": "\"It treats a slow heart rate from shock.\""}]'::jsonb, '["a"]', 'Preoperative atropine is an anticholinergic given to reduce secretions during surgery, and dry mouth and blurred vision are its side effects. Preventing nausea describes ondansetron, and calming anxiety describes midazolam or lorazepam.', false),
  ('emerg_meds', 26, 'A nurse checks on several clients 1 hour after each received a preoperative medication. All have stable vital signs. Which client reports reflect an expected side effect of the medication received? Select all that apply.', '[{"id": "a", "text": "After midazolam: \"I feel such drowsiness.\""}, {"id": "b", "text": "After ondansetron: \"My mouth is so dry.\""}, {"id": "c", "text": "After ondansetron: \"I have a headache.\""}, {"id": "d", "text": "After atropine: \"My mouth is really dry.\""}, {"id": "e", "text": "After atropine: \"My vision is blurry.\""}]'::jsonb, '["a", "c", "d", "e"]', 'Midazolam can cause drowsiness (and respiratory depression), ondansetron can cause headache and constipation, and atropine can cause dry mouth and blurred vision. Dry mouth is an atropine side effect, not an ondansetron side effect.', true),
  ('emerg_meds', 27, 'A client 3 hours after abdominal surgery has a BP of 86/50 mmHg (preoperative 128/78), a heart rate of 124 bpm, and 20 mL of urine in the last hour. The dressing is dry. Which prescription should the nurse anticipate FIRST?', '[{"id": "a", "text": "Bladder scan"}, {"id": "b", "text": "IV fluids"}, {"id": "c", "text": "Straight catheterization"}, {"id": "d", "text": "Ketorolac IV"}]'::jsonb, '["b"]', 'Low BP with a fast HR after surgery are signs of bleeding or hypotension, treated with IV fluids and, if needed, blood transfusion. A bladder scan and straight catheterization are for urinary retention with no urine output, and this client is producing urine.', false),
  ('emerg_meds', 28, 'A client on postoperative day 1 has bloody drainage increasing on the dressing and a heart rate that has risen from 88 to 110 bpm. Which prescribed medication is MOST important for the nurse to clarify with the provider?', '[{"id": "a", "text": "Morphine"}, {"id": "b", "text": "Ondansetron"}, {"id": "c", "text": "Ketorolac"}, {"id": "d", "text": "Hydromorphone"}]'::jsonb, '["c"]', 'NSAIDs such as ketorolac carry a risk of bleeding and kidney injury, which is dangerous with signs of postoperative bleeding. Morphine and hydromorphone require monitoring for respiratory depression but do not increase bleeding.', false),
  ('emerg_meds', 29, 'A client using a hydromorphone PCA after a laparotomy is difficult to arouse, with a respiratory rate of 8/min and shallow breathing. Which complication is the nurse MOST likely observing?', '[{"id": "a", "text": "Atelectasis from poor incentive spirometer use"}, {"id": "b", "text": "Anaphylaxis to the hydromorphone"}, {"id": "c", "text": "Bleeding from the surgical site"}, {"id": "d", "text": "Opioid-related respiratory depression"}]'::jsonb, '["d"]', 'Opioids such as hydromorphone and morphine require monitoring for respiratory depression, which fits a slow respiratory rate with sedation. Atelectasis does not explain the decreased level of arousal after an opioid.', false),
  ('emerg_meds', 30, 'A client 8 hours after a hernia repair has had no urine output since surgery and reports lower abdominal fullness. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Insert a straight catheter"}, {"id": "b", "text": "Perform a bladder scan"}, {"id": "c", "text": "Give an IV diuretic"}, {"id": "d", "text": "Increase the IV fluid rate"}]'::jsonb, '["b"]', 'For no urine output after surgery, a bladder scan is done first, then straight catheterization if needed. Catheterizing before scanning skips the first step.', false),
  ('emerg_meds', 31, 'A client on postoperative day 2 after a cholecystectomy has diminished breath sounds at the bases, low oxygen saturation, and atelectasis on chest x-ray. Which interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Incentive spirometer"}, {"id": "b", "text": "Bladder scan"}, {"id": "c", "text": "Bed rest until the lungs clear"}, {"id": "d", "text": "Early ambulation"}, {"id": "e", "text": "Oxygen therapy"}]'::jsonb, '["a", "d", "e"]', 'Respiratory issues such as atelectasis are managed with an incentive spirometer, early ambulation, and oxygen therapy if needed, as with this low oxygen saturation. A bladder scan is for urinary retention, and bed rest contradicts early ambulation.', true),
  ('emerg_meds', 32, 'A postoperative client''s urine output has dropped since surgery, and the provider has documented early kidney injury. Several analgesics are prescribed. Which prescription requires follow-up with the provider?', '[{"id": "a", "text": "Morphine"}, {"id": "b", "text": "Ketorolac"}, {"id": "c", "text": "Hydromorphone"}, {"id": "d", "text": "Ondansetron"}]'::jsonb, '["b"]', 'Ketorolac, an NSAID, carries a risk of bleeding and kidney injury, so it requires follow-up in a client with kidney injury. Morphine and hydromorphone are monitored for respiratory depression, and ondansetron is an antiemetic.', false),
  ('emerg_meds', 33, 'A client in hypovolemic shock from a GI bleed is receiving rapid NS boluses and 2 units of packed RBCs. Which complications of this treatment should the nurse monitor for? Select all that apply.', '[{"id": "a", "text": "Fluid overload"}, {"id": "b", "text": "Thrombotic events"}, {"id": "c", "text": "Temperature regulation problems"}, {"id": "d", "text": "Allergic reaction to blood"}, {"id": "e", "text": "Headache and constipation"}]'::jsonb, '["a", "d"]', 'IV fluids and blood products for hypovolemic shock carry risks of fluid overload and allergic reaction to blood. Thrombotic events are a tranexamic acid concern, temperature regulation is monitored in neurogenic shock, and headache and constipation are ondansetron side effects.', true),
  ('emerg_meds', 34, 'A client with extensive burns remains hypotensive after several liters of NS and LR. Which plan BEST reflects the next step in volume replacement?', '[{"id": "a", "text": "Switch to dobutamine to increase contractility"}, {"id": "b", "text": "Give tranexamic acid to expand the volume"}, {"id": "c", "text": "Add albumin, since crystalloids are insufficient"}, {"id": "d", "text": "Start diuretics to prevent fluid overload"}]'::jsonb, '["c"]', 'Albumin is a colloid used for volume expansion when crystalloids are insufficient and is used in burns. Tranexamic acid prevents clot breakdown and does not expand volume.', false),
  ('emerg_meds', 35, 'A 70-kg client in septic shock received IV antibiotics and a 2,100-mL fluid bolus. The BP remains 78/44 mmHg. Which prescription should the nurse anticipate NEXT?', '[{"id": "a", "text": "Norepinephrine"}, {"id": "b", "text": "Dobutamine"}, {"id": "c", "text": "Epinephrine IM"}, {"id": "d", "text": "Diuretics"}]'::jsonb, '["a"]', 'After antibiotics and the 30 mL/kg bolus, septic shock that remains hypotensive is treated with vasopressors such as norepinephrine or dopamine. Dobutamine is for cardiogenic shock, and epinephrine IM is first line for anaphylaxis.', false),
  ('emerg_meds', 36, 'A 60-kg client is admitted with septic shock from a urinary tract infection. Which prescriptions should the nurse expect? Select all that apply.', '[{"id": "a", "text": "Epinephrine IM"}, {"id": "b", "text": "IV antibiotics"}, {"id": "c", "text": "1,800 mL IV fluid bolus"}, {"id": "d", "text": "600 mL IV fluid bolus"}, {"id": "e", "text": "Norepinephrine"}]'::jsonb, '["b", "c", "e"]', 'Septic shock is treated with IV antibiotics (first priority), a 30 mL/kg IV fluid bolus (30 × 60 kg = 1,800 mL), and vasopressors such as norepinephrine. A 600-mL bolus is only 10 mL/kg, and epinephrine IM is first line for anaphylactic shock.', true),
  ('emerg_meds', 37, 'A client in cardiogenic shock after an MI is started on dopamine. One hour later, which finding BEST indicates the drug is having its intended effect?', '[{"id": "a", "text": "Heart rate down from 112 to 48 bpm"}, {"id": "b", "text": "New irregular heart rhythm"}, {"id": "c", "text": "Dry mouth and blurred vision"}, {"id": "d", "text": "BP up from 78/48 to 96/60 mmHg"}]'::jsonb, '["d"]', 'Dopamine increases BP and cardiac output, so a rising BP shows the intended effect. A new irregular rhythm suggests an arrhythmia, a risk in cardiogenic shock, and dry mouth with blurred vision are atropine effects.', false),
  ('emerg_meds', 38, 'The nurse receives report on four postoperative clients. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Dry mouth and blurred vision after preoperative atropine"}, {"id": "b", "text": "Mild headache after receiving ondansetron for nausea"}, {"id": "c", "text": "BP 84/50 mmHg and HR 128 bpm, 2 hours after surgery"}, {"id": "d", "text": "Wants to skip incentive spirometer use due to pain"}]'::jsonb, '["c"]', 'Low BP with a fast HR after surgery are signs of bleeding or hypotension, requiring IV fluids and possibly blood transfusion. Dry mouth, blurred vision, and headache are expected side effects of atropine and ondansetron.', false),
  ('emerg_meds', 39, 'A client 9 hours after knee surgery has not voided since surgery and reports suprapubic discomfort. Which actions are appropriate for this client''s urine output problem? Select all that apply.', '[{"id": "a", "text": "Give an IV diuretic"}, {"id": "b", "text": "Perform a bladder scan first"}, {"id": "c", "text": "Straight catheterization if retention is confirmed"}, {"id": "d", "text": "Increase IV fluids to prompt voiding"}, {"id": "e", "text": "Give ketorolac for the discomfort"}]'::jsonb, '["b", "c"]', 'No urine output after surgery is managed with a bladder scan first, then straight catheterization if needed. A diuretic or more IV fluids does not relieve retention, and ketorolac carries a risk of kidney injury and does not treat retention.', true),
  ('emerg_meds', 40, 'A client 2 days after hip surgery develops sudden dyspnea and hypotension, and a pulmonary embolism (PE) is confirmed. Thrombolytic therapy is started. Which assessment is the nurse''s PRIORITY?', '[{"id": "a", "text": "Signs of fluid overload"}, {"id": "b", "text": "Temperature regulation"}, {"id": "c", "text": "Oxygenation status"}, {"id": "d", "text": "Kidney injury"}]'::jsonb, '["c"]', 'A PE causes obstructive shock, an emergency in which oxygenation must be monitored closely. Fluid overload is the albumin concern, and temperature regulation is monitored in neurogenic shock.', false),
  ('emerg_meds', 41, 'A client with an acute spinal cord injury has a BP of 80/46 mmHg and a heart rate of 44 bpm. Which interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Atropine"}, {"id": "b", "text": "Epinephrine IM"}, {"id": "c", "text": "Dopamine"}, {"id": "d", "text": "Monitor heart rate"}, {"id": "e", "text": "Monitor temperature regulation"}]'::jsonb, '["a", "c", "d", "e"]', 'Neurogenic shock is treated with atropine for bradycardia and vasopressors such as dopamine, and the nurse monitors HR and temperature regulation. Epinephrine IM is first line for anaphylactic shock.', true),
  ('emerg_meds', 42, 'A client who had anaphylactic shock after a contrast dye injection received epinephrine IM, diphenhydramine, and corticosteroids 30 minutes ago. The BP is now 104/66 mmHg, but the client reports a hoarse voice and throat tightness. Which action is the nurse''s PRIORITY?', '[{"id": "a", "text": "Monitor the airway closely"}, {"id": "b", "text": "Document that the BP has stabilized"}, {"id": "c", "text": "Give atropine for the heart rate"}, {"id": "d", "text": "Start albumin for volume expansion"}]'::jsonb, '["a"]', 'In anaphylactic shock the nurse monitors the airway and allergic response; throat tightness and hoarseness signal an airway problem even though the BP has improved. Atropine is for bradycardia and albumin is for volume expansion when crystalloids are insufficient.', false),
  ('emerg_meds', 43, 'A client 2 hours after a total knee replacement has a drain filling with blood, a BP of 80/48 mmHg, and a heart rate of 128 bpm. Which prescriptions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Ketorolac for pain"}, {"id": "b", "text": "IV fluids"}, {"id": "c", "text": "Diuretics"}, {"id": "d", "text": "Blood transfusion"}, {"id": "e", "text": "Dobutamine"}]'::jsonb, '["b", "d"]', 'Postoperative bleeding with low BP and fast HR is treated with IV fluids and blood transfusion. Ketorolac increases the risk of bleeding, diuretics are for fluid overload in cardiogenic shock, and dobutamine increases contractility in cardiogenic shock.', true),
  ('emerg_meds', 44, 'A marathon runner collapses with severe dehydration, a BP of 84/50 mmHg, a heart rate of 122 bpm, and no signs of bleeding. Which prescription is the BEST initial treatment?', '[{"id": "a", "text": "Albumin infusion"}, {"id": "b", "text": "Packed RBCs"}, {"id": "c", "text": "IV fluids such as NS or LR"}, {"id": "d", "text": "Dobutamine infusion"}]'::jsonb, '["c"]', 'Dehydration causes hypovolemic shock, treated with IV fluids (NS, LR); blood products are for bleeding. Albumin is added only when crystalloids are insufficient.', false),
  ('emerg_meds', 45, 'A client 10 hours after surgery has not voided. A bladder scan shows a large volume of retained urine, and the client cannot void after being assisted to the bathroom. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Repeat the bladder scan in 4 hours"}, {"id": "b", "text": "Give an IV diuretic"}, {"id": "c", "text": "Increase the IV fluid rate"}, {"id": "d", "text": "Straight catheterization"}]'::jsonb, '["d"]', 'After the bladder scan confirms retention, straight catheterization is performed if needed. Repeating the scan delays relief, and diuretics or extra fluids do not treat retention.', false),
  ('emerg_meds', 46, 'A client is in hemorrhagic shock 1 hour after a motorcycle crash. Which prescriptions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Protamine sulfate"}, {"id": "b", "text": "IV fluids (NS, LR)"}, {"id": "c", "text": "Dobutamine"}, {"id": "d", "text": "Packed RBCs"}, {"id": "e", "text": "Tranexamic acid (TXA)"}]'::jsonb, '["b", "d", "e"]', 'Hypovolemic (hemorrhagic) shock is treated with IV fluids (NS, LR) and packed RBCs, and TXA is used in hemorrhagic shock and trauma within 3 hours of injury. Protamine reverses heparin, and dobutamine increases contractility in cardiogenic shock.', true),
  ('emerg_meds', 47, 'A client on postoperative day 1 after abdominal surgery has diminished breath sounds at the bases. The nurse teaches about preventing atelectasis. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I can skip early ambulation and use oxygen instead.\""}, {"id": "b", "text": "\"I''ll use my incentive spirometer as I was shown.\""}, {"id": "c", "text": "\"I''ll walk in the hallway with help later today.\""}, {"id": "d", "text": "\"I''ll keep the oxygen on if the nurse says I need it.\""}]'::jsonb, '["a"]', 'Atelectasis is managed with an incentive spirometer, early ambulation, and oxygen therapy if needed; oxygen does not replace early ambulation. The other statements are correct.', false),
  ('emerg_meds', 48, 'A client after a bowel resection is receiving morphine and ketorolac for pain. Which assessments are MOST important for the nurse to monitor related to these medications? Select all that apply.', '[{"id": "a", "text": "Dry mouth and blurred vision"}, {"id": "b", "text": "Respiratory depression"}, {"id": "c", "text": "Temperature regulation"}, {"id": "d", "text": "Signs of bleeding"}, {"id": "e", "text": "Kidney injury"}]'::jsonb, '["b", "d", "e"]', 'Opioids such as morphine require monitoring for respiratory depression, and ketorolac carries a risk of bleeding and kidney injury. Dry mouth and blurred vision are atropine side effects, and temperature regulation is monitored in neurogenic shock.', true),
  ('emerg_meds', 49, 'The nurse reviews five clients for whom albumin has been prescribed. Which clients are appropriate candidates for albumin? Select all that apply.', '[{"id": "a", "text": "Severe sepsis, hypotensive despite crystalloids"}, {"id": "b", "text": "Severe burns"}, {"id": "c", "text": "Heparin overdose with oozing IV sites"}, {"id": "d", "text": "Liver failure"}, {"id": "e", "text": "Hypoalbuminemia"}]'::jsonb, '["a", "b", "d", "e"]', 'Albumin is used for volume expansion in septic shock when crystalloids are insufficient, and in burns, liver failure, and hypoalbuminemia. A heparin overdose is treated with protamine sulfate, the heparin antidote.', true),
  ('emerg_meds', 50, 'A 75-kg client with septic shock from pneumonia has a BP of 78/42 mmHg and a patent airway on oxygen. Which sequence of prescriptions BEST reflects the treatment priorities?', '[{"id": "a", "text": "Norepinephrine, then a 2,250-mL fluid bolus, then IV antibiotics"}, {"id": "b", "text": "A 750-mL fluid bolus, then IV antibiotics, then a dopamine infusion"}, {"id": "c", "text": "IV antibiotics, then dobutamine, then a 2,250-mL fluid bolus"}, {"id": "d", "text": "IV antibiotics, then a 2,250-mL fluid bolus, then norepinephrine"}]'::jsonb, '["d"]', 'IV antibiotics are the first priority in septic shock, followed by a 30 mL/kg bolus (30 × 75 kg = 2,250 mL) and then vasopressors such as norepinephrine. A 750-mL bolus is only 10 mL/kg, and dobutamine is for cardiogenic shock.', false),
  ('priorities', 1, 'The nurse receives change-of-shift report on four post-op clients. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Client with stridor and inability to speak"}, {"id": "b", "text": "Client with RR 24/min and low SpO₂"}, {"id": "c", "text": "Client with BP 92/58 mm Hg, HR 108/min, and pallor"}, {"id": "d", "text": "Client at high fall risk who is trying to get up"}]'::jsonb, '["a"]', 'Stridor with inability to speak is an airway problem, and airway is addressed before breathing and circulation. RR >20 with low SpO₂ is a breathing problem, which comes second in the ABC framework.', false),
  ('priorities', 2, 'A client 1 day after abdominal surgery shares several concerns with the nurse. According to Maslow''s hierarchy, which needs are at the HIGHEST priority level? Select all that apply.', '[{"id": "a", "text": "Elimination: has not voided for 8 hours"}, {"id": "b", "text": "Social support: wants church friends to visit"}, {"id": "c", "text": "Sleep needs not met for 2 nights"}, {"id": "d", "text": "Dignity: embarrassed by the hospital gown"}, {"id": "e", "text": "Personal growth: worried about a degree"}]'::jsonb, '["a", "c"]', 'Physiological needs such as elimination (a) and sleep (c) are the HIGHEST Maslow level and are addressed first. Social support (b) is love/belonging, dignity (d) is esteem, and personal growth (e) is self-actualization, the lowest priority in acute care.', true),
  ('priorities', 3, 'A nurse on a surgical unit is assigned four clients. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Pain rated 9/10; requesting medication"}, {"id": "b", "text": "HR 112/min, BP 96/58 mm Hg, pallor"}, {"id": "c", "text": "RR 9/min on a hydromorphone PCA"}, {"id": "d", "text": "Anxious and tearful about discharge"}]'::jsonb, '["c"]', 'An RR below 12 is a breathing problem, and breathing is addressed before circulation. The client with tachycardia, hypotension, and pallor has a circulation problem, which is third in the ABC framework.', false),
  ('priorities', 4, 'Four clients on a surgical unit all have an open airway and adequate breathing. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Client rating pain 9/10 who is requesting medication"}, {"id": "b", "text": "Client with tachycardia, low BP, and abdominal distension"}, {"id": "c", "text": "Client at fall risk who is unsteady when standing up alone"}, {"id": "d", "text": "Client who is crying about a new cancer diagnosis"}]'::jsonb, '["b"]', 'Tachycardia, low BP, and abdominal distension suggest hemorrhage, a circulation problem that is life-threatening. Pain, fall risk, and anxiety fall under ''everything else'' (safety, pain, psychosocial), which comes after airway, breathing, and circulation.', false),
  ('priorities', 5, 'An RN is working with a UAP and is assigned a stable client on post-op day 3 who is receiving morphine for pain. Which tasks can the RN delegate to the UAP? Select all that apply.', '[{"id": "a", "text": "Reassessment of pain after morphine"}, {"id": "b", "text": "Vital signs for the stable client"}, {"id": "c", "text": "Teaching incentive spirometer use"}, {"id": "d", "text": "I&O measurement"}, {"id": "e", "text": "Routine specimen collection"}]'::jsonb, '["b", "d", "e"]', 'Vital signs for stable patients (b), I&O measurement (d), and routine specimen collection (e) can be delegated to a UAP. Reassessment (a) and patient teaching (c) are RN-only parts of the nursing process.', true),
  ('priorities', 6, 'A client 1 day after a lobectomy has an SpO₂ that has dropped from 95% to 87%. The client is crying, says, "I am so scared," and asks the nurse to call the chaplain. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Sit with the client and explore the fears"}, {"id": "b", "text": "Call the chaplain for social support"}, {"id": "c", "text": "Teach the client about the lobectomy"}, {"id": "d", "text": "Treat the hypoxia"}]'::jsonb, '["d"]', 'Maslow''s physiological needs come FIRST; when a patient is hypoxic AND anxious, the nurse treats the hypoxia first. Exploring fears and calling the chaplain address psychosocial and love/belonging needs, which come after physical needs are met.', false),
  ('priorities', 7, 'The nurse is planning care for four stable clients, each with a different need. According to Maslow''s hierarchy, which client need should the nurse address FIRST?', '[{"id": "a", "text": "Fall prevention: climbing over the rails"}, {"id": "b", "text": "Family connections: requesting a visit from friends"}, {"id": "c", "text": "Dignity: upset about wearing a hospital gown"}, {"id": "d", "text": "Personal growth: discussing future career goals"}]'::jsonb, '["a"]', 'Fall prevention (physical safety) is the second Maslow level and comes before love/belonging, esteem, and self-actualization. Family connections are a love/belonging need, addressed only after physical needs are met.', false),
  ('priorities', 8, 'A client on post-op day 2 is using a morphine PCA. Which assessment findings require IMMEDIATE follow-up by the nurse? Select all that apply.', '[{"id": "a", "text": "No bowel movement since surgery"}, {"id": "b", "text": "RR 10/min"}, {"id": "c", "text": "Mild nausea after breakfast"}, {"id": "d", "text": "Sedation"}, {"id": "e", "text": "Low SpO₂"}]'::jsonb, '["b", "d", "e"]', 'Clients on opioids are monitored for respiratory depression (RR <12/min) (b), sedation (d), and low SpO₂ (e), which require immediate follow-up. Constipation (a) and nausea (c) are expected opioid side effects that are not immediately life-threatening.', true),
  ('priorities', 9, 'The RN is making assignments for a UAP on a busy surgical unit. Which task is MOST appropriate for the RN to delegate to the UAP?', '[{"id": "a", "text": "Vital signs on a client whose BP is trending down"}, {"id": "b", "text": "Teaching a client to use the incentive spirometer"}, {"id": "c", "text": "Postmortem care after a death"}, {"id": "d", "text": "Developing the care plan for a new admission"}]'::jsonb, '["c"]', 'Postmortem care may be delegated to the UAP. Vital signs can be delegated only for stable patients, so a client with a falling BP needs the RN; teaching and care plan creation are RN-only.', false),
  ('priorities', 10, 'The charge nurse reviews the tasks an RN has delegated to a UAP for four stable clients. Which delegated task requires correction by the charge nurse?', '[{"id": "a", "text": "Bathing a client who is 2 days after surgery"}, {"id": "b", "text": "Evaluation of pain medication outcomes"}, {"id": "c", "text": "Measuring I&O for a client with IV fluids"}, {"id": "d", "text": "Collecting a routine urine specimen"}]'::jsonb, '["b"]', 'Deciding whether a medication worked is evaluation of outcomes (and reassessment), which the RN cannot delegate. Bathing (ADLs), I&O measurement, and routine specimen collection can be delegated to a UAP for stable patients.', false),
  ('priorities', 11, 'The nurse is performing a sterile dressing change on a client''s abdominal incision. Which events result in contamination of the sterile field? Select all that apply.', '[{"id": "a", "text": "Sterile field out of sight"}, {"id": "b", "text": "Sterile glove touches sterile gauze"}, {"id": "c", "text": "Saline wets the sterile drape"}, {"id": "d", "text": "Bare hand touches sterile item"}, {"id": "e", "text": "Sterile field dry and in view"}]'::jsonb, '["a", "c", "d"]', 'Anything out of sight (a) or wet (c) is contaminated, and a bare hand touching a sterile item (d) breaks the rule that sterile touches sterile only. A sterile glove touching sterile gauze (b) and a field kept dry and in view (e) remain sterile.', true),
  ('priorities', 12, 'A client 1 day after abdominal surgery is asleep with a morphine PCA. The nurse observes the client''s daughter pressing the PCA button and saying, "I want to keep him ahead of the pain." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Press it only when he looks uncomfortable.\""}, {"id": "b", "text": "\"Only he should press it; it risks oversedation.\""}, {"id": "c", "text": "\"The lockout makes it safe for you to press it for him.\""}, {"id": "d", "text": "\"Press it once an hour while he is sleeping.\""}]'::jsonb, '["b"]', 'Family must NOT press the PCA button because of the risk of oversedation; only the patient presses. The lockout interval prevents overdose of self-administered doses, but it does not make family-controlled dosing safe.', false),
  ('priorities', 13, 'The nurse teaches a client about a hydromorphone PCA pump before surgery. Which statement by the client indicates understanding of the teaching?', '[{"id": "a", "text": "\"My husband can press the button for me if I am asleep.\""}, {"id": "b", "text": "\"The pump gives a dose every time I press it.\""}, {"id": "c", "text": "\"The PCA is used for non-opioid pain medicine.\""}, {"id": "d", "text": "\"The lockout interval keeps me from an overdose.\""}]'::jsonb, '["d"]', 'A lockout interval prevents overdose, so not every button press delivers a dose. Family must not press the button, and PCA pumps are common with opioids such as morphine and hydromorphone.', false),
  ('priorities', 14, 'A client who has had prolonged vomiting has low serum potassium and low serum magnesium levels. Which findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "↓ DTRs"}, {"id": "b", "text": "Muscle cramps"}, {"id": "c", "text": "Tremors"}, {"id": "d", "text": "Tall T waves"}, {"id": "e", "text": "Arrhythmias"}]'::jsonb, '["b", "c", "e"]', 'Low potassium causes muscle cramps (b) and arrhythmias (e), and low magnesium causes tremors (c) and arrhythmias. ↓ DTRs (a) are a sign of high magnesium, and tall T waves (d) are a sign of high potassium.', true),
  ('priorities', 15, 'A post-op client using a morphine PCA had an RR of 8/min and was difficult to arouse. After the nurse gives naloxone, the client is alert with an RR of 14/min and reports pain of 6/10. Which action is MOST important for the nurse to take NEXT?', '[{"id": "a", "text": "Monitor closely; a repeat dose may be needed"}, {"id": "b", "text": "Resume the PCA at the same settings as before"}, {"id": "c", "text": "Recheck the client in 4 hours"}, {"id": "d", "text": "Give a full opioid dose now for the 6/10 pain"}]'::jsonb, '["a"]', 'Naloxone (Narcan) is the opioid antidote, but a repeat dose may be needed, so the client must be monitored closely. Resuming the PCA at the same settings or leaving the client for 4 hours ignores the risk of returning respiratory depression.', false),
  ('priorities', 16, 'A client 2 days after surgery reports incisional pain of 6/10. The nurse holds the scheduled opioid because the client''s RR is 11/min and the client is sleepy. Which intervention by the nurse is BEST at this time?', '[{"id": "a", "text": "Give the next opioid dose as scheduled for pain"}, {"id": "b", "text": "Ask the spouse to press the PCA button for him"}, {"id": "c", "text": "Positioning, music therapy, breathing techniques"}, {"id": "d", "text": "Give half of the scheduled opioid dose instead"}]'::jsonb, '["c"]', 'With an RR below 12 and sedation, opioids are unsafe, so nonpharmacologic interventions such as positioning, music therapy, and breathing techniques are best. Giving even half of the opioid dose adds to the respiratory depression.', false),
  ('priorities', 17, 'The nurse observes a newly hired nurse inserting a urinary catheter in a client. Which action by the newly hired nurse requires correction?', '[{"id": "a", "text": "Uses sterile technique for the insertion"}, {"id": "b", "text": "Keeps the sterile field within sight"}, {"id": "c", "text": "Touches sterile items with sterile gloves"}, {"id": "d", "text": "Keeps using a drape after saline wets it"}]'::jsonb, '["d"]', 'Anything out of sight or wet is contaminated, so a drape wet with saline must not be used. Catheter insertion is an invasive procedure that uses sterile technique, and sterile touches sterile only.', false),
  ('priorities', 18, 'The nurse reviews the pre-op history of a client scheduled for an elective hernia repair. Which findings increase this client''s surgical risk? Select all that apply.', '[{"id": "a", "text": "Walks 2 miles daily"}, {"id": "b", "text": "Advanced age (82 years)"}, {"id": "c", "text": "Diabetes and hypertension"}, {"id": "d", "text": "Smoking history"}, {"id": "e", "text": "Obesity"}]'::jsonb, '["b", "c", "d", "e"]', 'Surgical risk factors include advanced age (b), comorbidities such as diabetes and hypertension (c), smoking (d), and obesity (e). Walking daily (a) is not a listed risk factor.', true),
  ('priorities', 19, 'A client 3 hours after abdominal surgery has bright red drainage filling the drain, HR 122/min, BP 88/50 mm Hg, and new abdominal distension. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Stay with the patient; IV fluids; call provider"}, {"id": "b", "text": "Leave the room to find the provider"}, {"id": "c", "text": "Encourage incentive spirometry"}, {"id": "d", "text": "Notify provider; compression devices"}]'::jsonb, '["a"]', 'Tachycardia, low BP, and abdominal distension indicate hemorrhage; the nurse stays with the patient, gives IV fluids, and calls the provider. For bleeding, the nurse does not leave the patient, and compression devices are a DVT intervention.', false),
  ('priorities', 20, 'On post-op day 2, a client''s incision edges are red and slightly swollen, with no drainage. Vital signs are at baseline. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Infection requiring follow-up"}, {"id": "b", "text": "Normal inflammatory swelling, redness"}, {"id": "c", "text": "Proliferative granulation growth"}, {"id": "d", "text": "Active bleeding in the wound"}]'::jsonb, '["b"]', 'Swelling and redness during days 0–3 are expected in the inflammatory stage. The proliferative stage (3–21 days) is when tissue grows (granulation), and infection would show purulent drainage.', false),
  ('priorities', 21, 'A client''s laboratory results show high serum calcium and high serum magnesium levels. Which findings would the nurse expect when assessing this client? Select all that apply.', '[{"id": "a", "text": "Constipation"}, {"id": "b", "text": "Chvostek sign"}, {"id": "c", "text": "Lethargy"}, {"id": "d", "text": "↓ DTRs"}, {"id": "e", "text": "Low BP"}]'::jsonb, '["a", "c", "d", "e"]', 'High calcium causes constipation (a) and lethargy (c), and high magnesium causes ↓ DTRs (d) and low BP (e). Chvostek sign (b) is a sign of low calcium.', true),
  ('priorities', 22, 'A client who has had 2 days of vomiting has fluid loss and a sodium level within the normal range. The nurse reviews the IV fluid prescriptions for this client. Which prescription requires follow-up with the provider?', '[{"id": "a", "text": "NS (0.9%) at 125 mL/hr"}, {"id": "b", "text": "LR at 125 mL/hr"}, {"id": "c", "text": "3% NS at 125 mL/hr"}, {"id": "d", "text": "NS (0.9%) bolus of 500 mL"}]'::jsonb, '["c"]', '3% NS is a hypertonic fluid used for severe hyponatremia, which this client does not have. Isotonic NS (0.9%) and LR are used for fluid loss replacement.', false),
  ('priorities', 23, 'A client on telemetry has a serum potassium level reported as high. Which finding is the nurse MOST likely to note on assessment?', '[{"id": "a", "text": "Muscle cramps"}, {"id": "b", "text": "Chvostek sign"}, {"id": "c", "text": "Thirst"}, {"id": "d", "text": "Tall T waves"}]'::jsonb, '["d"]', 'High potassium causes tall T waves and weakness. Muscle cramps are a sign of low potassium, the opposite imbalance.', false),
  ('priorities', 24, 'Fifteen minutes after a unit of packed RBCs is started, the nurse reassesses the client. Which findings indicate a transfusion reaction that requires the nurse to stop the transfusion? Select all that apply.', '[{"id": "a", "text": "Back pain"}, {"id": "b", "text": "Hypotension"}, {"id": "c", "text": "Tremors"}, {"id": "d", "text": "Chills"}, {"id": "e", "text": "Tachycardia"}]'::jsonb, '["a", "b", "d", "e"]', 'Transfusion reaction signs include back pain (a), hypotension (b), chills (d), and tachycardia (e), along with fever. Tremors (c) are a sign of low magnesium, not a transfusion reaction.', true),
  ('priorities', 25, 'A client receiving IV fluids after surgery has a low serum sodium level. Which assessment findings is the nurse MOST likely to note?', '[{"id": "a", "text": "Confusion and headache"}, {"id": "b", "text": "Thirst"}, {"id": "c", "text": "Constipation and lethargy"}, {"id": "d", "text": "Tremors and arrhythmias"}]'::jsonb, '["a"]', 'Low sodium causes confusion and headache. Thirst is a sign of high sodium, and constipation with lethargy is a sign of high calcium.', false),
  ('priorities', 26, 'The surgical scheduling nurse must prioritize operating room time for four clients. Which client''s surgery should be performed FIRST?', '[{"id": "a", "text": "Client with an inguinal hernia awaiting repair"}, {"id": "b", "text": "Client with a ruptured aneurysm"}, {"id": "c", "text": "Client with appendicitis needing an appendectomy"}, {"id": "d", "text": "Client planning knee surgery next month"}]'::jsonb, '["b"]', 'A ruptured aneurysm requires emergency surgery, which is immediate. An appendectomy is urgent (within 24–48 hrs), and hernia repair and planned knee surgery are elective.', false),
  ('priorities', 27, 'A client with appendicitis is stable on IV fluids and asks the nurse, "Does this mean I have to have surgery right this minute?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Yes, this is emergency surgery done immediately.\""}, {"id": "b", "text": "\"No, this is elective surgery planned for later.\""}, {"id": "c", "text": "\"This surgery is urgent, within 24–48 hours.\""}, {"id": "d", "text": "\"Surgery is done only if antibiotics fail.\""}]'::jsonb, '["c"]', 'An appendectomy is urgent surgery, performed within 24–48 hours. Emergency surgery is immediate (for example, a ruptured aneurysm), and elective surgery is planned (for example, hernia repair).', false),
  ('priorities', 28, 'The nurse reviews assessment findings for five post-op clients. Which findings require IMMEDIATE intervention because they threaten airway, breathing, or circulation? Select all that apply.', '[{"id": "a", "text": "Stridor"}, {"id": "b", "text": "Fall risk"}, {"id": "c", "text": "Low SpO₂"}, {"id": "d", "text": "Hypotension and pallor"}, {"id": "e", "text": "Anxiety"}]'::jsonb, '["a", "c", "d"]', 'Stridor (a) is an airway problem, low SpO₂ (c) is a breathing problem, and hypotension with pallor (d) is a circulation problem. Fall risk (b) and anxiety (e) fall under ''everything else'' and come after the ABCs.', true),
  ('priorities', 29, 'The nurse is caring for four clients who are 2 to 3 days post-op. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Client with leg pain, swelling, and warmth"}, {"id": "b", "text": "Client with ↓ breath sounds who is using spirometry"}, {"id": "c", "text": "Client with constipation from opioid use"}, {"id": "d", "text": "Client with sudden SOB, chest pain, tachycardia"}]'::jsonb, '["d"]', 'Sudden SOB, chest pain, and tachycardia indicate PE, an EMERGENCY requiring O₂ and a call to the provider. Leg pain, swelling, and warmth indicate DVT, which is serious but not immediately life-threatening like PE.', false),
  ('priorities', 30, 'A client on post-op day 1 has stayed in bed since surgery. The nurse hears ↓ breath sounds in both bases, and the SpO₂ is 92%. The client denies chest pain, and the HR is 84/min. Which action by the nurse is BEST?', '[{"id": "a", "text": "O₂ and call provider as an emergency"}, {"id": "b", "text": "Incentive spirometry and ambulate"}, {"id": "c", "text": "Stay with patient and give IV fluids"}, {"id": "d", "text": "Notify provider; compression devices"}]'::jsonb, '["b"]', '↓ breath sounds with hypoxia in a client who has not ambulated indicate atelectasis, treated with incentive spirometry and ambulation. O₂ with an emergency call is the first action for PE, which presents with sudden SOB, chest pain, and tachycardia.', false),
  ('priorities', 31, 'On post-op day 6, the nurse assesses a client''s abdominal incision and drain. Which findings require follow-up? Select all that apply.', '[{"id": "a", "text": "Granulation tissue"}, {"id": "b", "text": "Increasing redness and swelling"}, {"id": "c", "text": "Yellow/green pus"}, {"id": "d", "text": "Pink, watery drainage"}, {"id": "e", "text": "New bloody drainage"}]'::jsonb, '["b", "c", "e"]', 'Redness and swelling are expected only in the inflammatory stage (0–3 days), so increasing redness and swelling on day 6 (b) and yellow/green pus (c) suggest infection, and new bloody drainage (e) indicates active bleeding. Granulation tissue (a) is expected in the proliferative stage (3–21 days), and pink, watery drainage (d) is normal early healing.', true),
  ('priorities', 32, 'A UAP reports that a post-op client''s SpO₂ on the monitor has dropped from 96% to 90% over the past hour. Which action should the RN take FIRST?', '[{"id": "a", "text": "Go to assess the client"}, {"id": "b", "text": "Call the provider with the reading"}, {"id": "c", "text": "Ask the UAP to recheck in 30 minutes"}, {"id": "d", "text": "Document the reading in the chart"}]'::jsonb, '["a"]', 'Assess first, then call the provider; assessment and reassessment cannot be delegated to the UAP. Calling the provider before assessing skips the first step.', false),
  ('priorities', 33, 'The nurse is preparing to give the first unit of packed RBCs to a client with anemia. Which finding requires follow-up BEFORE the nurse starts the transfusion?', '[{"id": "a", "text": "Baseline vital signs are documented"}, {"id": "b", "text": "Filtered Y-tubing is primed with NS"}, {"id": "c", "text": "Only a type & screen is on record"}, {"id": "d", "text": "The blood was received 20 minutes ago"}]'::jsonb, '["c"]', 'A type & screen determines ABO/Rh, but a type & cross must be performed before the actual transfusion. Baseline vitals, filtered Y-tubing with normal saline, and blood received 20 minutes ago meet transfusion standards.', false),
  ('priorities', 34, 'Ten minutes into a blood transfusion, a client develops chills, back pain, and a drop in BP. Which actions should the nurse take? Select all that apply.', '[{"id": "a", "text": "Slow the rate and continue the unit"}, {"id": "b", "text": "Stop the transfusion immediately"}, {"id": "c", "text": "Start NS through new tubing"}, {"id": "d", "text": "Flush the blood tubing with NS"}, {"id": "e", "text": "Notify HCP and blood bank"}]'::jsonb, '["b", "c", "e"]', 'For a transfusion reaction, the nurse stops the transfusion immediately (b), starts NS through new tubing (c), and notifies the HCP and blood bank (e). Slowing the rate (a) continues the reaction, and flushing the existing blood tubing (d) violates the new-tubing step.', true),
  ('priorities', 35, 'The charge nurse observes a nurse giving a unit of packed RBCs to a post-op client. Which action by the nurse requires correction?', '[{"id": "a", "text": "Stays with the patient for the first 15 minutes"}, {"id": "b", "text": "Takes baseline and post-vitals"}, {"id": "c", "text": "Uses filtered Y-tubing with normal saline"}, {"id": "d", "text": "Hangs blood received 4.5 hours ago"}]'::jsonb, '["d"]', 'Blood must be infused within 4 hours of receiving it, so blood received 4.5 hours ago cannot be started. Staying for the first 15 minutes, taking baseline and post-vitals, and using filtered Y-tubing with normal saline are correct.', false),
  ('priorities', 36, 'A client arrives on the surgical unit after a 4-hour procedure. The client is shivering, and the temperature is below the client''s normal baseline. The incision is clean and dry. Which nursing action is MOST important for preventing a surgical site infection?', '[{"id": "a", "text": "Hold the antibiotics until the client is warm"}, {"id": "b", "text": "Maintain normothermia"}, {"id": "c", "text": "Repeat the chlorhexidine wash now"}, {"id": "d", "text": "Recheck the temperature in 4 hours"}]'::jsonb, '["b"]', 'Maintaining normothermia is an SSI prevention measure, so warming the client is most important. Antibiotics are given pre-op for SSI prevention and are not held, and waiting 4 hours delays the needed action.', false),
  ('priorities', 37, 'The RN and a UAP are caring for a stable client who will go home with a PCA pump. Which task should the RN perform rather than delegate to the UAP?', '[{"id": "a", "text": "Feeding the client lunch"}, {"id": "b", "text": "Collecting a routine urine specimen"}, {"id": "c", "text": "Patient teaching about the PCA pump"}, {"id": "d", "text": "Repositioning the client in bed"}]'::jsonb, '["c"]', 'Patient teaching/education is RN-only and cannot be delegated. Feeding (ADLs), routine specimen collection, and repositioning stable patients can be delegated to the UAP.', false),
  ('priorities', 38, 'Four hours after abdominal surgery, the nurse is assessing a client for hemorrhage. Which findings suggest hemorrhage? Select all that apply.', '[{"id": "a", "text": "Tachycardia"}, {"id": "b", "text": "↓ breath sounds"}, {"id": "c", "text": "Low BP"}, {"id": "d", "text": "Leg warmth and swelling"}, {"id": "e", "text": "Abdominal distension"}]'::jsonb, '["a", "c", "e"]', 'Hemorrhage presents with tachycardia (a), low BP (c), and abdominal distension (e). ↓ breath sounds (b) suggest atelectasis, and leg warmth and swelling (d) suggest DVT.', true),
  ('priorities', 39, 'A client on post-op day 3 has a serum sodium level that is reported as high. The client is alert and oriented, and vital signs are at baseline. Which finding would the nurse MOST likely expect?', '[{"id": "a", "text": "Thirst"}, {"id": "b", "text": "Confusion and headache"}, {"id": "c", "text": "Chvostek sign"}, {"id": "d", "text": "Tall T waves"}]'::jsonb, '["a"]', 'High sodium causes thirst (and seizures). Confusion and headache are signs of low sodium, the opposite imbalance.', false),
  ('priorities', 40, 'The nurse reviews the respiratory rates of four post-op clients. Which client''s finding requires IMMEDIATE follow-up?', '[{"id": "a", "text": "RR 20/min while asleep"}, {"id": "b", "text": "RR 13/min with SpO₂ at baseline"}, {"id": "c", "text": "RR 19/min after ambulating"}, {"id": "d", "text": "RR 11/min on a morphine PCA"}]'::jsonb, '["d"]', 'Clients on opioids are monitored for respiratory depression (RR <12/min), so an RR of 11/min requires immediate follow-up. RRs of 13, 19, and 20/min are within the range that the breathing priority flags (RR <12 or >20).', false),
  ('priorities', 41, 'A client who had a bowel resection is transferred from the PACU to the surgical unit, where an RN and a UAP will provide care. Which tasks must the RN perform rather than delegate? Select all that apply.', '[{"id": "a", "text": "I&O measurement"}, {"id": "b", "text": "Assessment on arrival"}, {"id": "c", "text": "Planning the care"}, {"id": "d", "text": "Medication administration"}, {"id": "e", "text": "Patient teaching"}]'::jsonb, '["b", "c", "d", "e"]', 'Assessment (b), planning (care plan creation) (c), medication administration (d), and patient teaching (e) are RN-only. I&O measurement (a) can be delegated to the UAP.', true),
  ('priorities', 42, 'A 45-year-old client who does not smoke and has no chronic illness is scheduled for surgery. The client reports a 9-kg unplanned weight loss and eating very little over the past 3 months. Which surgical risk factor should the nurse report to the health care provider?', '[{"id": "a", "text": "Advanced age"}, {"id": "b", "text": "Malnutrition"}, {"id": "c", "text": "Obesity"}, {"id": "d", "text": "Comorbidities"}]'::jsonb, '["b"]', 'Unplanned weight loss with poor intake indicates malnutrition, a surgical risk factor along with obesity and smoking. The client is 45 years old with no chronic illness, so advanced age and comorbidities do not apply.', false),
  ('priorities', 43, 'The nurse is alone in the room with a post-op client whose SpO₂ suddenly drops to 86%. The client is restless and short of breath. Which action is BEST?', '[{"id": "a", "text": "Leave the room to get an O₂ tank"}, {"id": "b", "text": "Leave to call the provider at the desk"}, {"id": "c", "text": "Stay with patient and prepare interventions"}, {"id": "d", "text": "Recheck the SpO₂ in 15 minutes"}]'::jsonb, '["c"]', 'For hypoxia or bleeding, the nurse stays with the patient and prepares interventions. Leaving the room to get equipment or call the provider leaves a hypoxic client alone.', false),
  ('priorities', 44, 'On post-op day 2 a client suddenly becomes short of breath, reports chest pain, and has a heart rate of 126/min. Which actions should the nurse take FIRST? Select all that apply.', '[{"id": "a", "text": "Incentive spirometry"}, {"id": "b", "text": "O₂"}, {"id": "c", "text": "Compression devices"}, {"id": "d", "text": "Call the provider"}, {"id": "e", "text": "Ambulate the client"}]'::jsonb, '["b", "d"]', 'Sudden SOB, chest pain, and tachycardia indicate PE, an EMERGENCY: give O₂ (b) and call the provider (d). Incentive spirometry (a) and ambulation (e) are for atelectasis, and compression devices (c) are a DVT action.', true),
  ('priorities', 45, 'The nurse teaches a client about surgical site infection (SSI) prevention the day before an elective hernia repair. Which statement by the client indicates understanding of the teaching?', '[{"id": "a", "text": "\"I will do a chlorhexidine wash before surgery.\""}, {"id": "b", "text": "\"I will take antibiotics only after surgery.\""}, {"id": "c", "text": "\"My blood sugar does not affect my incision.\""}, {"id": "d", "text": "\"Keeping my body cool will prevent infection.\""}]'::jsonb, '["a"]', 'A chlorhexidine wash is an SSI prevention measure. Antibiotics are given pre-op, and blood sugar control and normothermia also prevent SSI.', false),
  ('priorities', 46, 'A client is being discharged with an oral opioid after surgery. Which statement by the client indicates understanding of the expected side effects?', '[{"id": "a", "text": "\"Opioids rarely cause constipation.\""}, {"id": "b", "text": "\"Sedation means I need a higher opioid dose.\""}, {"id": "c", "text": "\"Nausea means I am allergic to opioids.\""}, {"id": "d", "text": "\"I may have constipation, sedation, nausea.\""}]'::jsonb, '["d"]', 'Side effects of opioids include constipation, sedation, and nausea. Sedation signals a need for monitoring, not a higher dose.', false),
  ('priorities', 47, 'On post-op day 2 after a hip repair, a client reports pain in the left calf. The nurse notes the left leg is swollen and warm; breath sounds are clear and SpO₂ is at baseline. Which interpretation and action are MOST appropriate?', '[{"id": "a", "text": "PE; give O₂ as an emergency"}, {"id": "b", "text": "DVT; notify provider"}, {"id": "c", "text": "Atelectasis; incentive spirometry"}, {"id": "d", "text": "Hemorrhage; give IV fluids"}]'::jsonb, '["b"]', 'Leg pain, swelling, and warmth indicate DVT, and the first action is to notify the provider. PE would present with sudden SOB, chest pain, and tachycardia.', false),
  ('priorities', 48, 'The nurse is planning care for a client with diabetes who is scheduled for a colon resection. Which interventions reduce the client''s risk of a surgical site infection (SSI)? Select all that apply.', '[{"id": "a", "text": "Antibiotics pre-op"}, {"id": "b", "text": "Chlorhexidine wash"}, {"id": "c", "text": "Cooling the client post-op"}, {"id": "d", "text": "Blood sugar control"}, {"id": "e", "text": "Maintain normothermia"}]'::jsonb, '["a", "b", "d", "e"]', 'SSI prevention includes antibiotics pre-op (a), chlorhexidine wash (b), blood sugar control (d), and maintaining normothermia (e). Cooling the client (c) contradicts maintaining normothermia.', true),
  ('priorities', 49, 'A client who has had diarrhea for 3 days has a low serum potassium level and reports muscle cramps in both legs. Which additional finding would the nurse MOST likely expect?', '[{"id": "a", "text": "Tall T waves"}, {"id": "b", "text": "Thirst"}, {"id": "c", "text": "Arrhythmias"}, {"id": "d", "text": "↓ DTRs"}]'::jsonb, '["c"]', 'Low potassium causes muscle cramps and arrhythmias. Tall T waves are a sign of high potassium, and ↓ DTRs are a sign of high magnesium.', false),
  ('priorities', 50, 'The nurse and a UAP are caring for a post-op client who needs several tasks completed this morning. Which task is MOST important for the nurse to perform using sterile technique?', '[{"id": "a", "text": "Insertion of a urinary catheter"}, {"id": "b", "text": "Routine urine specimen collection"}, {"id": "c", "text": "Measuring urine I&O"}, {"id": "d", "text": "Repositioning the stable client"}]'::jsonb, '["a"]', 'Sterile technique is used in invasive procedures such as dressing changes and catheter insertions. Routine specimen collection, I&O measurement, and repositioning stable patients are basic tasks that can be delegated to the UAP and do not require sterile technique.', false),
  ('postop_emerg', 1, 'A client is in the PACU 20 minutes after an abdominal procedure under general anesthesia. The client is drowsy, and the nurse hears stridor, observes choking movements and cyanosis of the lips, and notes an SpO₂ of 85%. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Reposition the head and provide airway support"}, {"id": "b", "text": "Coach the client to use the incentive spirometer"}, {"id": "c", "text": "Increase the IV fluid rate to support circulation"}, {"id": "d", "text": "Check the pupil response and level of consciousness"}]'::jsonb, '["a"]', 'Stridor, choking, low O₂ and cyanosis point to airway obstruction (such as the tongue falling back after anesthesia), which is managed by repositioning the head, suctioning and airway support. The incentive spirometer treats hypoxia from shallow breathing or atelectasis, not an obstructed airway, and circulation and neuro checks come after the Airway.', false),
  ('postop_emerg', 2, 'The nurse on a surgical unit receives report on four clients who each had surgery earlier today. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Post-op patient with BP 152/90 who reports incisional pain and a headache"}, {"id": "b", "text": "Post-op patient with confusion, restlessness, and low SpO₂"}, {"id": "c", "text": "Post-op patient with HR 56 bpm who is alert and denies dizziness or fatigue"}, {"id": "d", "text": "Post-op patient with mild abdominal distension who reports nausea"}]'::jsonb, '["b"]', 'Low SpO₂ with confusion and restlessness after narcotics signals hypoxia, a Breathing problem, and Airway & Breathing are the first post-op priority. The client with pain-related hypertension needs pain control but is not a breathing threat, and an asymptomatic HR of 56 bpm is monitored.', false),
  ('postop_emerg', 3, 'A client 10 hours after an open cholecystectomy has received narcotics for pain and has been breathing shallowly while staying in bed. The client is now restless and newly confused, and the SpO₂ is 89%. Which interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Ambulation"}, {"id": "b", "text": "Atropine IV"}, {"id": "c", "text": "Incentive spirometer"}, {"id": "d", "text": "O₂ therapy"}, {"id": "e", "text": "Straight catheter"}]'::jsonb, '["a", "c", "d"]', 'Restlessness, confusion and a low SpO₂ after narcotics and shallow breathing indicate hypoxia. O₂ therapy is correct because it is the listed hypoxia treatment; the incentive spirometer is correct because it re-expands the lungs of a client breathing shallowly; ambulation is correct because it is also listed for hypoxia. Atropine is wrong because it is given only for symptomatic bradycardia, and a straight catheter is wrong because it treats urinary retention, not hypoxia.', true),
  ('postop_emerg', 4, 'Three hours after surgery, a client''s BP has fallen from 128/76 to 88/50 and the HR has risen from 84 to 124 bpm. The client is pale, reports dizziness, and the nurse sees bright red blood soaking through the surgical dressing. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Hang the blood transfusion typed before surgery"}, {"id": "b", "text": "Prepare the client for a return to surgery"}, {"id": "c", "text": "Apply pressure to the bleeding surgical site"}, {"id": "d", "text": "Encourage oral fluids to correct dehydration"}]'::jsonb, '["c"]', 'Low BP, tachycardia, pale skin and dizziness with active bleeding indicate post-op hemorrhage, and applying pressure to the site is the first listed intervention. A blood transfusion and surgery may follow, but they do not stop the bleeding that is happening now.', false),
  ('postop_emerg', 5, 'On postoperative day 1, a client who has taken very little by mouth reports dizziness when sitting up. BP is 90/56, peripheral pulses are weak, and the skin is cold. The dressing and drain show minimal drainage. Which intervention is MOST appropriate for the nurse to anticipate?', '[{"id": "a", "text": "Antihypertensives if needed after pain control"}, {"id": "b", "text": "Atropine if the low blood pressure persists"}, {"id": "c", "text": "A pressure dressing over the surgical incision"}, {"id": "d", "text": "IV fluids, with blood transfusion if needed"}]'::jsonb, '["d"]', 'Dizziness, weak pulses and cold skin with poor intake indicate hypotension from dehydration, which is treated with IV fluids and a blood transfusion if needed. Atropine is for symptomatic bradycardia, and a pressure dressing is for a bleeding surgical site, which this dry dressing does not show.', false),
  ('postop_emerg', 6, 'Two hours after an open abdominal procedure, a client with no history of hypertension has a BP of 168/96. The client is grimacing and sweating, reports a headache, and rates incisional pain 9/10. Lung sounds are clear and intake and output are balanced. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Pain control, then recheck the BP"}, {"id": "b", "text": "Antihypertensives, then recheck the BP"}, {"id": "c", "text": "Fluid restriction for fluid overload"}, {"id": "d", "text": "Oxygen and anticoagulants for a PE"}]'::jsonb, '["a"]', 'Headache and sweating with severe pain indicate post-op hypertension caused by pain, so pain control comes first; antihypertensives are given only if needed. Clear lungs and balanced I&O make fluid overload unlikely.', false),
  ('postop_emerg', 7, 'On postoperative day 1, a client has a heart rate of 116 bpm and reports palpitations. The nurse reviews the client''s data to identify the cause so it can be treated. Which conditions should the nurse consider as possible causes of this heart rate? Select all that apply.', '[{"id": "a", "text": "Laryngospasm after extubation"}, {"id": "b", "text": "Recent removal of the urinary catheter"}, {"id": "c", "text": "Hypovolemia from blood loss"}, {"id": "d", "text": "Pain at the surgical incision"}, {"id": "e", "text": "Vagal stimulation during suctioning"}]'::jsonb, '["c", "d"]', 'An HR above 100 bpm with palpitations is tachycardia. Hypovolemia is correct because it is a listed cause (treated with fluids), and pain is correct because it is a listed cause (treated with pain relief). Vagal stimulation is wrong because it causes bradycardia; laryngospasm is wrong because it causes airway obstruction; catheter removal is wrong because it is a cause of urinary retention.', true),
  ('postop_emerg', 8, 'A client in the PACU after general anesthesia has a heart rate of 54 bpm. The client is awake and oriented, denies dizziness or fatigue, and has a BP of 118/72 and an SpO₂ of 97%. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Administer atropine as prescribed for bradycardia"}, {"id": "b", "text": "Continue to monitor the heart rate and symptoms"}, {"id": "c", "text": "Start IV fluids for suspected hypovolemia"}, {"id": "d", "text": "Notify the provider of a possible hemorrhage"}]'::jsonb, '["b"]', 'An HR below 60 bpm after anesthesia is bradycardia, but this client has no dizziness or fatigue, so the nurse monitors. Atropine is given only if the bradycardia is symptomatic.', false),
  ('postop_emerg', 9, 'Shortly after an NG tube is inserted and suctioned, a postoperative client''s heart rate drops from 72 to 46 bpm. The client reports feeling dizzy and very tired, and the BP is 98/60. Which medication is the nurse MOST likely to prepare?', '[{"id": "a", "text": "Dantrolene sodium for muscle rigidity"}, {"id": "b", "text": "Anticoagulants for a suspected clot"}, {"id": "c", "text": "Atropine for symptomatic bradycardia"}, {"id": "d", "text": "Antihypertensives for the headache"}]'::jsonb, '["c"]', 'Vagal stimulation can cause bradycardia (HR <60 bpm) with dizziness and fatigue, and atropine is given when it is symptomatic. Dantrolene treats malignant hyperthermia, and anticoagulants treat DVT or PE.', false),
  ('postop_emerg', 10, 'On postoperative day 3, a client who has stayed mostly in bed reports pain in the right calf. The right leg is swollen and red, and the left leg is unchanged. Which interventions should the nurse anticipate for this complication? Select all that apply.', '[{"id": "a", "text": "Strict bed rest until swelling resolves"}, {"id": "b", "text": "Compression devices as prescribed"}, {"id": "c", "text": "Anticoagulants as prescribed"}, {"id": "d", "text": "IV antibiotics for the leg redness"}, {"id": "e", "text": "Ambulation as prescribed"}]'::jsonb, '["b", "c", "e"]', 'Unilateral leg swelling, pain and redness after immobility indicate DVT. Anticoagulants are correct because they are a listed DVT intervention; compression devices are correct for the same reason; ambulation is correct because it is listed for DVT and immobility is a cause. IV antibiotics are wrong because they treat pneumonia or anastomotic leak, not a clot, and strict bed rest is wrong because immobility is a cause of DVT and ambulation is part of treatment.', true),
  ('postop_emerg', 11, 'A client on postoperative day 4 who has had left calf swelling suddenly sits up gasping and reports sharp chest pain. The HR is 124 bpm and the SpO₂ is 86%. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Coach the client to use the incentive spirometer"}, {"id": "b", "text": "Assist the client to ambulate to ease breathing"}, {"id": "c", "text": "Apply compression devices to both legs"}, {"id": "d", "text": "Give oxygen and call for help"}]'::jsonb, '["d"]', 'Sudden dyspnea, chest pain, tachycardia and low SpO₂ after a DVT indicate pulmonary embolism, an emergency treated with oxygen and anticoagulants while calling for help. The incentive spirometer and ambulation treat atelectasis, and compression devices are for DVT prevention, not a clot that has reached the lungs.', false),
  ('postop_emerg', 12, 'On postoperative day 3, a client who aspirated during anesthesia induction has a fever, crackles in the right lung base, and a cough producing purulent sputum. Which set of prescriptions is the nurse MOST likely to receive?', '[{"id": "a", "text": "Antibiotics, oxygen, and deep breathing"}, {"id": "b", "text": "Oxygen and anticoagulants as an emergency"}, {"id": "c", "text": "NPO status, IV fluids, and an NG tube"}, {"id": "d", "text": "Dantrolene IV and active cooling measures"}]'::jsonb, '["a"]', 'Aspiration followed by fever, crackles, cough and purulent sputum indicates pneumonia, which is treated with antibiotics, oxygen and deep breathing. Dantrolene and cooling treat malignant hyperthermia, whose fever comes with muscle rigidity during or after surgery, not purulent sputum.', false),
  ('postop_emerg', 13, 'A client on postoperative day 1 after abdominal surgery has been splinting with shallow breaths and has not been out of bed. The client has a low-grade fever, crackles in both bases, mild dyspnea, and an SpO₂ of 91%, with no cough or sputum. Which intervention is MOST appropriate?', '[{"id": "a", "text": "Antibiotics, oxygen, and deep breathing"}, {"id": "b", "text": "Incentive spirometer and ambulation"}, {"id": "c", "text": "Oxygen and anticoagulants"}, {"id": "d", "text": "NPO status and an NG tube"}]'::jsonb, '["b"]', 'Shallow breathing and immobility with low O₂, crackles, fever and dyspnea indicate atelectasis, treated with the incentive spirometer, deep breathing and ambulation. Antibiotics are for pneumonia, which would also show a cough with purulent sputum.', false),
  ('postop_emerg', 14, 'A client who had abdominal surgery yesterday has been breathing shallowly and refusing to get out of bed. The nurse assesses for the respiratory complication MOST likely to develop from this pattern. Which findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Crackles"}, {"id": "b", "text": "Cough with purulent sputum"}, {"id": "c", "text": "Low O₂ saturation"}, {"id": "d", "text": "Dyspnea"}, {"id": "e", "text": "Fever"}]'::jsonb, '["a", "c", "d", "e"]', 'Shallow breathing and immobility cause atelectasis (collapsed alveoli). Low O₂ is correct, crackles are correct, fever is correct and dyspnea is correct because all four are listed symptoms of atelectasis. Cough with purulent sputum is wrong because it is a symptom of pneumonia from mucus buildup or aspiration.', true),
  ('postop_emerg', 15, 'An obese client on postoperative day 5 after an abdominal procedure has a wound infection. While coughing, the client says, ''I felt something pop,'' and the nurse sees the incision edges separated with no abdominal contents visible. Which action is MOST appropriate?', '[{"id": "a", "text": "Apply firm pressure to push the wound edges together"}, {"id": "b", "text": "Encourage coughing and deep breathing every hour"}, {"id": "c", "text": "Cover with sterile dressing; notify provider"}, {"id": "d", "text": "Keep the client NPO and insert an NG tube"}]'::jsonb, '["c"]', 'A sudden popping sensation with a visible wound opening in an obese client with infection indicates wound dehiscence: cover with a sterile dressing, notify the provider and avoid strain. Hourly coughing adds strain, and applying pressure is the action for a bleeding site.', false),
  ('postop_emerg', 16, 'On postoperative day 6 after a laparotomy, a client vomits forcefully and then cries out in severe pain. The nurse lifts the gown and sees loops of intestine protruding through the incision. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Cover the incision with a dry sterile dressing"}, {"id": "b", "text": "Apply firm pressure over the open wound"}, {"id": "c", "text": "Keep the client NPO and insert an NG tube"}, {"id": "d", "text": "Cover the intestines with moist sterile gauze"}]'::jsonb, '["d"]', 'Visible intestines with severe pain indicate evisceration, an emergency: cover with moist sterile gauze, then call the surgeon for emergency surgery. A plain sterile dressing is the dehiscence action and does not keep exposed organs moist.', false),
  ('postop_emerg', 17, 'The nurse is called to the bedside of a client on postoperative day 5 whose abdominal incision has opened. Which findings indicate wound evisceration rather than wound dehiscence? Select all that apply.', '[{"id": "a", "text": "Intestines visible in the wound"}, {"id": "b", "text": "Visible wound opening"}, {"id": "c", "text": "Severe pain"}, {"id": "d", "text": "History of obesity"}, {"id": "e", "text": "Sudden ''popping'' sensation"}]'::jsonb, '["a", "c"]', 'Intestines visible is correct because it is the defining sign of evisceration; severe pain is correct because it is listed for evisceration. A sudden popping sensation and a visible wound opening are wrong because they are the listed signs of dehiscence, and obesity is wrong because it is a cause of dehiscence, not a sign that organs have protruded.', true),
  ('postop_emerg', 18, 'On postoperative day 2 after a bowel resection, a client receiving opioids has no bowel sounds, a distended abdomen, and nausea with two episodes of vomiting. Vital signs are stable and there is no fever or rigidity. Which interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "NG tube"}, {"id": "b", "text": "Ambulation"}, {"id": "c", "text": "Advance the diet"}, {"id": "d", "text": "Keep NPO"}, {"id": "e", "text": "IV fluids"}]'::jsonb, '["a", "b", "d", "e"]', 'No bowel sounds, distension and N/V after opioids and bowel manipulation indicate paralytic ileus. NPO is correct, IV fluids are correct, an NG tube is correct and ambulation is correct because all four are the listed ileus interventions. Advancing the diet is wrong because the client must be NPO.', true),
  ('postop_emerg', 19, 'On postoperative day 5 after a bowel resection, a client reports abdominal pain that has worsened each day. The client has a fever and an HR of 118 bpm, the abdomen is rigid, and the wound drainage has become feculent. Which complication is the nurse MOST concerned about?', '[{"id": "a", "text": "Anastomotic leak"}, {"id": "b", "text": "Paralytic ileus"}, {"id": "c", "text": "Wound dehiscence"}, {"id": "d", "text": "Pulmonary embolism"}]'::jsonb, '["a"]', 'Fever, worsening abdominal pain on days 3–7, tachycardia, a rigid abdomen (peritonitis) and feculent drainage after bowel surgery indicate an anastomotic leak. Paralytic ileus causes absent bowel sounds and distension without peritonitis or feculent drainage.', false),
  ('postop_emerg', 20, 'A client on postoperative day 4 after colon surgery was advanced to clear liquids this morning. The client now has a fever, a rigid abdomen, worsening abdominal pain, and purulent drainage from the incision. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Continue clear liquids and reassess in 4 hours"}, {"id": "b", "text": "Keep NPO and notify the surgeon"}, {"id": "c", "text": "Encourage ambulation to relieve the pain"}, {"id": "d", "text": "Apply a sterile dressing and avoid strain"}]'::jsonb, '["b"]', 'These day 3–7 findings after bowel surgery indicate an anastomotic leak, which requires NPO, an NG tube, IV antibiotics and notifying the surgeon because a return to the OR may be needed. A sterile dressing and avoiding strain is the dehiscence plan and does not address peritonitis.', false),
  ('postop_emerg', 21, 'A client on postoperative day 1 after abdominal surgery refuses to walk, saying, ''I''ll just stay in bed until the pain is gone.'' The client is taking shallow breaths and has hypoactive bowel sounds. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "Walking is needed mainly to prevent urinary retention."}, {"id": "b", "text": "Bed rest is safest until the risk of dehiscence has passed."}, {"id": "c", "text": "Walking helps prevent atelectasis, DVT, and paralytic ileus."}, {"id": "d", "text": "Walking should wait until your bowel sounds return to normal."}]'::jsonb, '["c"]', 'Ambulation is a listed intervention for atelectasis, DVT and paralytic ileus, all of which immobility promotes. Waiting for bowel sounds is wrong because ambulation is part of the treatment even when an ileus is present.', false),
  ('postop_emerg', 22, 'Six hours after the urinary catheter was removed following surgery, a client receiving opioids has not voided. The nurse palpates a distended bladder, and the client reports an urge to void but cannot. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Insert a straight catheter"}, {"id": "b", "text": "Notify the provider of possible kidney injury"}, {"id": "c", "text": "Increase the IV fluid rate to improve output"}, {"id": "d", "text": "Perform a bladder scan"}]'::jsonb, '["d"]', 'No urine output with bladder distension after catheter removal and opioids indicates urinary retention; the nurse first performs a bladder scan and inserts a straight catheter only if needed. Increasing IV fluids would add volume to a bladder that cannot empty.', false),
  ('postop_emerg', 23, 'A client who is 12 hours post-op has had a urine output of 25 mL/hr for the past 2 hours. The bladder is not distended, and the BP and HR are unchanged from baseline. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Assess for dehydration or kidney injury"}, {"id": "b", "text": "Notify the provider of the low output"}, {"id": "c", "text": "Insert a straight catheter for a urine sample"}, {"id": "d", "text": "Continue routine monitoring of the output"}]'::jsonb, '["a"]', 'Output below the 30 mL/hr minimum calls for assessment for dehydration or kidney injury first and then notifying the provider. Routine monitoring is wrong because 25 mL/hr is below the normal minimum.', false),
  ('postop_emerg', 24, 'The nurse reviews the urine output totals for four clients who are each 1 day post-op and have no other new findings. Which client''s urine output requires follow-up?', '[{"id": "a", "text": "450 mL over the past 12 hours"}, {"id": "b", "text": "100 mL over the past 4 hours"}, {"id": "c", "text": "180 mL over the past 6 hours"}, {"id": "d", "text": "210 mL over the past 7 hours"}]'::jsonb, '["b"]', '100 mL over 4 hours is 25 mL/hr, below the minimum of 30 mL/hr. The other clients average 37.5, 30 and 30 mL/hr, which meet the minimum.', false),
  ('postop_emerg', 25, 'During a laparoscopic procedure under sevoflurane, after succinylcholine was given for intubation, the client''s temperature rises rapidly, the jaw becomes rigid, the HR climbs to 142 bpm, and the urine turns dark. Which intervention should the nurse anticipate FIRST?', '[{"id": "a", "text": "Administer dantrolene sodium IV"}, {"id": "b", "text": "Provide 100% O₂"}, {"id": "c", "text": "Stop the triggering agent"}, {"id": "d", "text": "Begin active cooling measures"}]'::jsonb, '["c"]', 'Rapidly rising temperature, jaw rigidity, tachycardia and dark urine after a volatile anesthetic and succinylcholine indicate malignant hyperthermia; the triggering agent is stopped immediately, then dantrolene, 100% O₂ and active cooling follow. Dantrolene is the antidote but comes after removing the trigger.', false),
  ('postop_emerg', 26, 'In the PACU, a client who received succinylcholine develops severe jaw rigidity, a rapidly rising temperature, tachycardia, and dark urine. The triggering agent has already been stopped. Which medication should the nurse prepare to administer NEXT?', '[{"id": "a", "text": "Atropine IV"}, {"id": "b", "text": "IV anticoagulants"}, {"id": "c", "text": "IV antihypertensive agents"}, {"id": "d", "text": "Dantrolene sodium IV"}]'::jsonb, '["d"]', 'These findings indicate malignant hyperthermia, and dantrolene sodium IV is the only antidote, given right after the trigger is stopped. Atropine is for symptomatic bradycardia, but this client is tachycardic.', false),
  ('postop_emerg', 27, 'A client is transferred to the PACU after general anesthesia. The nurse suspects malignant hyperthermia. Which findings support the nurse''s suspicion? Select all that apply.', '[{"id": "a", "text": "Heart rate of 52 bpm"}, {"id": "b", "text": "Severe muscle rigidity of the jaw"}, {"id": "c", "text": "Dark urine (myoglobinuria)"}, {"id": "d", "text": "Metabolic alkalosis"}, {"id": "e", "text": "Rapidly rising temperature"}]'::jsonb, '["b", "c", "e"]', 'Rapidly rising temperature is correct, severe jaw rigidity is correct and dark urine (myoglobinuria) is correct because each is a listed sign of malignant hyperthermia. Metabolic alkalosis is wrong because the reaction causes metabolic acidosis, and an HR of 52 bpm is wrong because malignant hyperthermia causes tachycardia; a slow rate after anesthesia points to bradycardia instead.', true),
  ('postop_emerg', 28, 'In the operating room, a client develops a rapidly rising temperature, jaw rigidity, tachycardia, and metabolic acidosis. The nurse is working with the anesthesia team. Which sequence of interventions is BEST?', '[{"id": "a", "text": "Stop agent → dantrolene IV → 100% O₂ → active cooling"}, {"id": "b", "text": "Dantrolene IV → stop the agent → active cooling → 100% O₂"}, {"id": "c", "text": "Active cooling → stop agent → 100% O₂ → dantrolene IV"}, {"id": "d", "text": "100% O₂ → active cooling → dantrolene IV → stop agent"}]'::jsonb, '["a"]', 'For malignant hyperthermia the triggering agent is stopped immediately, then dantrolene sodium IV is given, then 100% O₂ and active cooling, and the anesthesia team is notified stat. Giving dantrolene before stopping the agent leaves the trigger running.', false),
  ('postop_emerg', 29, 'A nurse orienting to a surgical unit is caring for clients at different points after surgery. Which statement by the orienting nurse indicates understanding of postoperative risk?', '[{"id": "a", "text": "Monitoring is most intense in the early period, 24–48 hours after surgery."}, {"id": "b", "text": "Life-threatening complications are most likely in the first 24 hours."}, {"id": "c", "text": "Life-threatening complications peak in the late period, days to weeks later."}, {"id": "d", "text": "Once a client leaves PACU after 1–2 hours, the life-threatening risk has passed."}]'::jsonb, '["b"]', 'The first 24 hours post-op carry the highest risk for life-threatening complications. The highest monitoring intensity is in the immediate PACU period (first 1–2 hours), not the early 24–48 hour period.', false),
  ('postop_emerg', 30, 'A client arrives in the PACU after a hernia repair. The nurse has confirmed a patent airway; RR 16 with clear breath sounds and SpO₂ 97%; BP 124/78 with brisk capillary refill; and the client is drowsy but oriented with reactive pupils. Which assessment should the nurse perform NEXT?', '[{"id": "a", "text": "Recheck the breath sounds and O₂ saturation"}, {"id": "b", "text": "Recheck capillary refill in all extremities"}, {"id": "c", "text": "Check for hypothermia and surgical site bleeding"}, {"id": "d", "text": "Assess bowel sounds, nausea, and abdominal distension"}]'::jsonb, '["c"]', 'Airway, Breathing, Circulation and Disability (neuro) are complete and normal, so the next ABCDES step is Exposure: hypothermia and surgical site bleeding. Rechecking breath sounds or capillary refill repeats steps already found normal.', false),
  ('postop_emerg', 31, 'A client arrives in the PACU after an open bowel procedure; morphine was given in the OR. The dressing has a small amount of bloody drainage, the client is shivering, and respirations are 8/min and shallow. Which assessment is the nurse''s PRIORITY?', '[{"id": "a", "text": "Bleeding on the surgical dressing"}, {"id": "b", "text": "Temperature and signs of hypothermia"}, {"id": "c", "text": "LOC, orientation, and pupil response"}, {"id": "d", "text": "Breath sounds and O₂ saturation"}]'::jsonb, '["d"]', 'Opioids and anesthesia can depress respiration, and Airway & Breathing are the first post-op priority, so the slow, shallow breathing is assessed first. Bleeding and hypothermia belong to Exposure, which comes later in ABCDES.', false),
  ('postop_emerg', 32, 'The nurse completes an ABCDES assessment on a client 45 minutes after arrival in the PACU. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Stridor with choking"}, {"id": "b", "text": "BP 84/50 with weak pulses and cold skin"}, {"id": "c", "text": "Heart rate of 88 bpm"}, {"id": "d", "text": "Low SpO₂ of 86%"}, {"id": "e", "text": "Urine output of 40 mL in the past hour"}]'::jsonb, '["a", "b", "d"]', 'Stridor is correct because it signals airway obstruction; an SpO₂ of 86% is correct because low SpO₂ signals hypoxia; BP 84/50 with weak pulses and cold skin is correct because it signals hypotension. An HR of 88 bpm is wrong because it is neither above 100 nor below 60 bpm, and 40 mL in an hour is wrong because it meets the 30 mL/hr minimum.', true),
  ('postop_emerg', 33, 'Midway through surgery, a client develops a rapidly rising temperature, severe jaw rigidity, and tachycardia. The nurse reviews the intraoperative medication record. Which agents on the record are known triggers of this reaction? Select all that apply.', '[{"id": "a", "text": "Dantrolene sodium"}, {"id": "b", "text": "Atropine"}, {"id": "c", "text": "Narcotics"}, {"id": "d", "text": "Sevoflurane"}, {"id": "e", "text": "Succinylcholine"}]'::jsonb, '["d", "e"]', 'These findings indicate malignant hyperthermia. Sevoflurane is correct because it is a listed volatile anesthetic trigger, and succinylcholine is correct because it is a listed trigger. Atropine is wrong because it is the treatment for symptomatic bradycardia; dantrolene is wrong because it is the antidote; narcotics are wrong because they are linked to hypoxia, ileus and urinary retention rather than this reaction.', true),
  ('postop_emerg', 34, 'Four hours after surgery, a client has a BP of 174/98 and reports a headache and sweating. The client had a normal BP before surgery. Which factors should the nurse assess as possible causes of this change? Select all that apply.', '[{"id": "a", "text": "Anxiety"}, {"id": "b", "text": "Fluid overload"}, {"id": "c", "text": "Dehydration"}, {"id": "d", "text": "Blood loss"}, {"id": "e", "text": "Pain"}]'::jsonb, '["a", "b", "e"]', 'Headache and sweating with a high BP indicate post-op hypertension. Pain is correct, anxiety is correct and fluid overload is correct because all three are listed causes of hypertension. Blood loss and dehydration are wrong because they are causes of hypotension.', true),
  ('postop_emerg', 35, 'On postoperative day 3, a client has a fever and crackles. The nurse is trying to tell whether the client has pneumonia or atelectasis. Which data support pneumonia? Select all that apply.', '[{"id": "a", "text": "Crackles"}, {"id": "b", "text": "Fever"}, {"id": "c", "text": "Purulent sputum"}, {"id": "d", "text": "Cough"}, {"id": "e", "text": "Aspiration during surgery"}]'::jsonb, '["c", "d", "e"]', 'Cough is correct and purulent sputum is correct because they are listed for pneumonia but not atelectasis; aspiration is correct because it is a listed cause of pneumonia. Crackles and fever are wrong because they occur in both atelectasis and pneumonia, so they do not support one over the other.', true),
  ('postop_emerg', 36, 'A client is on postoperative day 4 after a bowel resection with a new anastomosis. Which findings require IMMEDIATE follow-up because they suggest breakdown of the anastomosis? Select all that apply.', '[{"id": "a", "text": "Feculent wound drainage"}, {"id": "b", "text": "Sudden ''popping'' at the incision"}, {"id": "c", "text": "Rigid abdomen"}, {"id": "d", "text": "Worsening abdominal pain"}, {"id": "e", "text": "Fever and tachycardia"}]'::jsonb, '["a", "c", "d", "e"]', 'Feculent drainage is correct, worsening abdominal pain is correct, a rigid abdomen (peritonitis) is correct and fever with tachycardia is correct because all are listed signs of anastomotic leak on days 3–7. A sudden popping sensation is wrong because it is the sign of wound dehiscence.', true),
  ('postop_emerg', 37, 'The nurse receives report on four surgical clients. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Post-op patient with intestines visible through the incision"}, {"id": "b", "text": "Post-op patient with unilateral leg swelling, pain, and redness"}, {"id": "c", "text": "Post-op patient with no bowel sounds, distension, and nausea"}, {"id": "d", "text": "Post-op patient who has not voided since catheter removal"}]'::jsonb, '["a"]', 'Intestines visible through the incision indicate evisceration, an emergency needing moist sterile gauze and emergency surgery. DVT, paralytic ileus and urinary retention need treatment but are not described as surgical emergencies.', false),
  ('postop_emerg', 38, 'The nurse on a surgical unit is assigned four clients on postoperative day 2. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Post-op patient with fever, crackles, and dyspnea after shallow breathing"}, {"id": "b", "text": "Post-op patient with sudden dyspnea, chest pain, and low SpO₂"}, {"id": "c", "text": "Post-op patient with HR 56 bpm who is resting without dizziness"}, {"id": "d", "text": "Post-op patient with BP 150/88 who reports incisional pain"}]'::jsonb, '["b"]', 'Sudden dyspnea, chest pain and low SpO₂ indicate pulmonary embolism, an emergency requiring oxygen, anticoagulants and a call for help. Atelectasis also affects breathing but develops from shallow breathing and is treated with the incentive spirometer, deep breathing and ambulation.', false),
  ('postop_emerg', 39, 'A PACU nurse is caring for four clients who arrived from the OR within the past hour. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Post-op patient with BP 94/58, HR 112, and a damp dressing"}, {"id": "b", "text": "Post-op patient who is shivering with a low temperature"}, {"id": "c", "text": "Post-op patient with stridor, choking, and cyanosis"}, {"id": "d", "text": "Post-op patient with confusion while waking from anesthesia"}]'::jsonb, '["c"]', 'Stridor, choking and cyanosis indicate airway obstruction, and Airway is the first post-op priority. The client with low BP and tachycardia needs Circulation assessment for possible hemorrhage, which comes after a threatened airway.', false),
  ('postop_emerg', 40, 'A client on postoperative day 3 is receiving anticoagulants for unilateral leg swelling, pain, and redness in the left calf. During the shift, the nurse reassesses the client. Which new finding requires IMMEDIATE follow-up?', '[{"id": "a", "text": "Left calf swelling unchanged from yesterday"}, {"id": "b", "text": "Urine output of 45 mL in the past hour"}, {"id": "c", "text": "Request to walk in the hallway"}, {"id": "d", "text": "Sudden dyspnea with chest pain"}]'::jsonb, '["d"]', 'A PE occurs when the blood clot travels to the lungs and presents with sudden dyspnea and chest pain, an emergency. Unchanged calf swelling is the known DVT, and ambulation is part of DVT treatment.', false),
  ('postop_emerg', 41, 'On postoperative day 4 after a laparotomy, the nurse reviews the client''s history to plan care that lowers the risk that the incision will separate. Which client data increase this risk? Select all that apply.', '[{"id": "a", "text": "Obesity"}, {"id": "b", "text": "Wound infection"}, {"id": "c", "text": "Laryngospasm after extubation"}, {"id": "d", "text": "Poor healing of the incision"}, {"id": "e", "text": "Bradycardia during suctioning"}]'::jsonb, '["a", "b", "d"]', 'Obesity is correct, infection is correct and poor healing is correct because all three are listed causes of wound dehiscence. Bradycardia during suctioning is wrong because it reflects vagal stimulation, and laryngospasm is wrong because it is a cause of airway obstruction.', true),
  ('postop_emerg', 42, 'Eight hours after surgery, a client has not voided and has a distended bladder. The nurse reviews the record to identify contributing factors. Which factors are MOST likely contributing to this problem? Select all that apply.', '[{"id": "a", "text": "Opioids for pain"}, {"id": "b", "text": "Laryngospasm"}, {"id": "c", "text": "Vagal stimulation"}, {"id": "d", "text": "Recent catheter removal"}, {"id": "e", "text": "Fluid overload"}]'::jsonb, '["a", "d"]', 'No urine output with bladder distension indicates urinary retention. Opioids are correct and catheter removal is correct because both are listed causes of urinary retention. Vagal stimulation is wrong because it causes bradycardia; fluid overload is wrong because it is a cause of hypertension; laryngospasm is wrong because it causes airway obstruction.', true),
  ('postop_emerg', 43, 'Two hours after surgery, a client has a BP of 86/52, HR 126 bpm, pale skin, and dizziness, and the drain output has increased sharply. Which interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Blood transfusion"}, {"id": "b", "text": "Return to surgery"}, {"id": "c", "text": "IV fluids"}, {"id": "d", "text": "Antihypertensives"}, {"id": "e", "text": "Apply pressure"}]'::jsonb, '["a", "b", "c", "e"]', 'Low BP, tachycardia, pale skin and dizziness with increased drain output indicate post-op hemorrhage. Applying pressure is correct, IV fluids are correct, a blood transfusion is correct and surgery is correct because all are listed hemorrhage interventions. Antihypertensives are wrong because they treat hypertension, and this client is hypotensive.', true),
  ('postop_emerg', 44, 'On postoperative day 2, a client receiving opioids has lower abdominal distension. The nurse must decide whether the problem is paralytic ileus or urinary retention. Which finding MOST strongly indicates paralytic ileus?', '[{"id": "a", "text": "No bowel sounds with N/V"}, {"id": "b", "text": "No urine output since catheter removal"}, {"id": "c", "text": "Recent anesthesia and opioid use"}, {"id": "d", "text": "Bladder distension on palpation"}]'::jsonb, '["a"]', 'Paralytic ileus presents with no bowel sounds, distension and N/V. Anesthesia and opioids cause both ileus and urinary retention, so that history does not distinguish them, and no urine output with bladder distension points to retention.', false),
  ('postop_emerg', 45, 'Six hours after surgery, a client who received narcotics becomes restless and confused and keeps pulling at the IV line. The family says, ''She''s just still waking up from the anesthesia.'' Which action should the nurse take FIRST?', '[{"id": "a", "text": "Reorient the client and dim the lights"}, {"id": "b", "text": "Check the SpO₂ and respiratory rate"}, {"id": "c", "text": "Perform a full pupil and LOC assessment"}, {"id": "d", "text": "Ask the family to stay at the bedside"}]'::jsonb, '["b"]', 'Confusion and restlessness after narcotics can signal hypoxia, so the nurse checks breathing and SpO₂ first. A neuro (LOC and pupil) assessment is the Disability step, which follows Breathing.', false),
  ('postop_emerg', 46, 'On postoperative day 1, a client has an HR of 118 bpm, is grimacing, and rates incisional pain 9/10. BP is 132/80, SpO₂ is 97%, the dressing is dry, and urine output is 50 mL/hr. Which action is MOST appropriate?', '[{"id": "a", "text": "Administer atropine and then recheck the HR"}, {"id": "b", "text": "Give an IV fluid bolus for hypovolemia"}, {"id": "c", "text": "Give pain relief and recheck the HR"}, {"id": "d", "text": "Start IV antibiotics for infection"}]'::jsonb, '["c"]', 'Tachycardia is managed by treating the cause, and this client''s stable BP, dry dressing and adequate output point to pain rather than hypovolemia, so pain relief is the treatment. Atropine is for symptomatic bradycardia and would worsen a fast rate.', false),
  ('postop_emerg', 47, 'Four hours after a hip procedure, the nurse notes that a client''s drain output has increased. Which set of findings is MOST consistent with post-op hemorrhage?', '[{"id": "a", "text": "HR <60 bpm, dizziness, and fatigue"}, {"id": "b", "text": "Headache, chest pain, and sweating"}, {"id": "c", "text": "Sudden dyspnea, chest pain, and tachycardia"}, {"id": "d", "text": "Low BP, tachycardia, and pale skin"}]'::jsonb, '["d"]', 'Post-op hemorrhage presents with low BP, tachycardia, pale skin and dizziness. Sudden dyspnea and chest pain with tachycardia indicate PE, and headache with sweating indicates hypertension.', false),
  ('postop_emerg', 48, 'A client who has not voided for 8 hours after surgery has bladder distension. A bladder scan shows a large volume of urine, and the client still cannot void. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Insert a straight catheter"}, {"id": "b", "text": "Increase the IV fluid infusion rate"}, {"id": "c", "text": "Assess for kidney injury"}, {"id": "d", "text": "Repeat the bladder scan in 4 hours"}]'::jsonb, '["a"]', 'Urinary retention is managed with a bladder scan and then a straight catheter if needed; a large retained volume shows it is needed. Assessing for kidney injury applies to low output, but here urine is being made and retained.', false),
  ('postop_emerg', 49, 'A client in the PACU after general anesthesia has gurgling respirations, visible secretions in the mouth, and an SpO₂ that has dropped from 96% to 89%. The head is already positioned to open the airway. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Encourage incentive spirometer use"}, {"id": "b", "text": "Suction the airway"}, {"id": "c", "text": "Provide pain control"}, {"id": "d", "text": "Check capillary refill"}]'::jsonb, '["b"]', 'Secretions are a cause of airway obstruction, and with the head already repositioned, suctioning is the next airway intervention. The incentive spirometer treats atelectasis but cannot clear an obstructed airway.', false),
  ('postop_emerg', 50, 'A newly hired nurse is receiving a client from the OR into the PACU. Which plan by the newly hired nurse requires correction by the preceptor?', '[{"id": "a", "text": "Monitor the respiratory rate closely after opioids"}, {"id": "b", "text": "Check BP, HR, and capillary refill to assess circulation"}, {"id": "c", "text": "Check LOC and orientation before checking the airway"}, {"id": "d", "text": "Check for hypothermia and surgical site bleeding"}]'::jsonb, '["c"]', 'The first post-op priority is Airway & Breathing, so assessing LOC (Disability) before ensuring a patent airway is out of order. Monitoring respirations after opioids is correct because opioids and anesthesia can depress respiration.', false),
  ('overview', 1, 'A client is admitted after a diving accident that caused a spinal cord injury. Two hours later the client''s blood pressure is 78/42 mm Hg, and the provider states the client is in shock related to the injury. Which treatment does the nurse anticipate as FIRST-line therapy for this client''s shock?', '[{"id": "a", "text": "Vasopressors plus atropine"}, {"id": "b", "text": "Dobutamine to improve contractility"}, {"id": "c", "text": "IV antibiotics plus IV fluids"}, {"id": "d", "text": "Epinephrine IM"}]'::jsonb, '["a"]', 'Shock caused by a spinal cord injury is neurogenic shock, treated with vasopressors + atropine (dopamine, norepinephrine). Improving contractility with dobutamine is the treatment for cardiogenic shock caused by MI or heart failure.', false),
  ('overview', 2, 'A client who had a myocardial infarction 1 day ago now has a BP of 82/50 mm Hg and a heart rate of 118/min, and the provider diagnoses shock caused by the MI. Which prescription requires follow-up with the provider BEFORE the nurse implements it?', '[{"id": "a", "text": "Dobutamine infusion"}, {"id": "b", "text": "Dopamine infusion"}, {"id": "c", "text": "Diuretics as prescribed"}, {"id": "d", "text": "IV fluid bolus of 2 liters"}]'::jsonb, '["d"]', 'Shock caused by an MI is cardiogenic shock; first-line treatment is to improve contractility (not excess fluids), so a 2-liter fluid bolus should be questioned. Dobutamine, dopamine, and diuretics are the key medications for cardiogenic shock.', false),
  ('overview', 3, 'A client who is bleeding heavily after a motor vehicle crash has a BP of 82/48 mm Hg, a heart rate of 130/min, and cool, clammy skin. Which prescriptions does the nurse anticipate to treat this client''s shock? Select all that apply.', '[{"id": "a", "text": "Dobutamine"}, {"id": "b", "text": "IV fluids: NS"}, {"id": "c", "text": "Packed RBCs"}, {"id": "d", "text": "Atropine"}, {"id": "e", "text": "IV fluids: LR"}]'::jsonb, '["b", "c", "e"]', 'Shock from bleeding is hypovolemic shock, treated with IV fluids/blood products: NS (b), packed RBCs (c), and LR (e) are correct. Dobutamine (a) improves contractility for cardiogenic shock, and atropine (d) is given with vasopressors for neurogenic shock from a spinal cord injury.', true),
  ('overview', 4, 'A client with a severe kidney infection has a BP of 84/46 mm Hg, a heart rate of 124/min, and is diagnosed with shock caused by the infection. Prescriptions include norepinephrine, dopamine, an IV fluid bolus, and IV antibiotics. Which prescription should the nurse implement FIRST?', '[{"id": "a", "text": "Norepinephrine infusion"}, {"id": "b", "text": "IV antibiotics"}, {"id": "c", "text": "IV fluid bolus"}, {"id": "d", "text": "Dopamine infusion"}]'::jsonb, '["b"]', 'Shock caused by severe infection is septic shock, and the treatment is IV antibiotics FIRST, followed by fluids and vasopressors. Norepinephrine and dopamine are the key vasopressors for septic shock but are not the first action.', false),
  ('overview', 5, 'Five minutes after receiving the first dose of a new IV medication, a client with a history of severe allergies becomes hypotensive and tachycardic and is diagnosed with a severe allergic reaction causing shock. Which medication should the nurse administer FIRST?', '[{"id": "a", "text": "Diphenhydramine IV"}, {"id": "b", "text": "Steroids IV"}, {"id": "c", "text": "Epinephrine IM"}, {"id": "d", "text": "Norepinephrine drip"}]'::jsonb, '["c"]', 'Shock from severe allergy is anaphylactic shock, and epinephrine IM is given FIRST. Diphenhydramine and steroids are also key medications for anaphylactic shock but follow epinephrine.', false),
  ('overview', 6, 'A client 6 hours after abdominal surgery had a heart rate of 112/min and cool, clammy skin at 1400. At 1600 the nurse reassesses the client for worsening shock. Which findings indicate the client has progressed to LATE shock? Select all that apply.', '[{"id": "a", "text": "Tachycardia"}, {"id": "b", "text": "Severe hypotension"}, {"id": "c", "text": "Cool, clammy skin"}, {"id": "d", "text": "LOC ↓"}, {"id": "e", "text": "Organ failure"}]'::jsonb, '["b", "d", "e"]', 'Late shock causes severe hypotension (b), decreased LOC (d), and organ failure (e). Tachycardia (a) and cool, clammy skin (c) are signs of early shock and were already present at 1400, so they do not indicate progression.', true),
  ('overview', 7, 'A client with chest trauma develops a pneumothorax. The client''s BP is 80/50 mm Hg and heart rate is 128/min, and the provider states the shock is caused by the pneumothorax. Which intervention is the PRIORITY treatment for this client''s shock?', '[{"id": "a", "text": "Large-volume isotonic IV fluids"}, {"id": "b", "text": "Dobutamine to improve contractility"}, {"id": "c", "text": "Vasopressors plus atropine"}, {"id": "d", "text": "Chest tube to remove obstruction"}]'::jsonb, '["d"]', 'Shock caused by a pneumothorax is obstructive shock, and first-line treatment is to remove the obstruction (anticoagulants, chest tube, surgery). Dobutamine treats cardiogenic shock, and vasopressors plus atropine treat neurogenic shock.', false),
  ('overview', 8, 'A client 4 hours after surgery has a heart rate that has risen from 84/min to 116/min, cool and clammy skin, BP 118/76 mm Hg (baseline 120/78 mm Hg), and is alert and oriented. Which interpretation of these findings is MOST accurate?', '[{"id": "a", "text": "Late shock with organ failure"}, {"id": "b", "text": "Early shock"}, {"id": "c", "text": "Expected findings after surgery"}, {"id": "d", "text": "Late shock with LOC changes"}]'::jsonb, '["b"]', 'Tachycardia with cool, clammy skin is early shock. Late shock would show severe hypotension, decreased LOC, and organ failure, none of which are present because the BP is unchanged and the client is alert.', false),
  ('overview', 9, 'A client receiving a continuous heparin infusion has an aPTT of 4 times normal and new bleeding from the gums and IV site. Which medication should the nurse have available IMMEDIATELY?', '[{"id": "a", "text": "Protamine sulfate"}, {"id": "b", "text": "Vitamin K"}, {"id": "c", "text": "Flumazenil"}, {"id": "d", "text": "N-acetylcysteine"}]'::jsonb, '["a"]', 'The heparin aPTT goal is 1.5–2.5× normal, so 4 times normal with bleeding indicates excess heparin; its antidote is protamine sulfate. Vitamin K is the antidote for warfarin, not heparin.', false),
  ('overview', 10, 'The nurse reviews morning laboratory results for a client in each of four rooms who is receiving anticoagulant therapy. Which client''s result requires follow-up with the provider?', '[{"id": "a", "text": "Heparin infusion; aPTT 2 times normal"}, {"id": "b", "text": "Warfarin; INR 2.4"}, {"id": "c", "text": "Warfarin; INR 3.8"}, {"id": "d", "text": "Heparin infusion; aPTT 1.8 times normal"}]'::jsonb, '["c"]', 'The warfarin goal INR is 2–3, so an INR of 3.8 is above goal and requires follow-up. An INR of 2.4 and aPTT values of 1.8 and 2 times normal are all within the stated goals (heparin aPTT 1.5–2.5× normal).', false),
  ('overview', 11, 'A client is admitted with a severe infection, a BP of 80/44 mm Hg, and a heart rate of 126/min, and is diagnosed with septic shock. Which prescriptions does the nurse anticipate for this client''s shock? Select all that apply.', '[{"id": "a", "text": "Epinephrine IM"}, {"id": "b", "text": "IV antibiotics"}, {"id": "c", "text": "Norepinephrine"}, {"id": "d", "text": "Dopamine"}, {"id": "e", "text": "IV fluids"}]'::jsonb, '["b", "c", "d", "e"]', 'Septic shock is treated with IV antibiotics first (b) plus fluids (e) and vasopressors; norepinephrine (c) and dopamine (d) are the key medications. Epinephrine IM (a) is the first treatment for anaphylactic shock, not septic shock.', true),
  ('overview', 12, 'A client who is 1 day post-op received IV morphine 1 hour ago. The client is drowsy and difficult to keep awake, with a respiratory rate of 10/min, and the next opioid dose is now due. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Give the dose and recheck RR in 30 minutes"}, {"id": "b", "text": "Hold the dose and give flumazenil"}, {"id": "c", "text": "Hold the dose and give Narcan"}, {"id": "d", "text": "Give half of the dose as prescribed"}]'::jsonb, '["c"]', 'A respiratory rate below 12 on opioids means the nurse should hold the dose and give Narcan (naloxone), the opioid antidote. Flumazenil reverses benzodiazepines, not opioids.', false),
  ('overview', 13, 'A client is brought to the emergency department after intentionally swallowing a large amount of acetaminophen along with a bottle of a benzodiazepine. The client takes no opioids or anticoagulants. Which antidotes does the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Naloxone (Narcan)"}, {"id": "b", "text": "Flumazenil"}, {"id": "c", "text": "Protamine sulfate"}, {"id": "d", "text": "N-acetylcysteine"}, {"id": "e", "text": "Digibind"}]'::jsonb, '["b", "d"]', 'Flumazenil (b) reverses benzodiazepines and N-acetylcysteine (d) is the antidote for acetaminophen. Naloxone (a) reverses opioids, protamine sulfate (c) reverses heparin, and Digibind (e) reverses digoxin; none of these drugs were taken.', true),
  ('overview', 14, 'A client with diabetes accidentally receives twice the prescribed dose of insulin and 1 hour later is found unresponsive and diaphoretic. The client takes no opioids or sedatives. Which medication should the nurse prepare to give IMMEDIATELY?', '[{"id": "a", "text": "Naloxone (Narcan)"}, {"id": "b", "text": "Flumazenil"}, {"id": "c", "text": "Vitamin K"}, {"id": "d", "text": "Glucagon or D50"}]'::jsonb, '["d"]', 'The antidote for insulin overdose is glucagon or D50. Naloxone reverses opioids and flumazenil reverses benzodiazepines, which the client has not taken.', false),
  ('overview', 15, 'At 0730 the nurse prepares a client''s prescribed insulin lispro. The dietary department calls to say the client''s breakfast tray is delayed and will not arrive until 0830. Which action by the nurse is BEST?', '[{"id": "a", "text": "Hold the lispro to give with meals"}, {"id": "b", "text": "Give the lispro now; onset is 30–60 min"}, {"id": "c", "text": "Give the lispro now; onset is 1–2 hr"}, {"id": "d", "text": "Replace it with glargine, which has no peak"}]'::jsonb, '["a"]', 'Rapid-acting lispro has an onset of 15 minutes and is given with meals, so it should be held until the tray arrives. An onset of 30–60 minutes describes regular insulin, not lispro.', false),
  ('overview', 16, 'The nurse teaches a client newly prescribed insulin glargine once daily and insulin lispro with meals. Which statements by the client indicate understanding of the teaching? Select all that apply.', '[{"id": "a", "text": "\"Glargine has no peak and lasts 24 hours.\""}, {"id": "b", "text": "\"Lispro has an onset of about 15 minutes.\""}, {"id": "c", "text": "\"Glargine has an onset of about 15 minutes.\""}, {"id": "d", "text": "\"Glargine has a peak like NPH insulin.\""}, {"id": "e", "text": "\"I take lispro with meals.\""}]'::jsonb, '["a", "b", "e"]', 'Glargine has no peak and lasts 24 hours (a), and lispro has a 15-minute onset (b) and is taken with meals (e). Glargine''s onset is 1–2 hours, not 15 minutes (c), and NPH has a peak while glargine does not (d).', true),
  ('overview', 17, 'A client scheduled for surgery in 1 hour is anxious and asks for the prescribed pre-op sedative. While preparing the medication, the nurse notes that the surgical consent form has not been signed. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Give the sedative, then witness the consent"}, {"id": "b", "text": "Obtain signed consent before any sedatives"}, {"id": "c", "text": "Have a family member sign the consent now"}, {"id": "d", "text": "Give the sedative and notify the surgeon"}]'::jsonb, '["b"]', 'Consent must be obtained before any sedatives are given. Giving the sedative first, even with a plan to obtain consent afterward, violates this rule.', false),
  ('overview', 18, 'A client scheduled for surgery under general anesthesia at 1000 tells the nurse at 0800, "I was so hungry that I ate a piece of toast at 0700." Which action should the nurse take NEXT?', '[{"id": "a", "text": "Document the intake and continue pre-op care"}, {"id": "b", "text": "Give the pre-op Ondansetron early"}, {"id": "c", "text": "Notify the surgeon; surgery may be delayed"}, {"id": "d", "text": "Reschedule surgery for 2 hours later"}]'::jsonb, '["c"]', 'Clients should be NPO 6–8 hours before general anesthesia; if the patient ate, the nurse notifies the surgeon because surgery may be delayed. The nurse does not reschedule surgery independently.', false),
  ('overview', 19, 'The nurse is completing the pre-op checklist for a client with atrial fibrillation who is scheduled for surgery under general anesthesia. Which items must the nurse verify before the client goes to surgery? Select all that apply.', '[{"id": "a", "text": "NPO for at least 2 hours"}, {"id": "b", "text": "Signed consent"}, {"id": "c", "text": "Labs"}, {"id": "d", "text": "Allergies"}, {"id": "e", "text": "Warfarin status"}]'::jsonb, '["b", "c", "d", "e"]', 'Pre-op the nurse verifies signed consent (b), labs (c), allergies (d), and warfarin status (e). NPO for 2 hours (a) is not enough; clients are NPO 6–8 hours before general anesthesia.', true),
  ('overview', 20, 'A client who had a total knee replacement yesterday asks the nurse, "How long do I have to stay in bed before I can put weight on this leg?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"You will stay on bed rest until the CPM is stopped.\""}, {"id": "b", "text": "\"You can bear weight only after the incision heals.\""}, {"id": "c", "text": "\"You will not bear weight for about 6 weeks.\""}, {"id": "d", "text": "\"Early weight bearing with an assistive device is used.\""}]'::jsonb, '["d"]', 'After TKR, the client begins early weight bearing with an assistive device, and early ambulation prevents DVT. Bed rest until the CPM is stopped or delayed weight bearing contradicts the TKR plan.', false),
  ('overview', 21, 'The nurse in the PACU receives reports on four clients. Which client should the nurse assess FIRST?', '[{"id": "a", "text": "Stridor with cyanosis and ↓ O₂"}, {"id": "b", "text": "Urine output of 28 mL/hr"}, {"id": "c", "text": "Incisional pain rated 8/10"}, {"id": "d", "text": "Pink, watery drainage on dressing"}]'::jsonb, '["a"]', 'Airway & Breathing is priority #1 in the PACU, and stridor with cyanosis and ↓ O₂ means airway obstruction. Urine output of 28 mL/hr is below the ≥30 mL/hr goal and must be reported, but it is not an airway problem; serosanguineous (pink/watery) drainage is normal healing.', false),
  ('overview', 22, 'Twenty minutes after extubation, a client in the PACU develops a high-pitched sound on inspiration, cyanosis of the lips, and an SpO₂ that drops from 96% to 88%. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Encourage incentive spirometer and deep breathing"}, {"id": "b", "text": "Call for help; reposition, suction, airway support"}, {"id": "c", "text": "Give O₂ and prepare to give anticoagulants"}, {"id": "d", "text": "Hold the opioid dose and give Narcan"}]'::jsonb, '["b"]', 'Stridor with cyanosis and decreased O₂ is airway obstruction; the nurse calls for help and repositions, suctions, and supports the airway. O₂ with anticoagulants is the intervention for PE, which presents with sudden SOB, chest pain, and tachycardia.', false),
  ('overview', 23, 'The nurse reviews urine output for five clients recovering from surgery on the unit. Which clients'' findings require the nurse to notify the provider? Select all that apply.', '[{"id": "a", "text": "Urine output of 25 mL/hr"}, {"id": "b", "text": "Urine output of 30 mL/hr"}, {"id": "c", "text": "110 mL urine over 4 hours"}, {"id": "d", "text": "140 mL urine over 4 hours"}, {"id": "e", "text": "No urine output, distended bladder"}]'::jsonb, '["a", "c", "e"]', 'Post-op urine output should be ≥30 mL/hr; 25 mL/hr (a) and 110 mL over 4 hours, which is 27.5 mL/hr (c), are below that, and no urine output with a distended bladder (e) indicates urinary retention. 30 mL/hr (b) and 140 mL over 4 hours, which is 35 mL/hr (d), meet the goal.', true),
  ('overview', 24, 'A client arrives in the PACU at 1400. The nurse obtains vital signs every 15 minutes as prescribed by the post-op protocol and completes the fourth set of 15-minute vital signs at 1500. The client is stable. At what time should the nurse obtain the NEXT set of vital signs?', '[{"id": "a", "text": "1515"}, {"id": "b", "text": "1530"}, {"id": "c", "text": "1600"}, {"id": "d", "text": "1900"}]'::jsonb, '["c"]', 'PACU vital signs are taken every 15 minutes × 4, then hourly, so after the fourth set at 1500 the next set is due at 1600. 1515 would continue the 15-minute schedule beyond the four required sets.', false),
  ('overview', 25, 'A client who had abdominal surgery 8 hours ago has not voided since surgery, and the nurse palpates a distended bladder. The client''s IV fluids are infusing as prescribed. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Insert a straight catheter"}, {"id": "b", "text": "Perform a bladder scan"}, {"id": "c", "text": "Increase the IV fluid rate"}, {"id": "d", "text": "Insert an NG tube"}]'::jsonb, '["b"]', 'No urine output with a distended bladder suggests urinary retention; the nurse performs a bladder scan first and then a straight catheter if needed. Inserting a straight catheter before the bladder scan skips the first step.', false),
  ('overview', 26, 'A client who is 5 days post-op after abdominal surgery coughs forcefully and says, "Something just gave way." The nurse observes loops of bowel protruding through the opened incision. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Apply a dry sterile dressing and notify provider"}, {"id": "b", "text": "Apply pressure and increase IV fluids"}, {"id": "c", "text": "Have the client cough and deep breathe"}, {"id": "d", "text": "Cover with moist sterile gauze"}]'::jsonb, '["d"]', 'Organs protruding through the incision is evisceration: cover with moist sterile gauze, keep the client flat, and call the surgeon. A sterile dressing with notification of the provider is the intervention for wound dehiscence without protruding organs.', false),
  ('overview', 27, 'A client who is 3 days post-op reports nausea and vomiting. The nurse finds the abdomen distended and hears no bowel sounds in any quadrant. Which interventions does the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Clear liquid diet"}, {"id": "b", "text": "NPO"}, {"id": "c", "text": "NG tube"}, {"id": "d", "text": "Ambulate"}, {"id": "e", "text": "IV fluids"}]'::jsonb, '["b", "c", "d", "e"]', 'No bowel sounds, distension, and N/V indicate paralytic ileus, treated with NPO (b), an NG tube (c), ambulation (d), and IV fluids (e). A clear liquid diet (a) contradicts the NPO order.', true),
  ('overview', 28, 'On post-op day 6, a client''s abdominal incision edges have partially separated after a coughing episode. No organs are visible, and vital signs are within the client''s baseline. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Apply a sterile dressing and notify provider"}, {"id": "b", "text": "Apply pressure and give IV fluids"}, {"id": "c", "text": "Have the client use the incentive spirometer"}, {"id": "d", "text": "Reposition and suction the client"}]'::jsonb, '["a"]', 'Separated wound edges without visible organs is wound dehiscence: apply a sterile dressing and notify the provider. Pressure and IV fluids are interventions for hemorrhage, which would present with low BP, tachycardia, and pallor.', false),
  ('overview', 29, 'A client 3 days after hip surgery suddenly becomes short of breath and reports chest pain. The heart rate is 124/min and the client is anxious. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Encourage incentive spirometer use"}, {"id": "b", "text": "Give O₂ and call the provider now"}, {"id": "c", "text": "Assess the calves for unilateral swelling"}, {"id": "d", "text": "Ambulate to improve breath sounds"}]'::jsonb, '["b"]', 'Sudden SOB, chest pain, and tachycardia after surgery indicate PE, an EMERGENCY: give O₂ and call the provider NOW. Incentive spirometer use and ambulation are interventions for atelectasis.', false),
  ('overview', 30, 'Two hours after surgery, a client''s BP has dropped from 128/80 to 88/52 mm Hg, the heart rate is 128/min, and the client is pale with a blood-soaked dressing. Which interventions does the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Apply pressure"}, {"id": "b", "text": "NG tube"}, {"id": "c", "text": "IV fluids"}, {"id": "d", "text": "Blood transfusion"}, {"id": "e", "text": "Prepare for surgery"}]'::jsonb, '["a", "c", "d", "e"]', 'Decreased BP, tachycardia, and pallor with bleeding indicate hemorrhage, treated with pressure (a), IV fluids (c), blood transfusion (d), and surgery (e). An NG tube (b) is an intervention for paralytic ileus.', true),
  ('overview', 31, 'On post-op day 1, a client who has stayed in bed has decreased breath sounds in both lung bases and an SpO₂ of 91% on room air. The heart rate is 88/min, and the client denies chest pain. Which action is BEST?', '[{"id": "a", "text": "Give O₂ and anticoagulants"}, {"id": "b", "text": "Keep NPO and insert an NG tube"}, {"id": "c", "text": "Incentive spirometer, deep breathing, ambulate"}, {"id": "d", "text": "Reposition and suction the airway"}]'::jsonb, '["c"]', 'Decreased breath sounds with hypoxia in a client who has not ambulated suggests atelectasis, treated with incentive spirometer, deep breathing, and ambulation. O₂ and anticoagulants are for PE, which presents with sudden SOB, chest pain, and tachycardia.', false),
  ('overview', 32, 'The nurse observes a client on post-op day 2 after a total hip replacement (THR). Which actions by the client indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "Abduction pillow between the legs"}, {"id": "b", "text": "Crossing midline with hip adduction"}, {"id": "c", "text": "Internal rotation of the operative hip"}, {"id": "d", "text": "Hip flexion kept below 90°"}, {"id": "e", "text": "Hip flexion >90° while sitting"}]'::jsonb, '["b", "c", "e"]', 'After THR there is no adduction (crossing the midline) (b), no internal rotation (c), and no hip flexion >90° (e), so these need further teaching. Using the abduction pillow (a) and keeping hip flexion below 90° (d) are correct.', true),
  ('overview', 33, 'A client who had a total knee replacement (TKR) yesterday asks why the leg is being moved by a machine for several hours a day. Which statement by the client indicates understanding of the nurse''s teaching?', '[{"id": "a", "text": "\"The CPM machine helps prevent stiffness.\""}, {"id": "b", "text": "\"The CPM machine keeps my hip from crossing midline.\""}, {"id": "c", "text": "\"The CPM machine replaces the need to walk.\""}, {"id": "d", "text": "\"The CPM machine checks my circulation.\""}]'::jsonb, '["a"]', 'After TKR, the CPM machine is used to prevent stiffness. Preventing crossing the midline relates to THR precautions, and early ambulation is still needed after TKR to prevent DVT.', false),
  ('overview', 34, 'The nurse is caring for four clients on an orthopedic unit. Which client should the nurse assess FIRST?', '[{"id": "a", "text": "THR client on post-op day 1 with an abduction pillow in place"}, {"id": "b", "text": "TKR client in a CPM machine who reports stiffness"}, {"id": "c", "text": "Client with a tight dressing, pain unrelieved by meds, and no pulse"}, {"id": "d", "text": "Client on enoxaparin who is due for incentive spirometer use"}]'::jsonb, '["c"]', 'Severe pain unrelieved by meds with a tight dressing and pulselessness indicates compartment syndrome, an emergency. An abduction pillow after THR and a CPM machine after TKR are expected parts of the plan of care.', false),
  ('overview', 35, 'A client with a forearm fracture has a tight dressing and reports severe pain that has not decreased after two doses of IV morphine. The radial pulse cannot be palpated. The nurse notifies the provider. Which intervention does the nurse anticipate as the PRIORITY treatment?', '[{"id": "a", "text": "Repeat the opioid dose"}, {"id": "b", "text": "Apply SCDs to both legs"}, {"id": "c", "text": "Neurovascular checks in 4 hours"}, {"id": "d", "text": "Emergency fasciotomy"}]'::jsonb, '["d"]', 'Pain unrelieved by meds, a tight dressing, and pulselessness indicate compartment syndrome, which requires fasciotomy as an emergency. Repeating the opioid does not treat the cause, and waiting 4 hours for checks delays emergency care.', false),
  ('overview', 36, 'The nurse is checking surgical wounds on four clients. Which wound finding requires follow-up?', '[{"id": "a", "text": "Post-op day 1: redness and swelling"}, {"id": "b", "text": "Post-op day 5: purulent drainage (pus)"}, {"id": "c", "text": "Post-op day 2: pink, watery drainage"}, {"id": "d", "text": "Post-op day 3: clear, watery drainage"}]'::jsonb, '["b"]', 'Purulent (pus) drainage indicates infection and requires follow-up. Redness and swelling on day 1 are expected in the inflammatory stage (0–3 days), and serosanguineous (pink/watery) and serous (clear/watery) drainage are normal.', false),
  ('overview', 37, 'The nurse assesses a client''s abdominal incision on post-op day 10. Which finding is an expected finding for the stage of wound healing on this day?', '[{"id": "a", "text": "Granulation tissue in the wound"}, {"id": "b", "text": "Redness and swelling as the main findings"}, {"id": "c", "text": "A mature, flat scar"}, {"id": "d", "text": "Purulent drainage"}]'::jsonb, '["a"]', 'Day 10 falls in the proliferative stage (3–21 days), marked by granulation. Redness and swelling are the inflammatory stage (0–3 days), and scar forms during maturation (weeks–months).', false),
  ('overview', 38, 'The nurse assesses a client''s incision and wound drain on post-op day 2. Which findings are expected at this time? Select all that apply.', '[{"id": "a", "text": "Clear, watery drainage"}, {"id": "b", "text": "Bloody drainage"}, {"id": "c", "text": "Pink, watery drainage"}, {"id": "d", "text": "Pus in the drainage"}, {"id": "e", "text": "Redness and swelling at the incision"}]'::jsonb, '["a", "c", "e"]', 'Serous (clear/watery) drainage is normal (a), serosanguineous (pink/watery) drainage is normal healing (c), and redness and swelling are expected in the inflammatory stage, days 0–3 (e). Sanguineous (bloody) drainage (b) signals an active bleed, and purulent drainage (d) signals infection.', true),
  ('overview', 39, 'A client''s serum sodium level is reported as critically low. Over the past hour the client has become confused and then had a seizure. Which IV fluid is MOST appropriate for this client?', '[{"id": "a", "text": "0.9% NS"}, {"id": "b", "text": "Lactated Ringer''s (LR)"}, {"id": "c", "text": "3% NS"}, {"id": "d", "text": "0.45% NS"}]'::jsonb, '["c"]', 'Hypertonic 3% NS is used for severe hyponatremia, which causes confusion and seizures. 0.45% NS is hypotonic and is used for cellular dehydration.', false),
  ('overview', 40, 'A client''s provider documents a diagnosis of cellular dehydration and asks the nurse to obtain the IV fluid that treats this problem. Which IV fluid prescription is MOST appropriate?', '[{"id": "a", "text": "0.9% NS"}, {"id": "b", "text": "LR"}, {"id": "c", "text": "3% NS"}, {"id": "d", "text": "0.45% NS"}]'::jsonb, '["d"]', 'Hypotonic 0.45% NS is used for cellular dehydration. Isotonic fluids (NS, LR) are used for fluid replacement, and 3% NS is hypertonic for severe hyponatremia.', false),
  ('overview', 41, 'A client''s laboratory results show a low calcium level and a high potassium level. Which findings would the nurse expect when assessing this client? Select all that apply.', '[{"id": "a", "text": "Chvostek sign"}, {"id": "b", "text": "Muscle cramps"}, {"id": "c", "text": "Tall T waves"}, {"id": "d", "text": "Trousseau sign"}, {"id": "e", "text": "Weakness"}]'::jsonb, '["a", "c", "d", "e"]', 'Low calcium causes Chvostek (a) and Trousseau (d) signs, and high potassium causes tall T waves (c) and weakness (e). Cramps (b) are a sign of low potassium, not high potassium.', true),
  ('overview', 42, 'A client who has had several days of vomiting has a low serum potassium level. Which assessment findings would the nurse MOST likely expect?', '[{"id": "a", "text": "Tall T waves and weakness"}, {"id": "b", "text": "Cramps and arrhythmias"}, {"id": "c", "text": "Chvostek and Trousseau signs"}, {"id": "d", "text": "Confusion and seizures"}]'::jsonb, '["b"]', 'Low potassium causes cramps and arrhythmias. Tall T waves and weakness are signs of high potassium, the opposite imbalance.', false),
  ('overview', 43, 'A client receiving IV fluids after surgery has a serum sodium level reported as low. The UAP reports that the client is now confused about where they are. Which interpretation of this finding is MOST likely?', '[{"id": "a", "text": "Confusion from ↓Na⁺"}, {"id": "b", "text": "Confusion from ↓Ca²⁺"}, {"id": "c", "text": "Confusion from ↑K⁺"}, {"id": "d", "text": "Expected after anesthesia"}]'::jsonb, '["a"]', 'Low sodium causes confusion and seizures, so new confusion is consistent with the client''s low sodium. Low calcium causes Chvostek/Trousseau signs, and high potassium causes tall T waves and weakness.', false),
  ('overview', 44, 'Twenty minutes after a unit of packed RBCs is started, the client reports chills and back pain. The BP has dropped from 124/76 to 98/58 mm Hg, and the heart rate has increased to 112/min. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Slow the transfusion rate"}, {"id": "b", "text": "Stop the transfusion"}, {"id": "c", "text": "Notify HCP & blood bank"}, {"id": "d", "text": "Recheck vitals in 15 minutes"}]'::jsonb, '["b"]', 'Chills, back pain, hypotension, and tachycardia are transfusion reaction signs, and the first step is to STOP the transfusion. Notifying the HCP and blood bank comes after stopping and starting NS through new tubing.', false),
  ('overview', 45, 'A client receiving packed RBCs develops fever, chills, and hypotension. The nurse has just stopped the transfusion. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Notify HCP & blood bank"}, {"id": "b", "text": "Restart the unit at a slower rate"}, {"id": "c", "text": "Start NS through new tubing"}, {"id": "d", "text": "Flush the blood tubing with NS"}]'::jsonb, '["c"]', 'After the transfusion is stopped, the nurse starts NS through new tubing and then notifies the HCP & blood bank. Using the existing blood tubing is incorrect because the sequence requires new tubing.', false),
  ('overview', 46, 'The charge nurse observes a new nurse who is giving a unit of packed RBCs to a client with anemia. Which actions by the new nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Primes the Y-tubing with LR"}, {"id": "b", "text": "Stays with the patient for the first 15 minutes"}, {"id": "c", "text": "Plans for the unit to infuse within 4 hours"}, {"id": "d", "text": "Uses filtered Y-tubing with NS"}, {"id": "e", "text": "Leaves the room once the first 5 minutes pass"}]'::jsonb, '["b", "c", "d"]', 'The nurse stays with the patient for the first 15 minutes (b), infuses blood within 4 hours (c), and uses filtered Y-tubing with NS only (d). Priming with LR (a) violates the NS-only rule, and leaving after 5 minutes (e) is too early.', true),
  ('overview', 47, 'A client who is prescribed enoxaparin after hip surgery asks the nurse, "Why don''t I need daily blood tests like my neighbor who takes warfarin?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Enoxaparin needs less monitoring.\""}, {"id": "b", "text": "\"Enoxaparin is monitored by INR weekly.\""}, {"id": "c", "text": "\"Enoxaparin is monitored by aPTT daily.\""}, {"id": "d", "text": "\"Enoxaparin needs the same monitoring as warfarin.\""}]'::jsonb, '["a"]', 'Enoxaparin requires less monitoring than heparin or warfarin. INR monitoring is used for warfarin and aPTT monitoring is used for heparin.', false),
  ('overview', 48, 'A client on post-op day 1 after a total hip replacement asks how blood clots will be prevented. Which interventions does the nurse include in the plan for DVT prophylaxis? Select all that apply.', '[{"id": "a", "text": "SCDs"}, {"id": "b", "text": "Bed rest until day 3"}, {"id": "c", "text": "Enoxaparin"}, {"id": "d", "text": "Daily aPTT for enoxaparin"}, {"id": "e", "text": "Avoid incentive spirometer"}]'::jsonb, '["a", "c"]', 'DVT prophylaxis for orthopedic clients includes SCDs (a) and enoxaparin (c), along with ambulation. Bed rest (b) contradicts early ambulation to prevent DVT, enoxaparin needs less monitoring (d), and the incentive spirometer (e) is part of all ortho care.', true),
  ('overview', 49, 'A client on warfarin with atrial fibrillation has an INR of 5.2 and is oozing blood from a recent venipuncture site. Which antidote is MOST appropriate for the nurse to anticipate?', '[{"id": "a", "text": "Protamine sulfate"}, {"id": "b", "text": "Naloxone (Narcan)"}, {"id": "c", "text": "Digibind"}, {"id": "d", "text": "Vitamin K"}]'::jsonb, '["d"]', 'The warfarin INR goal is 2–3, so 5.2 with bleeding indicates excess warfarin, and the antidote is vitamin K. Protamine sulfate reverses heparin, not warfarin.', false),
  ('overview', 50, 'The nurse on a surgical unit receives reports on four post-op clients. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Client with BP 86/50 mm Hg, HR 124/min, and pallor"}, {"id": "b", "text": "Client with abdominal distension and no bowel sounds"}, {"id": "c", "text": "Client with unilateral leg pain and redness"}, {"id": "d", "text": "Client who has not voided and has a distended bladder"}]'::jsonb, '["a"]', 'Decreased BP, tachycardia, and pallor indicate hemorrhage, a circulation problem requiring pressure, IV fluids, blood transfusion, or surgery. Paralytic ileus, DVT, and urinary retention are serious but do not pose the immediate threat of hemorrhage.', false),
  ('shock', 1, 'A client is 3 hours postoperative after a total hip arthroplasty. Over the past hour the heart rate has risen from 84 to 116 bpm, the skin has become cool and clammy, and the client is restless and anxious, repeatedly trying to get out of bed. Peripheral pulses are palpable and the client is alert and oriented. Which interpretation of these findings is MOST accurate?', '[{"id": "a", "text": "Late decompensated shock, with organs beginning to fail"}, {"id": "b", "text": "Early compensated shock; blood diverted to vital organs"}, {"id": "c", "text": "Expected postoperative anxiety that needs reassurance only"}, {"id": "d", "text": "Decompensated shock; restlessness means low O₂ to brain"}]'::jsonb, '["b"]', 'Tachycardia, cool clammy skin (blood diverted to vital organs), and restlessness and anxiety (low O₂ to brain) are early signs of compensated shock, when the body is adapting. Decompensated shock brings weak or absent peripheral pulses, slow shallow breathing, and loss of consciousness, none of which this client has.', false),
  ('shock', 2, 'The nurse receives handoff report on four clients being treated for shock in the intermediate care unit. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Client with septic shock on norepinephrine whose MAP is 68 mmHg"}, {"id": "b", "text": "Client with hypovolemic shock whose HR fell from 118 to 96 bpm after fluids"}, {"id": "c", "text": "Client with septic shock whose legs are now cool, pale, and mottled"}, {"id": "d", "text": "Client with cardiogenic shock whose SpO2 is 95% on a non-rebreather mask"}]'::jsonb, '["c"]', 'Cool, pale, mottled skin means poor perfusion, and the nurse must act immediately. A MAP of 68 mmHg meets the MAP ≥65 mmHg target, a HR of 96 bpm is within 60–100 bpm, and an SpO2 of 95% meets the ≥94% target.', false),
  ('shock', 3, 'A client with a lacerated spleen was admitted 2 hours ago with a heart rate of 124 bpm and was anxious. The transfusion has been delayed, and the nurse now reassesses the client. Which findings indicate the client has progressed to decompensated shock? Select all that apply.', '[{"id": "a", "text": "Severe hypotension at 68/40 mmHg"}, {"id": "b", "text": "Restlessness and anxiety"}, {"id": "c", "text": "Weak or absent peripheral pulses"}, {"id": "d", "text": "Slow, shallow breathing at 8/min"}, {"id": "e", "text": "Loss of consciousness"}]'::jsonb, '["a", "c", "d", "e"]', 'Severe hypotension (dangerously low BP), weak or absent peripheral pulses, slow shallow breathing (respiratory failure), and loss of consciousness (brain not getting O₂) are late signs of decompensated shock, when organs are failing. Restlessness and anxiety are an early, compensated sign (low O₂ to brain) that the client already had on admission, so it does not show progression.', true),
  ('shock', 4, 'A client admitted after a diving accident with a cervical spinal cord injury has a BP of 84/50 mmHg and a heart rate of 46 bpm. IV fluids and dopamine are infusing. Which additional medication is the nurse MOST likely to prepare to address the heart rate?', '[{"id": "a", "text": "Dobutamine"}, {"id": "b", "text": "Epinephrine IM"}, {"id": "c", "text": "Atropine"}, {"id": "d", "text": "Diphenhydramine"}]'::jsonb, '["c"]', 'Neurogenic shock from a spinal cord injury is treated with dopamine, norepinephrine, IV fluids, and atropine for low HR. Dobutamine increases contractility in cardiogenic shock, and epinephrine IM is the first drug for anaphylactic shock.', false),
  ('shock', 5, 'A client with pyelonephritis is now confused, with a BP of 82/48 mmHg, a heart rate of 122 bpm, and a lactate of 4.2 mmol/L. The airway is patent, SpO2 is 95% on oxygen, and blood cultures have been drawn. Which prescription should the nurse implement FIRST?', '[{"id": "a", "text": "Norepinephrine infusion"}, {"id": "b", "text": "IV antibiotics"}, {"id": "c", "text": "Dobutamine infusion"}, {"id": "d", "text": "Atropine IV"}]'::jsonb, '["b"]', 'Infection with low BP and an elevated lactate (tissue hypoperfusion, a sepsis indicator) points to septic shock, and the first priority is IV antibiotics ASAP. Norepinephrine supports the BP in septic shock but is not the first priority.', false),
  ('shock', 6, 'A client admitted with 3 days of vomiting and diarrhea is being monitored for shock. The nurse wants to recognize the stage while the body is still adapting. Which findings would the nurse identify as early signs of compensated shock? Select all that apply.', '[{"id": "a", "text": "Weak or absent peripheral pulses"}, {"id": "b", "text": "Tachycardia of 122 bpm"}, {"id": "c", "text": "Slow, shallow breathing"}, {"id": "d", "text": "Cool, clammy skin"}, {"id": "e", "text": "Restlessness and anxiety"}]'::jsonb, '["b", "d", "e"]', 'Tachycardia (trying to maintain blood flow), cool clammy skin (blood diverted to vital organs), and restlessness and anxiety (low O₂ to brain) are early signs of compensated shock. Weak or absent peripheral pulses and slow, shallow breathing are late signs of decompensated shock, when organs are failing.', true),
  ('shock', 7, 'A client 1 day after an MI has a BP of 84/58 mmHg, a heart rate of 118 bpm, crackles in both lung bases, and cool skin, and cardiogenic shock is diagnosed. Which prescription requires follow-up with the provider before the nurse implements it?', '[{"id": "a", "text": "Dobutamine infusion"}, {"id": "b", "text": "IV diuretic to remove excess fluid volume"}, {"id": "c", "text": "100% O₂ via non-rebreather mask"}, {"id": "d", "text": "IV fluids at a high rate to raise BP"}]'::jsonb, '["d"]', 'In cardiogenic shock the goal is to improve heart pumping and avoid excess IV fluids, so a high-rate fluid order needs clarification. Dobutamine and diuretics are key medications for cardiogenic shock, and 100% O₂ is part of ABCS.', false),
  ('shock', 8, 'A client with blunt chest trauma has a BP of 78/50 mmHg, a heart rate of 132 bpm, and an SpO2 of 88% on 100% O₂. A tension pneumothorax is identified, and IV fluids are infusing. Which intervention will MOST directly stop the cause of this client''s shock?', '[{"id": "a", "text": "Dobutamine infusion"}, {"id": "b", "text": "Norepinephrine infusion"}, {"id": "c", "text": "Chest tube insertion"}, {"id": "d", "text": "Blood transfusion"}]'::jsonb, '["c"]', 'A tension pneumothorax causes obstructive shock, a physical blockage of blood flow, and the treatment is to remove the obstruction with a chest tube. Vasopressors are for distributive shock and blood transfusion is for hemorrhagic shock.', false),
  ('shock', 9, 'The charge nurse reviews five clients who are hypotensive. Which clients'' low BP is MOST likely caused by blood vessels dilating so that blood pools instead of circulating? Select all that apply.', '[{"id": "a", "text": "Client with sepsis from an infection"}, {"id": "b", "text": "Client with an acute MI and crackles"}, {"id": "c", "text": "Client with a large PE"}, {"id": "d", "text": "Client with anaphylaxis from an allergy"}, {"id": "e", "text": "Client with severe burns over the trunk"}]'::jsonb, '["a", "d"]', 'Distributive shock (vessels dilate, blood pools) includes sepsis and anaphylaxis, so both of those clients are correct. An MI causes cardiogenic shock (heart cannot pump), a PE causes obstructive shock (physical blockage), and burns cause hypovolemic shock (loss of fluids).', true),
  ('shock', 10, 'An older client with 4 days of diarrhea has a heart rate of 124 bpm, a BP of 86/52 mmHg, cool and clammy skin, and no signs of bleeding. Two large-bore IV lines are in place. Which prescription is the BEST first-line treatment for this client?', '[{"id": "a", "text": "Packed RBC transfusion of 2 units"}, {"id": "b", "text": "Dobutamine infusion"}, {"id": "c", "text": "Norepinephrine infusion"}, {"id": "d", "text": "IV fluids such as NS or LR"}]'::jsonb, '["d"]', 'Fluid loss from diarrhea (dehydration) causes hypovolemic shock, and IV fluids (NS, LR) are first-line. Packed RBCs are added only if the shock is hemorrhagic, which it is not here.', false),
  ('shock', 11, 'A client 4 hours after a colectomy has a drain filling rapidly with bright red blood, a BP of 80/50 mmHg, and a heart rate of 132 bpm. After 2 liters of LR, the BP is 82/50 mmHg and the bleeding continues. Which prescription should the nurse anticipate NEXT?', '[{"id": "a", "text": "Dobutamine infusion to improve pumping"}, {"id": "b", "text": "Packed RBC transfusion"}, {"id": "c", "text": "IV diuretic"}, {"id": "d", "text": "Atropine IV"}]'::jsonb, '["b"]', 'Hypovolemic shock is treated with IV fluids first, followed by blood products when the shock is hemorrhagic, as with this ongoing bleeding. Dobutamine and diuretics are cardiogenic shock medications.', false),
  ('shock', 12, 'An 80-kg client in septic shock has been receiving IV fluids and norepinephrine. The nurse reviews the data from the past 2 hours. Which finding requires IMMEDIATE follow-up?', '[{"id": "a", "text": "Urine output of 50 mL in 2 hours"}, {"id": "b", "text": "MAP of 67 mmHg on the last reading"}, {"id": "c", "text": "Heart rate of 98 bpm"}, {"id": "d", "text": "SpO2 of 95% on oxygen"}]'::jsonb, '["a"]', 'The target is ≥0.5 mL/kg/hr (≥30 mL/hr); 50 mL in 2 hours is 25 mL/hr, about 0.31 mL/kg/hr for 80 kg, which means kidney hypoperfusion and the provider must be notified. A MAP of 67 meets MAP ≥65 mmHg, the HR is within 60–100 bpm, and SpO2 95% meets ≥94%.', false),
  ('shock', 13, 'A nurse is screening newly admitted clients for the type of shock caused by loss of blood or fluids, leaving not enough blood for circulation. Which client conditions place the client at risk for this type of shock? Select all that apply.', '[{"id": "a", "text": "Acute MI with heart failure"}, {"id": "b", "text": "Burns covering the chest and legs"}, {"id": "c", "text": "Hemorrhage after surgery"}, {"id": "d", "text": "Tension pneumothorax after trauma"}, {"id": "e", "text": "Dehydration from vomiting"}]'::jsonb, '["b", "c", "e"]', 'Hypovolemic shock (loss of blood or fluids) is caused by hemorrhage, dehydration, and burns, so those three clients are at risk. An MI with heart failure causes cardiogenic shock, and a tension pneumothorax causes obstructive shock from a physical blockage.', true),
  ('shock', 14, 'A client in septic shock has received IV antibiotics and fluids and is now on a norepinephrine infusion titrated per protocol. Which finding BEST indicates the norepinephrine is achieving its intended effect?', '[{"id": "a", "text": "Heart rate of 104 bpm"}, {"id": "b", "text": "Urine output of 22 mL/hr"}, {"id": "c", "text": "MAP of 66 mmHg"}, {"id": "d", "text": "Lactate of 3.4 mmol/L"}]'::jsonb, '["c"]', 'Vasopressors are given to support BP, and the BP target is MAP ≥65 mmHg, so a MAP of 66 shows the intended effect. The HR is above 60–100 bpm, urine output is below ≥30 mL/hr, and lactate is above <2 mmol/L, so none of these show improvement.', false),
  ('shock', 15, 'A client in hypovolemic shock is receiving IV fluids through two large-bore lines. The client is alert, but the SpO2 has fallen to 90% on 2 L/min by nasal cannula and the respiratory rate is 26/min. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Increase the IV fluid infusion rate now"}, {"id": "b", "text": "Draw a serum lactate level now"}, {"id": "c", "text": "Place the client in Trendelenburg"}, {"id": "d", "text": "Apply 100% O₂ by non-rebreather mask"}]'::jsonb, '["d"]', 'The SpO2 target is ≥94%; when it is low the nurse increases O₂ delivery, providing 100% O₂ via non-rebreather mask (Breathing comes before Circulation in ABCS). Increasing fluids treats circulation, which comes after breathing.', false),
  ('shock', 16, 'A client who developed hives, wheezing, and a BP of 78/44 mmHg after an IV contrast injection has just received the FIRST-line medication. Which additional medications should the nurse anticipate to reverse the allergic reaction? Select all that apply.', '[{"id": "a", "text": "Steroids"}, {"id": "b", "text": "IV fluids"}, {"id": "c", "text": "Atropine"}, {"id": "d", "text": "Diphenhydramine"}, {"id": "e", "text": "Dobutamine"}]'::jsonb, '["a", "b", "d"]', 'Anaphylactic shock is treated with epinephrine IM first, followed by diphenhydramine, steroids, and IV fluids to reverse the allergic reaction. Atropine is for low HR in neurogenic shock, and dobutamine increases contractility in cardiogenic shock.', true),
  ('shock', 17, 'A client in septic shock who was alert 1 hour ago now opens the eyes only to a loud voice, has snoring respirations, and has a respiratory rate of 9/min. The MAP is 62 mmHg. Which action is the nurse''s PRIORITY?', '[{"id": "a", "text": "Increase the norepinephrine infusion to raise the MAP"}, {"id": "b", "text": "Draw a repeat lactate to evaluate perfusion"}, {"id": "c", "text": "Ensure the airway is open; prepare for intubation"}, {"id": "d", "text": "Notify the provider that the MAP is 62 mmHg"}]'::jsonb, '["c"]', 'Decreased LOC means the nurse prioritizes the airway, and in ABCS the airway comes first, with intubation if the client cannot breathe properly. The low MAP needs treatment, but airway takes priority over circulation.', false),
  ('shock', 18, 'The spouse of a client in anaphylactic shock after a peanut exposure asks, "Why is the blood pressure so low when no blood was lost?" Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"The heart cannot pump effectively after the allergic reaction.\""}, {"id": "b", "text": "\"The blood vessels dilate, so blood pools instead of circulating.\""}, {"id": "c", "text": "\"Fluid is lost from the vessels, leaving too little to circulate.\""}, {"id": "d", "text": "\"A physical blockage is preventing the blood from flowing forward.\""}]'::jsonb, '["b"]', 'Anaphylactic shock is distributive: blood vessels dilate, blood pools rather than circulating, and BP drops. A heart that cannot pump describes cardiogenic shock, and loss of fluid describes hypovolemic shock.', false),
  ('shock', 19, 'A client with an acute T2 spinal cord injury from a fall has a BP of 78/44 mmHg, a heart rate of 44 bpm, and no signs of bleeding. Which prescriptions should the nurse anticipate to stabilize the BP and heart rate? Select all that apply.', '[{"id": "a", "text": "Dobutamine"}, {"id": "b", "text": "Dopamine"}, {"id": "c", "text": "IV fluids"}, {"id": "d", "text": "Atropine"}, {"id": "e", "text": "Norepinephrine"}]'::jsonb, '["b", "c", "d", "e"]', 'Neurogenic shock is treated to stabilize BP with dopamine, norepinephrine, and IV fluids, plus atropine for the low HR. Dobutamine increases contractility and is a cardiogenic shock medication, not a neurogenic shock treatment.', true),
  ('shock', 20, 'A client in cardiogenic shock after an MI has a BP of 80/52 mmHg and crackles. The nurse observes the UAP providing care. Which action by the UAP requires IMMEDIATE intervention?', '[{"id": "a", "text": "Emptying the urine bag and recording the hourly output"}, {"id": "b", "text": "Raising the foot of the bed so legs are above the heart"}, {"id": "c", "text": "Reporting that the client''s hands feel cool to the touch"}, {"id": "d", "text": "Repositioning the non-rebreather mask after it slips"}]'::jsonb, '["b"]', 'Trendelenburg position (legs elevated above heart) should be avoided in cardiogenic shock. Recording urine output, reporting cool skin, and keeping the non-rebreather in place all support shock monitoring.', false),
  ('shock', 21, 'The nurse reviews the flow sheet of a client who is 12 hours postoperative and was stable on arrival to the unit. Which change in the data MOST likely represents the earliest sign of developing shock?', '[{"id": "a", "text": "Radial pulses becoming weak or absent"}, {"id": "b", "text": "Heart rate rising from 82 to 114 bpm"}, {"id": "c", "text": "Respirations becoming slow and shallow"}, {"id": "d", "text": "Responding only to painful stimuli"}]'::jsonb, '["b"]', 'Shock starts with a high heart rate as the body compensates, then progresses to low BP and organ failure if untreated. Weak or absent pulses, slow shallow breathing, and decreasing consciousness are late, decompensated signs.', false),
  ('shock', 22, 'A client admitted with pneumonia has a BP of 94/58 mmHg and a heart rate of 108 bpm. The serum lactate is 3.6 mmol/L. Which interpretation of the lactate result is MOST accurate?', '[{"id": "a", "text": "It is within the expected range for a client with infection"}, {"id": "b", "text": "It reflects kidney hypoperfusion caused by the low blood pressure"}, {"id": "c", "text": "It shows the heart cannot pump effectively"}, {"id": "d", "text": "It indicates tissue hypoperfusion and is a sepsis indicator"}]'::jsonb, '["d"]', 'The lactate target is <2 mmol/L; an elevated lactate means tissue hypoperfusion and is a sepsis indicator. Kidney hypoperfusion is identified by low urine output, not by lactate.', false),
  ('shock', 23, 'A 60-kg client in septic shock is being monitored after a fluid bolus. The nurse reviews the latest data. Which findings require follow-up with the provider? Select all that apply.', '[{"id": "a", "text": "MAP of 63 mmHg"}, {"id": "b", "text": "SpO2 of 95% on 4 L/min"}, {"id": "c", "text": "Lactate of 3.1 mmol/L"}, {"id": "d", "text": "Urine output of 25 mL/hr"}, {"id": "e", "text": "Heart rate of 92 bpm"}]'::jsonb, '["a", "c", "d"]', 'A MAP of 63 is below the MAP ≥65 mmHg target (IV fluids, vasopressors; notify provider). Lactate of 3.1 is above <2 mmol/L and signals tissue hypoperfusion. Urine output of 25 mL/hr is below ≥30 mL/hr and below 0.5 mL/kg/hr for 60 kg (about 0.42), meaning kidney hypoperfusion. SpO2 95% meets the ≥94% target and a HR of 92 is within 60–100 bpm.', true),
  ('shock', 24, 'A client brought in after a motorcycle crash has an expanding thigh hematoma, a heart rate of 128 bpm, a BP of 88/56 mmHg, and cool, clammy skin. Breath sounds are equal and there is no spinal injury. Which shock type and treatment should the nurse anticipate FIRST?', '[{"id": "a", "text": "Cardiogenic; dobutamine to improve pumping"}, {"id": "b", "text": "Distributive; vasopressors to support BP"}, {"id": "c", "text": "Hypovolemic; IV fluids, then blood products"}, {"id": "d", "text": "Obstructive; chest tube to remove the blockage"}]'::jsonb, '["c"]', 'Bleeding into the thigh is loss of blood, so this is hypovolemic shock, treated with IV fluids and then blood products because it is hemorrhagic. Vasopressors are for distributive shock, which involves vessel dilation, not blood loss.', false),
  ('shock', 25, 'A client 3 days after a total knee replacement suddenly develops dyspnea, a BP of 80/50 mmHg, and a heart rate of 130 bpm. A large pulmonary embolism (PE) is confirmed. Along with O₂, which prescription MOST directly treats the cause of this client''s shock?', '[{"id": "a", "text": "Thrombolytics"}, {"id": "b", "text": "Dobutamine"}, {"id": "c", "text": "Chest tube insertion"}, {"id": "d", "text": "Diphenhydramine"}]'::jsonb, '["a"]', 'A PE causes obstructive shock, and first-line treatment is anticoagulants or thrombolytics with O₂. A chest tube removes the obstruction of a tension pneumothorax, not a PE.', false),
  ('shock', 26, 'A 70-kg client in septic shock has received IV antibiotics, fluids, and norepinephrine for 6 hours. Which findings indicate that perfusion is improving? Select all that apply.', '[{"id": "a", "text": "Heart rate of 112 bpm"}, {"id": "b", "text": "MAP of 70 mmHg"}, {"id": "c", "text": "Urine output of 42 mL/hr"}, {"id": "d", "text": "Skin warm and pink"}, {"id": "e", "text": "Alert and oriented"}]'::jsonb, '["b", "c", "d", "e"]', 'A MAP of 70 meets MAP ≥65 mmHg; urine output of 42 mL/hr is ≥30 mL/hr and about 0.6 mL/kg/hr for 70 kg; warm, pink skin and being alert and oriented are the normal targets. A HR of 112 is above the 60–100 bpm target, so the cause still needs treatment.', true),
  ('shock', 27, 'The nurse is caring for four clients who are being treated for shock. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Client whose heart rate is 100 bpm after a fluid bolus"}, {"id": "b", "text": "Client whose SpO2 is 93% on a non-rebreather mask"}, {"id": "c", "text": "Client whose MAP is 65 mmHg on norepinephrine"}, {"id": "d", "text": "Client whose urine output is 32 mL/hr and who weighs 60 kg"}]'::jsonb, '["b"]', 'An SpO2 below ≥94% while already on a non-rebreather means the nurse must increase O₂ delivery and prepare for intubation. A HR of 100 is within 60–100 bpm, a MAP of 65 meets MAP ≥65 mmHg, and 32 mL/hr for 60 kg is about 0.53 mL/kg/hr, which meets the target.', false),
  ('shock', 28, 'A client with septic shock received IV antibiotics within the first hour and has completed the prescribed IV fluid boluses. The MAP remains 58 mmHg and the skin is cool. Which prescription should the nurse anticipate NEXT?', '[{"id": "a", "text": "Dobutamine infusion to improve contractility"}, {"id": "b", "text": "Norepinephrine infusion"}, {"id": "c", "text": "IV diuretic"}, {"id": "d", "text": "Epinephrine IM"}]'::jsonb, '["b"]', 'Septic shock is treated with IV antibiotics first, then fluids, then vasopressors such as norepinephrine when BP stays low. Dobutamine is first-line for cardiogenic shock, and epinephrine IM is first for anaphylaxis.', false),
  ('shock', 29, 'A client who collapsed after working outdoors in the heat has severe dehydration, a heart rate of 130 bpm, and a BP of 84/50 mmHg with no bleeding. Which prescriptions are the FIRST-line treatment for this client''s shock? Select all that apply.', '[{"id": "a", "text": "Packed RBCs"}, {"id": "b", "text": "IV dobutamine"}, {"id": "c", "text": "IV fluids with NS"}, {"id": "d", "text": "IV diuretics"}, {"id": "e", "text": "IV fluids with LR"}]'::jsonb, '["c", "e"]', 'Dehydration causes hypovolemic shock, and IV fluids (NS, LR) are first-line. Packed RBCs are added only if the shock is hemorrhagic; dobutamine and diuretics are cardiogenic shock medications and diuretics would worsen fluid loss.', true),
  ('shock', 30, 'A client 6 hours after cardiac surgery has a BP of 76/54 mmHg, a heart rate of 128 bpm, and an SpO2 of 92%. Cardiac tamponade is identified. Which statement BEST describes this client''s shock and its treatment?', '[{"id": "a", "text": "Cardiogenic; dobutamine to increase contractility"}, {"id": "b", "text": "Obstructive; surgery to remove the obstruction"}, {"id": "c", "text": "Hypovolemic; IV fluids and blood transfusion"}, {"id": "d", "text": "Distributive; vasopressors to support the BP"}]'::jsonb, '["b"]', 'Cardiac tamponade is a physical blockage that prevents blood flow, which is obstructive shock, treated by removing the obstruction with surgery. Although it follows cardiac surgery, the problem is not the heart failing to pump, so dobutamine does not remove the cause.', false),
  ('shock', 31, 'The nurse reviews the latest data for four ICU clients. Which client''s data requires IMMEDIATE follow-up?', '[{"id": "a", "text": "Septic shock; lactate 2.4 → 4.8 mmol/L, MAP 60 mmHg"}, {"id": "b", "text": "Cardiogenic shock on dobutamine; heart rate 98 bpm"}, {"id": "c", "text": "Hypovolemic shock after fluids; urine output 0.6 mL/kg/hr"}, {"id": "d", "text": "Neurogenic shock on atropine; heart rate 64 bpm"}]'::jsonb, '["a"]', 'A rising lactate (target <2 mmol/L) shows worsening tissue hypoperfusion, and the MAP of 60 is below MAP ≥65 mmHg. The other clients have a HR within 60–100 bpm or urine output above ≥0.5 mL/kg/hr.', false),
  ('shock', 32, 'A client with extensive burns has a heart rate of 126 bpm, a BP of 84/50 mmHg, and a urine output of 15 mL/hr. Which prescription requires follow-up with the provider before the nurse implements it?', '[{"id": "a", "text": "IV fluids with LR"}, {"id": "b", "text": "100% O₂ via non-rebreather mask"}, {"id": "c", "text": "Hourly urine output monitoring with a catheter"}, {"id": "d", "text": "IV diuretic to increase urine output"}]'::jsonb, '["d"]', 'Burns cause hypovolemic shock, and low urine output means kidney hypoperfusion, which is treated with IV fluids (NS, LR) rather than a diuretic; diuretics are a cardiogenic shock medication. LR, oxygen, and hourly output monitoring are appropriate.', false),
  ('shock', 33, 'A client with a gunshot wound to the abdomen arrives with gurgling respirations, a BP of 70/40 mmHg, and active bleeding. Using the ABCS approach, which interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Ensure the airway is open"}, {"id": "b", "text": "Dobutamine to increase contractility"}, {"id": "c", "text": "100% O₂ via non-rebreather mask"}, {"id": "d", "text": "Blood transfusion"}, {"id": "e", "text": "Treat the underlying bleeding"}]'::jsonb, '["a", "c", "d", "e"]', 'ABCS: A — ensure the airway is open; B — 100% O₂ via non-rebreather mask; C — blood transfusion for hemorrhagic shock; S — stop the cause by treating the bleeding. Dobutamine increases contractility for cardiogenic shock and does not address blood loss.', true),
  ('shock', 34, 'A client receiving an IV antibiotic suddenly develops hives, wheezing, and a BP of 78/40 mmHg. The nurse has stopped the infusion and the airway is open. Which medication should the nurse administer FIRST?', '[{"id": "a", "text": "Diphenhydramine IV"}, {"id": "b", "text": "Steroids IV"}, {"id": "c", "text": "IV fluid bolus"}, {"id": "d", "text": "Epinephrine IM"}]'::jsonb, '["d"]', 'These findings indicate anaphylactic shock, and epinephrine IM is given first. Diphenhydramine, steroids, and IV fluids are also part of treatment but follow epinephrine.', false),
  ('shock', 35, 'A 70-kg client being treated for hypovolemic shock has received 2 liters of IV fluids. Current data: MAP 70 mmHg, urine output 36 mL/hr, SpO2 96% on room air, and heart rate 104 bpm. Which finding MOST clearly shows that the cause still needs treatment?', '[{"id": "a", "text": "MAP of 70 mmHg"}, {"id": "b", "text": "Urine output of 36 mL/hr"}, {"id": "c", "text": "Heart rate of 104 bpm"}, {"id": "d", "text": "SpO2 of 96% on room air"}]'::jsonb, '["c"]', 'The HR target is 60–100 bpm, so 104 bpm calls for treating the cause (fluids, pain, infection). MAP 70 meets MAP ≥65 mmHg, 36 mL/hr is ≥30 mL/hr and about 0.51 mL/kg/hr for 70 kg, and SpO2 96% meets ≥94%.', false),
  ('shock', 36, 'A 64-kg client is admitted with septic shock from pneumonia, with a BP of 82/46 mmHg and an elevated lactate. Which prescriptions should the nurse expect to be part of this client''s treatment? Select all that apply.', '[{"id": "a", "text": "Epinephrine IM"}, {"id": "b", "text": "IV antibiotics"}, {"id": "c", "text": "IV fluids"}, {"id": "d", "text": "Dobutamine"}, {"id": "e", "text": "Norepinephrine"}]'::jsonb, '["b", "c", "e"]', 'Septic shock is treated with IV antibiotics first, plus IV fluids and vasopressors such as norepinephrine to support BP. Epinephrine IM is first for anaphylactic shock, and dobutamine increases contractility in cardiogenic shock.', true),
  ('shock', 37, 'A client with a C6 spinal cord injury has a BP of 82/50 mmHg and a heart rate of 48 bpm. There is no external bleeding and the abdomen is soft. Which explanation of this client''s hypotension is MOST accurate?', '[{"id": "a", "text": "Distributive shock; vessels dilate and blood pools"}, {"id": "b", "text": "Hypovolemic shock; blood is lost from circulation"}, {"id": "c", "text": "Cardiogenic shock; the heart cannot pump effectively"}, {"id": "d", "text": "Obstructive shock; a blockage prevents blood flow"}]'::jsonb, '["a"]', 'Neurogenic shock from a spinal cord injury is a distributive shock in which blood vessels dilate and blood pools. There is no blood loss to suggest hypovolemic shock.', false),
  ('shock', 38, 'Four clients on a surgical unit are showing signs of shock. Which client should the nurse recognize as being in the MOST advanced stage?', '[{"id": "a", "text": "Weak peripheral pulses; slow, shallow breathing"}, {"id": "b", "text": "Heart rate of 118 bpm with restlessness and anxiety"}, {"id": "c", "text": "Heart rate of 112 bpm with cool, clammy skin"}, {"id": "d", "text": "Heart rate of 120 bpm and a BP of 100/64 mmHg"}]'::jsonb, '["a"]', 'Weak or absent peripheral pulses and slow, shallow breathing are late signs of decompensated shock, when organs are failing. Tachycardia, restlessness and anxiety, and cool clammy skin are early, compensated signs.', false),
  ('shock', 39, 'A client 2 days after a total hip replacement suddenly becomes short of breath with a BP of 80/50 mmHg, and a large pulmonary embolism (PE) is confirmed. Which treatments should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "O₂ therapy"}, {"id": "b", "text": "Chest tube insertion"}, {"id": "c", "text": "Anticoagulants"}, {"id": "d", "text": "Dobutamine"}, {"id": "e", "text": "Thrombolytics"}]'::jsonb, '["a", "c", "e"]', 'A PE causes obstructive shock, and first-line treatment is anticoagulants or thrombolytics with O₂. A chest tube removes the obstruction of a tension pneumothorax, and dobutamine increases contractility in cardiogenic shock.', true),
  ('shock', 40, 'A client with a GI hemorrhage has a BP of 82/48 mmHg and a heart rate of 134 bpm, and two large-bore IVs are in place. Which prescription is the nurse MOST likely to question?', '[{"id": "a", "text": "NS infused through both IV lines"}, {"id": "b", "text": "Packed RBC transfusion"}, {"id": "c", "text": "Norepinephrine before any IV fluids"}, {"id": "d", "text": "Continuous BP and MAP monitoring at the bedside"}]'::jsonb, '["c"]', 'In hypovolemic shock IV fluids are first-line, with packed RBCs for hemorrhage; vasopressors are the circulation treatment for distributive shock. Packed RBCs are appropriate because the shock is hemorrhagic.', false),
  ('shock', 41, 'Two clients each have a BP of 82/50 mmHg and a heart rate of 120 bpm. One is bleeding after a liver laceration; the other is 1 day post-MI with crackles. Which plan BEST matches each client''s shock?', '[{"id": "a", "text": "Bleeding client: dobutamine; post-MI client: IV fluids"}, {"id": "b", "text": "Both clients: large IV fluid boluses until the BP rises"}, {"id": "c", "text": "Bleeding client: IV fluids; post-MI client: dobutamine"}, {"id": "d", "text": "Both clients: vasopressors before giving any IV fluids"}]'::jsonb, '["c"]', 'Bleeding causes hypovolemic shock, treated with IV fluids, while the post-MI client has cardiogenic shock, treated with dobutamine and not excess fluids. Vasopressors are the circulation treatment for distributive shock.', false),
  ('shock', 42, 'A client with severe aortic valve disease has a BP of 80/54 mmHg, a heart rate of 116 bpm, cool skin, and crackles. Which medication is the nurse MOST likely to prepare as first-line treatment?', '[{"id": "a", "text": "Dobutamine"}, {"id": "b", "text": "Epinephrine IM"}, {"id": "c", "text": "Atropine"}, {"id": "d", "text": "Packed RBCs"}]'::jsonb, '["a"]', 'Valve disease is a cause of cardiogenic shock, and dobutamine (to increase contractility) is first-line. Epinephrine IM is first-line for anaphylaxis, and atropine treats low HR in neurogenic shock.', false),
  ('shock', 43, 'A preceptor reviews shock care with a new graduate nurse who is caring for a client in the ICU. Which statements by the new graduate nurse indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"For anaphylaxis I give diphenhydramine first, then epinephrine.\""}, {"id": "b", "text": "\"In cardiogenic shock, I avoid giving excess IV fluids.\""}, {"id": "c", "text": "\"Atropine is given in neurogenic shock to raise a low BP.\""}, {"id": "d", "text": "\"A lactate of 2.5 mmol/L means tissue perfusion is adequate.\""}, {"id": "e", "text": "\"For a tension pneumothorax, a chest tube removes the obstruction.\""}]'::jsonb, '["b", "e"]', 'Cardiogenic shock is treated with dobutamine, not excess fluids, and a tension pneumothorax (obstructive shock) is treated with a chest tube. Epinephrine IM is given first for anaphylaxis, atropine in neurogenic shock is for low HR, and a lactate above <2 mmol/L indicates tissue hypoperfusion.', true),
  ('shock', 44, 'A client in hypovolemic shock from a GI bleed has new confusion, and the urine output has dropped to 10 mL/hr. The client''s daughter asks why bleeding is affecting the kidneys and brain. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "The heart cannot pump effectively, so fluid backs up into organs"}, {"id": "b", "text": "Blood vessels dilate, so blood pools away from the organs"}, {"id": "c", "text": "A physical blockage prevents blood from reaching the kidneys and brain"}, {"id": "d", "text": "Decreased blood flow causes low oxygen, which leads to organ failure"}]'::jsonb, '["d"]', 'In all shock, decreased blood flow leads to low oxygen and then organ failure, seen here as kidney hypoperfusion and decreased LOC. Vessel dilation describes distributive shock, not shock from bleeding.', false),
  ('shock', 45, 'A client from a long-term care facility has an infected sacral wound, a BP of 80/46 mmHg, a heart rate of 124 bpm, and a lactate of 4.0 mmol/L. The airway is patent. Which sequence of treatment is BEST for this client?', '[{"id": "a", "text": "Vasopressors, then IV fluids, then IV antibiotics"}, {"id": "b", "text": "IV fluids, then vasopressors, then IV antibiotics later"}, {"id": "c", "text": "Dobutamine, then diuretics, then IV antibiotics"}, {"id": "d", "text": "IV antibiotics, then IV fluids, then vasopressors"}]'::jsonb, '["d"]', 'This is septic shock (infection, low BP, elevated lactate), and IV antibiotics come FIRST, followed by fluids and vasopressors. Dobutamine and diuretics are cardiogenic shock medications.', false),
  ('shock', 46, 'A client 2 days after a large anterior MI has a BP of 78/50 mmHg, a heart rate of 122 bpm, crackles, and cool skin. Which prescriptions should the nurse anticipate for this client''s shock? Select all that apply.', '[{"id": "a", "text": "Diuretics"}, {"id": "b", "text": "Atropine"}, {"id": "c", "text": "Dobutamine"}, {"id": "d", "text": "Epinephrine IM"}, {"id": "e", "text": "Dopamine"}]'::jsonb, '["a", "c", "e"]', 'Cardiogenic shock is treated by improving heart pumping with dobutamine (↑ contractility), dopamine (↑ BP and HR), and diuretics. Atropine is for low HR in neurogenic shock, and epinephrine IM is first for anaphylactic shock.', true),
  ('shock', 47, 'A client in hemorrhagic shock after a fall is unresponsive, with gurgling respirations, a BP of 72/40 mmHg, and active bleeding from a scalp laceration. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Ensure the airway is open"}, {"id": "b", "text": "Start the blood transfusion"}, {"id": "c", "text": "Increase the IV fluid rate"}, {"id": "d", "text": "Apply 100% O₂ via non-rebreather"}]'::jsonb, '["a"]', 'ABCS starts with the airway: ensure it is open, with intubation if the client cannot breathe properly. Oxygen (Breathing) and transfusion or fluids (Circulation) follow once the airway is secured.', false),
  ('shock', 48, 'A client admitted with a GI bleed has these findings: 0800 — HR 96 bpm, BP 118/76 mmHg, anxious; 1000 — HR 116 bpm, BP 108/70 mmHg, restless; 1200 — HR 128 bpm, BP 72/40 mmHg, weak peripheral pulses, difficult to arouse. Which interpretation of the 1200 data is MOST accurate?', '[{"id": "a", "text": "Decompensated shock, with organs now failing"}, {"id": "b", "text": "Compensated shock, with the body still adapting"}, {"id": "c", "text": "Expected response to restlessness and anxiety"}, {"id": "d", "text": "Improvement, since the high heart rate maintains flow"}]'::jsonb, '["a"]', 'Shock starts with a high heart rate (compensation) and progresses to low BP and organ failure if untreated; severe hypotension, weak pulses, and loss of consciousness are late, decompensated signs. The 0800–1000 data reflected compensation, but the 1200 data no longer do.', false),
  ('shock', 49, 'A nurse is reassessing a 65-kg client with septic shock 2 hours after admission. Which findings require IMMEDIATE action? Select all that apply.', '[{"id": "a", "text": "MAP of 70 mmHg"}, {"id": "b", "text": "Knees and legs cool, pale, and mottled"}, {"id": "c", "text": "Heart rate of 92 bpm"}, {"id": "d", "text": "Decreased LOC; no longer alert, oriented"}, {"id": "e", "text": "SpO2 of 96% on 2 L/min"}]'::jsonb, '["b", "d"]', 'Cool, pale, mottled skin means poor perfusion and requires immediate action, and decreased LOC requires the nurse to prioritize the airway and reassess. A MAP of 70 meets MAP ≥65 mmHg, a HR of 92 is within 60–100 bpm, and SpO2 96% meets ≥94%.', true),
  ('shock', 50, 'The nurse is caring for two hypotensive clients: one with septic shock from pneumonia and one with anaphylactic shock after a bee sting. Both have patent airways. Which plan reflects the correct FIRST medication for each client?', '[{"id": "a", "text": "IV antibiotics for septic shock; epinephrine IM for anaphylactic shock"}, {"id": "b", "text": "Norepinephrine for septic shock; diphenhydramine for anaphylactic shock"}, {"id": "c", "text": "IV fluids for septic shock; steroids for anaphylactic shock"}, {"id": "d", "text": "Dopamine for septic shock; IV fluids for anaphylactic shock"}]'::jsonb, '["a"]', 'Septic shock is treated with IV antibiotics first, and anaphylactic shock with epinephrine IM first. Norepinephrine, diphenhydramine, steroids, dopamine, and IV fluids are part of treatment but are not the first medication.', false),
  ('periop', 1, 'A client is about to sign the consent for a scheduled bowel resection. When the nurse asks the client to describe the procedure, the client says, ''I''m not really sure what they''re removing or what my other options were.'' Which action should the nurse take FIRST?', '[{"id": "a", "text": "Hold the signature and notify the surgeon"}, {"id": "b", "text": "Explain the procedure and its alternatives"}, {"id": "c", "text": "Witness the signature and clarify it later"}, {"id": "d", "text": "Give the prescribed midazolam to ease anxiety"}]'::jsonb, '["a"]', 'The surgeon explains the procedure, risks, benefits and alternatives; the nurse verifies understanding, so a client who does not understand needs the surgeon before signing. The nurse''s role is witness only, not to explain the procedure.', false),
  ('periop', 2, 'At 0700 a client scheduled for surgery under general anesthesia received prescribed lorazepam for anxiety. At 0730 the nurse completing the checklist finds that the surgical consent has not been signed. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Have the client sign now while the medication is still taking effect"}, {"id": "b", "text": "Notify the surgeon; do not obtain a signature"}, {"id": "c", "text": "Ask a family member to sign the consent for the client"}, {"id": "d", "text": "Witness the client''s signature and document the lorazepam time"}]'::jsonb, '["b"]', 'Informed consent must be obtained BEFORE giving sedatives, so a client who has received lorazepam cannot give valid consent and the surgeon must be notified. Having the client sign now still produces a signature obtained after sedation.', false),
  ('periop', 3, 'The nurse is completing the preoperative checklist for a client who will go to the operating room in 30 minutes for surgery under general anesthesia. Which actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Remove dentures and contacts"}, {"id": "b", "text": "Confirm NPO status"}, {"id": "c", "text": "Explain the risks of the surgery"}, {"id": "d", "text": "Ensure signed consent is in the chart"}, {"id": "e", "text": "Have the client void"}]'::jsonb, '["a", "b", "d", "e"]', 'Confirming NPO status is correct, removing dentures and contacts is correct, having the client void is correct, and ensuring the signed consent is in the chart is correct because all are items on the pre-op checklist. Explaining the risks is wrong because the surgeon explains the procedure; the nurse''s role is witness only.', true),
  ('periop', 4, 'A charge nurse observes a newly hired nurse preparing a client for a laparoscopic cholecystectomy. Which action by the newly hired nurse requires correction?', '[{"id": "a", "text": "Verifying that the client understands the surgery"}, {"id": "b", "text": "Witnessing the client''s signature on the consent"}, {"id": "c", "text": "Explaining risks and alternatives"}, {"id": "d", "text": "Confirming the signed consent is in the chart"}]'::jsonb, '["c"]', 'The surgeon explains the procedure, risks, benefits and alternatives; the nurse''s role is witness only, NOT to explain the procedure. Verifying understanding, witnessing the signature and ensuring the signed consent is in the chart are nursing responsibilities.', false),
  ('periop', 5, 'A client is scheduled for a hernia repair under general anesthesia at 0800 tomorrow. After the nurse reviews preoperative instructions, which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I won''t chew any gum on the morning of the surgery."}, {"id": "b", "text": "I won''t eat or drink anything for 6 to 8 hours before."}, {"id": "c", "text": "I won''t smoke a cigarette on the morning of surgery."}, {"id": "d", "text": "I can have a light breakfast at 0600."}]'::jsonb, '["d"]', 'General anesthesia requires NPO for 6–8 hours to prevent aspiration, so a meal 2 hours before surgery is unsafe. NPO status includes no food, water, gum or smoking, so the other statements are correct.', false),
  ('periop', 6, 'The evening before an open abdominal procedure, the nurse provides preoperative teaching to a client. Which topics should the nurse include? Select all that apply.', '[{"id": "a", "text": "Pain control options"}, {"id": "b", "text": "Incentive spirometry"}, {"id": "c", "text": "Bed rest for 48 hours"}, {"id": "d", "text": "Early ambulation"}, {"id": "e", "text": "Leg exercises"}]'::jsonb, '["a", "b", "d", "e"]', 'Incentive spirometry is correct, leg exercises are correct, early ambulation is correct and pain control options are correct because all four are listed pre-op education topics. Bed rest for 48 hours is wrong because early ambulation is taught to prevent DVT, PE, atelectasis and ileus.', true),
  ('periop', 7, 'A client scheduled for removal of a small skin lesion under local anesthesia this afternoon asks the nurse, ''Do I have to skip lunch the way I did for my knee surgery under general anesthesia?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "With local anesthesia, a light meal may be allowed."}, {"id": "b", "text": "You must stay NPO for 6 to 8 hours before any surgery."}, {"id": "c", "text": "You may eat, but you must not drink water before."}, {"id": "d", "text": "You may have a full meal because no sedation is used."}]'::jsonb, '["a"]', 'With local anesthesia a light meal may be allowed, whereas general anesthesia requires NPO for 6–8 hours. A full meal goes beyond the light meal the note allows.', false),
  ('periop', 8, 'One hour before a scheduled colectomy under general anesthesia, a client tells the nurse, ''I was so hungry that I ate a piece of toast about 2 hours ago.'' Which action should the nurse take FIRST?', '[{"id": "a", "text": "Document the intake and continue preparing"}, {"id": "b", "text": "Notify the surgeon of the toast"}, {"id": "c", "text": "Give the prescribed ondansetron early"}, {"id": "d", "text": "Remind the client about the NPO rules"}]'::jsonb, '["b"]', 'If a patient eats before surgery, the nurse notifies the surgeon because surgery may need to be delayed; NPO for 6–8 hours prevents aspiration. Ondansetron prevents nausea but does not make a recent meal safe.', false),
  ('periop', 9, 'A nurse is reviewing the purposes of a client''s preoperative medications with a nursing student. Which statements by the student indicate understanding? Select all that apply.', '[{"id": "a", "text": "Ondansetron is given to prevent nausea."}, {"id": "b", "text": "Atropine is given to reduce secretions."}, {"id": "c", "text": "Lorazepam is given to reduce secretions."}, {"id": "d", "text": "The antibiotic is given after the incision."}, {"id": "e", "text": "Midazolam is given to calm anxiety."}]'::jsonb, '["a", "b", "e"]', 'Midazolam is correct because sedatives calm anxiety; ondansetron is correct because antiemetics prevent nausea; atropine is correct because anticholinergics reduce secretions. Lorazepam is wrong because it is a sedative that calms anxiety, and the antibiotic statement is wrong because antibiotics are given before the incision.', true),
  ('periop', 10, 'During the preoperative interview, a client scheduled for a knee replacement tomorrow reports taking warfarin (Coumadin) every evening, including last night. Which laboratory result is MOST important for the nurse to verify?', '[{"id": "a", "text": "Electrolytes"}, {"id": "b", "text": "Pregnancy test"}, {"id": "c", "text": "PT/INR"}, {"id": "d", "text": "CBC"}]'::jsonb, '["c"]', 'Warfarin may delay surgery because of bleeding risk, so the PT/INR on the pre-op lab list is the priority result. Electrolytes and the CBC are also verified but do not reflect the warfarin effect.', false),
  ('periop', 11, 'A client awaiting a mastectomy has signed the consent and is crying, trembling, and saying, ''I''m so scared I can''t think straight.'' The surgical consent is complete. Which preoperative medication is the nurse MOST likely to administer?', '[{"id": "a", "text": "Ondansetron"}, {"id": "b", "text": "Atropine"}, {"id": "c", "text": "Antibiotic"}, {"id": "d", "text": "Midazolam"}]'::jsonb, '["d"]', 'Sedatives such as midazolam calm anxiety, and the consent is already signed, so a sedative may now be given. Ondansetron prevents nausea and atropine reduces secretions, neither of which treats anxiety.', false),
  ('periop', 12, 'A client receiving preoperative medications asks why atropine is being given when ''my heart is fine.'' Which explanation by the nurse is BEST?', '[{"id": "a", "text": "It reduces secretions before surgery."}, {"id": "b", "text": "It calms your anxiety before surgery."}, {"id": "c", "text": "It prevents nausea after the surgery."}, {"id": "d", "text": "It prevents infection at the incision."}]'::jsonb, '["a"]', 'Atropine is an anticholinergic given pre-op to reduce secretions. Calming anxiety is the purpose of sedatives such as midazolam, and preventing nausea is the purpose of ondansetron.', false),
  ('periop', 13, 'A PACU nurse is monitoring a client during the first hour after a bowel resection. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Nausea relieved after an antiemetic"}, {"id": "b", "text": "Noisy breathing (stridor)"}, {"id": "c", "text": "Urine output of 20 mL in the past hour"}, {"id": "d", "text": "Drains filling with bright red blood"}, {"id": "e", "text": "Drowsy but oriented when spoken to"}]'::jsonb, '["b", "c", "d"]', 'Stridor is correct because it signals possible airway obstruction; 20 mL/hr is correct because output below 30 mL/hr suggests possible kidney injury; drains filling with blood are correct because bleeding is monitored at the site, dressing and drains. Being drowsy but oriented is wrong because it reflects proper wake-up without confusion, and nausea relieved by an antiemetic is wrong because the ordered treatment has worked.', true),
  ('periop', 14, 'A prophylactic IV antibiotic is prescribed for a client having an open abdominal procedure. The client is now in the preoperative holding area. When should the nurse plan for the antibiotic to be given to BEST prevent infection?', '[{"id": "a", "text": "After arrival in the PACU"}, {"id": "b", "text": "Before the incision"}, {"id": "c", "text": "When the client tolerates oral fluids"}, {"id": "d", "text": "If a fever develops after surgery"}]'::jsonb, '["b"]', 'Pre-op antibiotics prevent infection and are given before the incision. Giving them in the PACU or after a fever develops is too late to prevent infection.', false),
  ('periop', 15, 'The nurse delegates final preoperative preparation to a UAP for a client who is going to the operating room in 20 minutes. Which action by the UAP requires correction?', '[{"id": "a", "text": "Bagging jewelry as valuables"}, {"id": "b", "text": "Removing contacts before surgery"}, {"id": "c", "text": "Leaving dentures in during surgery"}, {"id": "d", "text": "Having the patient void before transfer"}]'::jsonb, '["c"]', 'Dentures, jewelry, contacts and prosthetics are removed before surgery, so leaving dentures in requires correction. Having the client void empties the bladder before anesthesia and is correct.', false),
  ('periop', 16, 'A client on postoperative day 1 after a hip procedure is at high risk for a clot forming in the legs. Which interventions should the nurse include in the plan to prevent DVT? Select all that apply.', '[{"id": "a", "text": "Enoxaparin as prescribed"}, {"id": "b", "text": "Blood glucose control"}, {"id": "c", "text": "Bladder scan"}, {"id": "d", "text": "Early ambulation"}, {"id": "e", "text": "Sequential compression devices"}]'::jsonb, '["a", "d", "e"]', 'Early ambulation is correct, SCDs are correct and enoxaparin is correct because all three are listed for preventing DVT. Blood glucose control is wrong because it prevents surgical site infection, and a bladder scan is wrong because it addresses urinary retention.', true),
  ('periop', 17, 'A client arrives in the PACU after a thyroid procedure. Ten minutes later the nurse hears noisy, high-pitched breathing (stridor) on inspiration, and the client appears anxious. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Recheck vital signs in 15 minutes"}, {"id": "b", "text": "Give the prescribed IV pain medication"}, {"id": "c", "text": "Assess the dressing for bleeding"}, {"id": "d", "text": "Call for help immediately"}]'::jsonb, '["d"]', 'Noisy breathing (stridor) signals possible airway obstruction, and the airway is the top priority, so the nurse calls for help immediately. Waiting for the next 15-minute vital signs delays care of the airway.', false),
  ('periop', 18, 'A client arrived in the PACU after surgery. The nurse has obtained vital signs every 15 minutes four times, most recently at 1045, and all values are stable. At what time should the nurse plan to obtain the NEXT set of vital signs?', '[{"id": "a", "text": "1145"}, {"id": "b", "text": "1100"}, {"id": "c", "text": "1115"}, {"id": "d", "text": "1245"}]'::jsonb, '["a"]', 'Vital signs are taken every 15 minutes four times and then hourly, so the next set after 1045 is due at 1145. 1100 continues the 15-minute schedule after the four checks are complete.', false),
  ('periop', 19, 'A client with diabetes is having an open abdominal procedure. The nurse is planning care across the perioperative period to reduce the client''s risk of infection. Which interventions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Sequential compression devices"}, {"id": "b", "text": "Blood glucose control"}, {"id": "c", "text": "Sterile wound care"}, {"id": "d", "text": "Antibiotics before the incision"}, {"id": "e", "text": "Bladder scan post-op"}]'::jsonb, '["b", "c", "d"]', 'Antibiotics before the incision are correct because they prevent infection; blood glucose control is correct because it prevents surgical site infection; sterile wound care is correct because it prevents infection and dehiscence. SCDs are wrong because they prevent DVT, and a bladder scan is wrong because it addresses urinary retention.', true),
  ('periop', 20, 'Forty minutes after an open abdominal procedure, a client in the PACU is awake, has a patent airway with stable vital signs, and rates incisional pain 8/10. The client is NPO and has an IV line. Which pain management approach is BEST at this time?', '[{"id": "a", "text": "Oral pain medication with sips of water"}, {"id": "b", "text": "IV pain medication as prescribed"}, {"id": "c", "text": "Hold all pain medication until fully awake"}, {"id": "d", "text": "Wait until the client tolerates oral intake"}]'::jsonb, '["b"]', 'Immediate post-op pain is managed with IV medications first and oral medications later. Oral medication with sips is the later step, not the PACU approach for an NPO client.', false),
  ('periop', 21, 'A client on postoperative day 1 has PCA morphine. The client''s daughter says, ''Mom keeps falling asleep before she presses the button, so I press it for her to stay ahead of the pain.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Press it only when she is grimacing in her sleep."}, {"id": "b", "text": "It is safe because the pump limits each dose."}, {"id": "c", "text": "Only your mother should press the PCA button."}, {"id": "d", "text": "Press it once an hour while she is sleeping."}]'::jsonb, '["c"]', 'With PCA the patient self-administers preset IV doses, and family must NOT press the button. The preset dose does not make family-pressed doses safe, because opioids carry a risk of respiratory depression.', false),
  ('periop', 22, 'The nurse is reassessing a client 6 hours after abdominal surgery who has PCA morphine. Which finding requires IMMEDIATE follow-up?', '[{"id": "a", "text": "Pain rated 4/10 at rest"}, {"id": "b", "text": "Mild nausea after fluids"}, {"id": "c", "text": "BP 128/76, HR 84 bpm"}, {"id": "d", "text": "Respiratory rate 8/min"}]'::jsonb, '["d"]', 'Opioids carry a risk of respiratory depression, so a slow respiratory rate with difficulty arousing is a breathing problem needing immediate action. Mild nausea is managed by giving antiemetics as ordered.', false),
  ('periop', 23, 'A client on postoperative day 1 is taking shallow breaths and has diminished breath sounds at the bases. Which interventions should the nurse use to prevent atelectasis and pneumonia? Select all that apply.', '[{"id": "a", "text": "Enoxaparin as prescribed"}, {"id": "b", "text": "Sequential compression devices"}, {"id": "c", "text": "Bladder scan post-op"}, {"id": "d", "text": "Early ambulation"}, {"id": "e", "text": "Incentive spirometer"}]'::jsonb, '["d", "e"]', 'The incentive spirometer is correct because, with deep breathing, it prevents atelectasis and pneumonia; early ambulation is correct because it prevents atelectasis. SCDs and enoxaparin are wrong because they prevent DVT (and enoxaparin PE), and a bladder scan is wrong because it addresses urinary retention.', true),
  ('periop', 24, 'A client who had surgery 5 hours ago has hourly urine outputs of 45, 38, 28, and 24 mL. The client denies pain and the BP is stable. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Assess for dehydration or kidney injury"}, {"id": "b", "text": "Continue to monitor the hourly output"}, {"id": "c", "text": "Encourage the client to drink more fluids"}, {"id": "d", "text": "Notify the provider of urinary retention"}]'::jsonb, '["a"]', 'The last two hours are below the 30 mL/hr minimum, so the nurse assesses for dehydration or kidney injury. Continuing to monitor ignores output that has fallen below the minimum.', false),
  ('periop', 25, 'One hour after a nephrectomy, a client''s BP has dropped from 132/80 to 104/66 and the HR has risen from 78 to 102 bpm. The surgical dressing is dry and intact. Which assessment should the nurse perform NEXT?', '[{"id": "a", "text": "Assess bowel sounds for ileus"}, {"id": "b", "text": "Check the surgical site and drains"}, {"id": "c", "text": "Check pupil response and movement"}, {"id": "d", "text": "Ask about readiness for diet advancement"}]'::jsonb, '["b"]', 'Monitoring for bleeding includes the surgical site, dressing and drains, so a dry dressing does not rule out bleeding when BP falls and HR rises. Bowel sounds and diet advancement are GI assessments that do not explain the vital sign changes.', false),
  ('periop', 26, 'A nurse is preparing to witness the surgical consent for a client scheduled for a mastectomy later this morning. Which actions by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Obtain consent after midazolam"}, {"id": "b", "text": "Verify the client''s understanding"}, {"id": "c", "text": "Explain the benefits and alternatives"}, {"id": "d", "text": "Witness the client''s signature"}, {"id": "e", "text": "Obtain consent before sedatives"}]'::jsonb, '["b", "d", "e"]', 'Verifying understanding is correct and witnessing the signature is correct because those are the nurse''s consent roles; obtaining consent before sedatives is correct because it must be obtained BEFORE sedatives. Explaining benefits and alternatives is wrong because the surgeon explains them, and obtaining consent after midazolam is wrong because midazolam is a sedative.', true),
  ('periop', 27, 'Thirty minutes after arriving in the PACU, a client with a patent airway and stable vital signs reports nausea and retches twice. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Give the atropine as ordered"}, {"id": "b", "text": "Advance the diet to crackers"}, {"id": "c", "text": "Give antiemetics as ordered"}, {"id": "d", "text": "Give oral pain medication"}]'::jsonb, '["c"]', 'Nausea and vomiting in the PACU are treated by giving antiemetics as ordered, such as ondansetron. Atropine reduces secretions and does not prevent nausea.', false),
  ('periop', 28, 'A client with diabetes is on postoperative day 1 after a bowel resection, and the capillary blood glucose is 286 mg/dL. The provider prescribes insulin to tighten glucose control. The client asks why this matters after surgery. Which explanation is BEST?', '[{"id": "a", "text": "It helps prevent urinary retention after surgery."}, {"id": "b", "text": "It helps prevent DVT and PE in the legs."}, {"id": "c", "text": "It helps prevent atelectasis and pneumonia."}, {"id": "d", "text": "It helps prevent surgical site infection."}]'::jsonb, '["d"]', 'Blood glucose control is the listed intervention for preventing surgical site infection (SSI). DVT is prevented by early ambulation, SCDs and enoxaparin, and urinary retention is addressed with a bladder scan.', false),
  ('periop', 29, 'The son of a client on postoperative day 1 has been taught about his mother''s PCA morphine pump. Which statements by the son indicate understanding? Select all that apply.', '[{"id": "a", "text": "Only Mom should press the button."}, {"id": "b", "text": "The pump lets her pick any dose."}, {"id": "c", "text": "The pump gives preset IV doses."}, {"id": "d", "text": "I can press it while she is sleeping."}, {"id": "e", "text": "Opioids can slow her breathing."}]'::jsonb, '["a", "c", "e"]', 'Only the client pressing the button is correct because the patient self-administers and family must NOT press it; preset IV doses is correct because PCA delivers preset doses; slowed breathing is correct because opioids risk respiratory depression. Pressing it while she sleeps is wrong because family must not press the button, and picking any dose is wrong because the doses are preset.', true),
  ('periop', 30, 'A client on postoperative day 1 after a hip procedure asks why a daily enoxaparin injection is prescribed when the SCDs are already on. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "It is an anticoagulant that prevents DVT and PE."}, {"id": "b", "text": "It prevents surgical site infection at the incision."}, {"id": "c", "text": "It prevents atelectasis and pneumonia after surgery."}, {"id": "d", "text": "It prevents urinary retention after the catheter."}]'::jsonb, '["a"]', 'Enoxaparin is an anticoagulant that prevents DVT and PE, while SCDs prevent DVT. Atelectasis and pneumonia are prevented with the incentive spirometer and deep breathing.', false),
  ('periop', 31, 'A charge nurse observes a nurse caring for a client on postoperative day 2 after an abdominal procedure. Which action by the nurse requires correction?', '[{"id": "a", "text": "Encouraging early ambulation in the hallway"}, {"id": "b", "text": "Clean rather than sterile wound care"}, {"id": "c", "text": "Coaching use of the incentive spirometer"}, {"id": "d", "text": "Applying SCDs while the client is in bed"}]'::jsonb, '["b"]', 'Sterile wound care prevents infection and dehiscence, so a non-sterile technique requires correction. Early ambulation, the incentive spirometer and SCDs are listed preventive interventions.', false),
  ('periop', 32, 'On postoperative day 1 after a colectomy, a client has hypoactive bowel sounds and says, ''I''d rather stay in bed until my bowels wake up.'' Which explanation by the nurse is BEST?', '[{"id": "a", "text": "Bed rest is best until bowel sounds return to normal levels."}, {"id": "b", "text": "Walking is needed mainly to prevent surgical site infection."}, {"id": "c", "text": "Early ambulation helps prevent ileus and DVT."}, {"id": "d", "text": "SCDs replace the need for walking until the bowels recover."}]'::jsonb, '["c"]', 'Early ambulation prevents DVT, PE, atelectasis and ileus, so walking helps the bowels recover. SCDs prevent DVT only and do not replace ambulation.', false),
  ('periop', 33, 'On the morning of surgery under general anesthesia scheduled for 1000, the nurse asks a client about NPO status at 0700. Which client statements require follow-up? Select all that apply.', '[{"id": "a", "text": "I voided before I came."}, {"id": "b", "text": "I had water at 0630."}, {"id": "c", "text": "I was smoking at 0600."}, {"id": "d", "text": "I had gum in the car."}, {"id": "e", "text": "My last meal was at midnight."}]'::jsonb, '["b", "c", "d"]', 'Gum is correct, smoking is correct and water is correct because confirmed NPO status means no food, water, gum or smoking. Emptying the bladder is wrong because voiding before anesthesia is part of the checklist, and a meal at midnight is wrong because it is 10 hours before a 1000 surgery, beyond the 6–8 hour NPO period.', true),
  ('periop', 34, 'A client who is NPO for surgery under general anesthesia asks, ''Why do I need an IV line if I can''t have anything and I''m not sick?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "It is only needed if a blood transfusion is required."}, {"id": "b", "text": "It is used to check your PT/INR before surgery."}, {"id": "c", "text": "It is placed after surgery to give oral medications."}, {"id": "d", "text": "It is for hydration and medication administration."}]'::jsonb, '["d"]', 'Pre-op IV access is for hydration and medication administration, which matters for a client who is NPO. It is not limited to transfusion.', false),
  ('periop', 35, 'A PACU nurse is caring for four clients who arrived within the past hour. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Patient with stridor after anesthesia"}, {"id": "b", "text": "Patient with urine output of 22 mL in 1 hour"}, {"id": "c", "text": "Patient whose son keeps pressing the PCA button"}, {"id": "d", "text": "Patient who is confused while waking up"}]'::jsonb, '["a"]', 'The airway is the top priority in the PACU, and stridor signals possible airway obstruction requiring a call for help immediately. Low urine output, a family member pressing the PCA button and confusion on wake-up all need follow-up, but they come after a threatened airway.', false),
  ('periop', 36, 'Two hours after surgery, a client''s BP is trending down. The nurse is collecting data to evaluate the client''s circulation. Which data should the nurse collect? Select all that apply.', '[{"id": "a", "text": "BP"}, {"id": "b", "text": "Skin color"}, {"id": "c", "text": "Pupil response"}, {"id": "d", "text": "HR"}, {"id": "e", "text": "Temperature"}]'::jsonb, '["a", "b", "d", "e"]', 'Skin color is correct, heart rate is correct, temperature is correct and blood pressure is correct because all four are listed circulation assessments. Pupil response is wrong because it belongs to the neurological assessment with LOC and movement.', true),
  ('periop', 37, 'A client on postoperative day 1 has SCDs on both legs and asks the nurse to remove them because ''they''re annoying and I''m already getting the incentive spirometer.'' Which explanation by the nurse is BEST?', '[{"id": "a", "text": "SCDs help prevent atelectasis."}, {"id": "b", "text": "SCDs help prevent DVT in your legs."}, {"id": "c", "text": "SCDs help prevent urinary retention."}, {"id": "d", "text": "SCDs help prevent wound dehiscence."}]'::jsonb, '["b"]', 'Sequential compression devices (SCDs) prevent DVT, while the incentive spirometer prevents atelectasis and pneumonia, so one does not replace the other. Dehiscence is prevented with sterile wound care.', false),
  ('periop', 38, 'A client scheduled for surgery under general anesthesia has completed the checklist, and the transport team has arrived. The client last voided 4 hours ago. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Plan a bladder scan after surgery"}, {"id": "b", "text": "Insert a straight catheter in the OR"}, {"id": "c", "text": "Have the patient void before anesthesia"}, {"id": "d", "text": "Send the client and note the last void"}]'::jsonb, '["c"]', 'The pre-op checklist includes having the patient void to empty the bladder before anesthesia. A bladder scan is a post-op measure for urinary retention, not a substitute for voiding before surgery.', false),
  ('periop', 39, 'A client on postoperative day 1 after a colectomy asks for a full breakfast. Which data should the nurse assess before the diet is advanced? Select all that apply.', '[{"id": "a", "text": "Pupil response"}, {"id": "b", "text": "PT/INR result"}, {"id": "c", "text": "Nausea"}, {"id": "d", "text": "Vomiting"}, {"id": "e", "text": "Bowel sounds"}]'::jsonb, '["c", "d", "e"]', 'Nausea is correct, bowel sounds are correct and vomiting is correct because they are the listed GI function assessments monitored with diet advancement. The PT/INR is wrong because it is a pre-op lab checked for bleeding risk, and pupil response is wrong because it is a neurological assessment.', true),
  ('periop', 40, 'A nurse is caring for one client the evening before surgery and another client in the PACU. Which statement by the nurse BEST describes the focus of care for these two phases?', '[{"id": "a", "text": "Pre-op: manage complications. Post-op: prevent new ones."}, {"id": "b", "text": "Pre-op: monitor complications. Post-op: treat the pain alone."}, {"id": "c", "text": "Pre-op and post-op: focus mainly on patient teaching."}, {"id": "d", "text": "Pre-op: prevent complications. Post-op: monitor and manage."}]'::jsonb, '["d"]', 'Pre-op care focuses on preventing complications, and post-op care focuses on monitoring and managing complications. Reversing the two phases misstates the principle.', false),
  ('periop', 41, 'A client on postoperative day 1 who is receiving IV opioids asks for another dose for pain rated 6/10. The client is drowsy. Which assessment is MOST important before the nurse gives the dose?', '[{"id": "a", "text": "Respiratory rate and O₂ levels"}, {"id": "b", "text": "Bowel sounds and diet tolerance"}, {"id": "c", "text": "Urine output for the past hour"}, {"id": "d", "text": "Dressing and surgical site drainage"}]'::jsonb, '["a"]', 'Opioids carry a risk of respiratory depression, so breathing and O₂ levels are checked before another dose in a drowsy client. Bowel sounds and diet tolerance are GI assessments that do not reflect opioid safety.', false),
  ('periop', 42, 'A client in the PACU after general anesthesia has gurgling respirations, secretions pooling in the mouth, and an SpO₂ that has dropped from 97% to 91%. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Recheck the BP and HR"}, {"id": "b", "text": "Suction the airway"}, {"id": "c", "text": "Give an antiemetic"}, {"id": "d", "text": "Assess the drains"}]'::jsonb, '["b"]', 'Airway is the top priority after anesthesia, and suction is used if needed to keep breathing clear. Rechecking BP and HR or giving an antiemetic does not clear the airway.', false),
  ('periop', 43, 'A client has just arrived in the PACU after a laparotomy. Which actions should the nurse include in care during the 1–2 hours after arrival? Select all that apply.', '[{"id": "a", "text": "Oral pain medication before IV medication"}, {"id": "b", "text": "Monitor confusion as the client wakes"}, {"id": "c", "text": "Check surgical site, dressing, and drains"}, {"id": "d", "text": "Give antiemetics for N/V as ordered"}, {"id": "e", "text": "Vital signs every 15 min × 4, then hourly"}]'::jsonb, '["b", "c", "d", "e"]', 'Vital signs every 15 minutes four times then hourly is correct; checking the surgical site, dressing and drains is correct because it monitors bleeding; monitoring confusion is correct because the neuro assessment ensures proper wake-up; antiemetics for N/V are correct as ordered. Oral before IV pain medication is wrong because IV meds are given first, then oral later.', true),
  ('periop', 44, 'A client with a history of severe nausea after previous surgeries is scheduled for a laparoscopic procedure. Which preoperative medication is the nurse MOST likely to administer for this concern?', '[{"id": "a", "text": "Lorazepam"}, {"id": "b", "text": "Atropine"}, {"id": "c", "text": "Ondansetron"}, {"id": "d", "text": "Midazolam"}]'::jsonb, '["c"]', 'Antiemetics such as ondansetron are given pre-op to prevent nausea. Lorazepam and midazolam are sedatives that calm anxiety, and atropine reduces secretions.', false),
  ('periop', 45, 'A client is in the PACU 30 minutes after general anesthesia. The airway is patent and vital signs every 15 minutes are stable. Which assessment should the nurse perform NEXT?', '[{"id": "a", "text": "Readiness for diet advancement"}, {"id": "b", "text": "Change of the surgical dressing"}, {"id": "c", "text": "Readiness to switch to oral pain medication"}, {"id": "d", "text": "LOC and confusion during wake-up"}]'::jsonb, '["d"]', 'After airway and vital signs, the PACU nurse completes the neuro assessment to ensure proper wake-up from anesthesia and monitor confusion. Oral pain medication and diet advancement come later.', false),
  ('periop', 46, 'The nurse reviews hourly urine output for a client who is 1 day post-op. Which hourly totals require follow-up? Select all that apply.', '[{"id": "a", "text": "60 mL"}, {"id": "b", "text": "45 mL"}, {"id": "c", "text": "25 mL"}, {"id": "d", "text": "30 mL"}, {"id": "e", "text": "18 mL"}]'::jsonb, '["c", "e"]', '25 mL is correct and 18 mL is correct because both are below the 30 mL/hr minimum, which suggests possible kidney injury. 30 mL is wrong because it meets the minimum, and 45 mL and 60 mL are wrong because they exceed it.', true),
  ('periop', 47, 'A client is scheduled for surgery under general anesthesia at 1300. The client asks when to stop eating. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "Stop all food by 0600"}, {"id": "b", "text": "Stop all food by 0900"}, {"id": "c", "text": "Stop all food by 1000"}, {"id": "d", "text": "Stop all food by 1100"}]'::jsonb, '["a"]', 'General anesthesia requires NPO for 6–8 hours to prevent aspiration; stopping at 0600 gives 7 hours before a 1300 surgery. Stopping at 0900 gives only 4 hours.', false),
  ('periop', 48, 'A client asks the nurse why surgery under general anesthesia requires an empty stomach: ''Why can''t I even have a little water this morning?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "NPO keeps the PT/INR stable before the incision."}, {"id": "b", "text": "NPO prevents aspiration during general anesthesia."}, {"id": "c", "text": "NPO lets the antibiotics absorb before the incision."}, {"id": "d", "text": "NPO prevents a surgical site infection after surgery."}]'::jsonb, '["b"]', 'NPO for 6–8 hours before general anesthesia prevents aspiration. Surgical site infection is prevented with antibiotics before the incision, blood glucose control and sterile wound care.', false),
  ('periop', 49, 'During the preoperative interview, a client scheduled for a hip procedure tomorrow says, ''I took my warfarin (Coumadin) last night like I always do.'' Which actions by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Tell the client surgery proceeds as planned"}, {"id": "b", "text": "Explain the surgical risks to the client"}, {"id": "c", "text": "Report the warfarin dose to the surgeon"}, {"id": "d", "text": "Have the client void now"}, {"id": "e", "text": "Verify the PT/INR result"}]'::jsonb, '["c", "e"]', 'Verifying the PT/INR is correct because it is a pre-op lab and warfarin raises bleeding risk; reporting to the surgeon is correct because surgery may be delayed due to bleeding risk. Telling the client surgery proceeds is wrong because it may be delayed; explaining surgical risks is wrong because the surgeon explains the procedure and risks; voiding now is wrong because it is done just before anesthesia, not in response to warfarin.', true),
  ('periop', 50, 'The evening before an open cholecystectomy, the nurse teaches a client how to use the incentive spirometer. Which statement by the client indicates understanding of its purpose?', '[{"id": "a", "text": "The spirometer helps prevent DVT and PE in my legs."}, {"id": "b", "text": "The spirometer helps prevent infection of my incision."}, {"id": "c", "text": "The spirometer helps prevent atelectasis and pneumonia."}, {"id": "d", "text": "The spirometer replaces the need for early ambulation later."}]'::jsonb, '["c"]', 'The incentive spirometer and deep breathing prevent atelectasis and pneumonia. DVT and PE are prevented by early ambulation, SCDs and enoxaparin, and the spirometer does not replace early ambulation, which prevents its own set of complications.', false)
  ) AS v(source_key, display_order, stem, options, correct_answer, rationale, is_multi)
  JOIN _medsurg_seed_map m USING (source_key)
 CROSS JOIN _medsurg_seed_config c;

DO $$
DECLARE
  v_bad text;
BEGIN
  SELECT string_agg(format('%s=%s', m.source_key, coalesce(n.cnt, 0)), ', ')
    INTO v_bad
    FROM _medsurg_seed_map m
    LEFT JOIN (SELECT category, count(*) AS cnt FROM test_questions GROUP BY category) n
      ON n.category = m.category
   WHERE coalesce(n.cnt, 0) <> 50;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'Med-Surg seed post-check failed (expected 50 per topic): %', v_bad;
  END IF;
END $$;

COMMIT;
